// ============================================================
// MyFabmesh.AI — Renderer 2 (refonte)
// ============================================================
// Architecture:
//   - Page "projects": grid of project cards
//   - Page "workspace": one project, 3 vertical step cards
//   - All IPC calls go through window.meshyAPI
// ============================================================

import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { TransformControls } from 'three/addons/controls/TransformControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { FBXLoader } from 'three/addons/loaders/FBXLoader.js';
import { computeBoundsTree, disposeBoundsTree, acceleratedRaycast } from 'three-mesh-bvh';
import { Viewer3D } from './lib/Viewer3D.js';
import { geometriePleine } from './lib/lod-maillage.js';
import { animerGLB, VARIANTES, modeDepuisTexte, allureDeClip, especeDepuisTexte, ESPECES_LISTE, animationsPour } from './lib/locomotion-procedurale.js';
import { creerApercu } from './lib/apercu-animation.js';

// BVH-accelerated raycasting (three-mesh-bvh, MIT). The 3D clone-stamp fires
// hundreds of raycasts per stamp; native three.js raycast is O(triangles) and
// froze on 500k-tri meshes. Patch the prototypes ONCE (guarded so a hot-reload
// or re-import never double-applies), then call geometry.computeBoundsTree() on
// meshes we intend to raycast heavily and geometry.disposeBoundsTree() to free.
if (!THREE.Mesh.prototype.__bvhPatched) {
  THREE.BufferGeometry.prototype.computeBoundsTree = computeBoundsTree;
  THREE.BufferGeometry.prototype.disposeBoundsTree = disposeBoundsTree;
  THREE.Mesh.prototype.raycast = acceleratedRaycast;
  THREE.Mesh.prototype.__bvhPatched = true;
}

// ============================================================
// GARDE WEBGL (cert Store 10.1.2.10)
// ============================================================
// Un contexte WebGL peut échouer (iGPU sur blocklist Chromium, RDP, VM,
// accélération désactivée). `new THREE.WebGLRenderer` LÈVE dans ce cas et
// l'exception remonte au panneau d'erreur global → app inutilisable alors que
// la génération, elle, marche. On centralise la création : en cas d'échec on
// renvoie null et on affiche un encart explicatif dans le conteneur.
function _webglNote(hostEl) {
  if (!hostEl || !hostEl.querySelector) return;
  if (hostEl.querySelector('.webgl-unavailable')) return;
  const n = document.createElement('div');
  n.className = 'webgl-unavailable';
  n.textContent = _i18nT('3D preview unavailable on this device (no WebGL / graphics acceleration). '
    + 'Generation still works and the file is saved to disk.');
  hostEl.appendChild(n);
}
function _mkRenderer(opts, hostEl) {
  // Canvas OPAQUE par defaut. Toutes nos scenes 3D peignent leur propre fond,
  // donc rien ne doit transparaitre de la page. Avec alpha:true, un materiau
  // pourtant declare OPAQUE dans le glTF mais dont la texture baseColor porte
  // un canal alpha (les WebP sortis de TRELLIS-2 en portent un) ecrit cet alpha
  // dans le framebuffer : le melange WebGL est bien desactive, mais le
  // NAVIGATEUR composite ensuite le canvas par-dessus la page avec cet alpha,
  // et le maillage parait semi-transparent. Aucun reglage de materiau ne corrige
  // ca, puisque le probleme est au niveau de la composition du canvas.
  // Un appelant peut toujours redemander explicitement alpha:true.
  opts = Object.assign({ alpha: false }, opts || {});
  try { return new THREE.WebGLRenderer(opts); }
  catch (e) {
    console.warn('[webgl] renderer creation failed:', (e && e.message) || e);
    _webglNote(hostEl);
    return null;
  }
}

// ============================================================
// PASSERELLE IPC + INTERCEPTION « session cloud requise »
// ============================================================
// Cert Store 10.1.2.10 : en mode Cloud, TOUT appel d'outil peut revenir avec
// { needsCloudLogin: true } si aucune session MyFabmesh n'est active. Avant,
// seule la génération d'images ouvrait la modale de connexion — les ~15 autres
// outils (Image→3D, Remove BG, rig, anim, outils mesh…) affichaient « failed /
// unknown » sans jamais proposer de se connecter, ce qui fait passer la
// fonctionnalité pour cassée. On enveloppe donc ces méthodes UNE fois ici :
// réponse needsCloudLogin → modale de connexion → un seul retry.
const _CLOUD_LOGIN_METHODS = [
  'generateImages', 'imageTo3D', 'imageToTrellis',
  'removeBackground', 'img2img', 'maskInpaint', 'autoInpaint', 'imageQuickEdit',
  'meshTool', 'meshSegment', 'materialAdjust', 'resizeMesh',
  'generateExplode3d', 'generateConstructionStages3d',
  'autoRigAI', 'animKimodo', 'animateAI', 'animMotion',
  // Outils cloud qui manquaient (2026-09-30) : sans session, l'erreur « Sign
  // in… » s'affichait au lieu de la fenetre de connexion. Recolor et Age
  // (texVariant) passent par le worker en mode Cloud depuis ce jour.
  'outfitCutout', 'recolor', 'texVariant',
];
const API = (() => {
  const raw = window.meshyAPI;
  // Les objets exposés par contextBridge sont figés : on travaille sur une
  // COPIE de surface (jamais un Proxy, qui lèverait sur une propriété
  // non-writable/non-configurable). Si la copie échoue, on retombe sur l'objet
  // d'origine — l'app doit démarrer quoi qu'il arrive.
  try {
    const keys = Object.keys(raw || {});
    if (keys.length < 20) return raw;
    const copy = {};
    for (const k of keys) copy[k] = raw[k];
    for (const name of _CLOUD_LOGIN_METHODS) {
      const orig = raw[name];
      if (typeof orig !== 'function') continue;
      copy[name] = async (...args) => {
        let r = await orig(...args);
        if (r && r.needsCloudLogin) {
          const ok = await showCloudLoginModal();   // déclaration hoistée
          if (ok) r = await orig(...args);
        }
        return r;
      };
    }
    return copy;
  } catch (_) { return raw; }
})();

// Helper exposé pour les scripts NON-module (index2-edit-tools.js) qui ne
// voient ni la copie `API` ni showCloudLoginModal (portée module). Même
// contrat que le wrapper ci-dessus : appel → needsCloudLogin → modale → un
// seul retry. Transparent hors cloud (sans needsCloudLogin, retour tel quel).
window.showCloudLoginModal = showCloudLoginModal;   // déclaration hoistée
window._withCloudLogin = async function (fn, ...args) {
  let r = await fn(...args);
  if (r && r.needsCloudLogin) {
    const ok = await showCloudLoginModal();
    if (ok) r = await fn(...args);
  }
  return r;
};

// Statut GPU mis en cache au boot (le main le cache aussi). Sert à masquer les
// éléments d'UI purement NVIDIA (moniteur VRAM/température) sur une machine
// sans carte NVIDIA, au lieu de les laisser figés sur « -- ».
window._gpuInfo = null;
(async () => {
  try { window._gpuInfo = await window.meshyAPI?.gpuStatus?.() || null; } catch (_) {}
})();
function _hasNvidia() { return !(window._gpuInfo && window._gpuInfo.hasNvidia === false); }
function _isCloudMode() {
  return ((typeof window._computeMode === 'function') && window._computeMode() === 'cloud') || !_hasNvidia();
}
window._isCloudMode = _isCloudMode;

// MyFabmesh.AI-styled confirm dialog (replaces the OS-native window.confirm
// popup, which looks out of place against the dark UI).
function fabConfirm({ title = 'Confirm', message = '', okLabel = 'Confirm',
                     cancelLabel = 'Cancel', icon = '\u26A0\uFE0F',
                     danger = true } = {}) {
  return new Promise((resolve) => {
    const modal = document.getElementById('modal-confirm');
    const titleEl = document.getElementById('confirm-title');
    const msgEl = document.getElementById('confirm-message');
    const iconEl = document.getElementById('confirm-icon');
    const okBtn = document.getElementById('confirm-ok');
    const cancelBtn = document.getElementById('confirm-cancel');
    if (!modal || !okBtn) { resolve(window.confirm(message)); return; }
    titleEl.textContent = title;
    msgEl.textContent = message;
    iconEl.textContent = icon;
    okBtn.textContent = okLabel;
    cancelBtn.textContent = cancelLabel;
    okBtn.classList.toggle('danger', !!danger);
    function cleanup(v) {
      modal.classList.add('hidden');
      okBtn.removeEventListener('click', onOk);
      cancelBtn.removeEventListener('click', onCancel);
      modal.removeEventListener('click', onBackdrop);
      document.removeEventListener('keydown', onKey);
      resolve(v);
    }
    const onOk = () => cleanup(true);
    const onCancel = () => cleanup(false);
    const onBackdrop = (e) => { if (e.target === modal) cleanup(false); };
    const onKey = (e) => {
      if (e.key === 'Escape') cleanup(false);
      else if (e.key === 'Enter') cleanup(true);
    };
    okBtn.addEventListener('click', onOk);
    cancelBtn.addEventListener('click', onCancel);
    modal.addEventListener('click', onBackdrop);
    document.addEventListener('keydown', onKey);
    modal.classList.remove('hidden');
    setTimeout(() => okBtn.focus(), 50);
  });
}
window.fabConfirm = fabConfirm;

// Forward all console.log/warn/error to main process log file for debugging.
// test_api_client.js already wrapped console.* — we wrap their wrapped versions.
// Helper for action logging — called from button handlers
function logAction(action, details) {
  const ts = new Date().toISOString();
  const msg = `[ACTION] ${action}` + (details ? ' ' + JSON.stringify(details) : '');
  try { window.meshyAPI?.logToFile?.(msg); } catch(_){}
  console.log(msg);
}

// Auto-log all clicks on important buttons (those with data-log-action attr)
document.addEventListener('click', (e) => {
  const btn = e.target.closest('button, [data-log-action]');
  if (!btn) return;
  const id = btn.id || btn.getAttribute('data-log-action') || btn.className;
  // Only log buttons that look like meaningful actions (skip nav, toolbar etc)
  if (id && (id.includes('generate') || id.includes('save') || id.includes('use-for') ||
             id.includes('-btn') || id.includes('export') || id.includes('apply') ||
             id.includes('mv-btn'))) {
    logAction('click:' + (btn.id || id.slice(0,40)));
  }
}, true);

function _installLogForwarder() {
  if (!API?.logToFile) return;
  const origLog = console.log, origWarn = console.warn, origErr = console.error, origInfo = console.info;
  const fmt = (args) => args.map(a => {
    if (a instanceof Error) return a.message + '\n' + (a.stack || '');
    if (typeof a === 'object') { try { return JSON.stringify(a); } catch(_) { return String(a); } }
    return String(a);
  }).join(' ');
  console.log = function (...args) { try { API.logToFile('[log] ' + fmt(args)); } catch(_){} return origLog.apply(console, args); };
  console.info = function (...args) { try { API.logToFile('[info] ' + fmt(args)); } catch(_){} return origInfo.apply(console, args); };
  console.warn = function (...args) { try { API.logToFile('[warn] ' + fmt(args)); } catch(_){} return origWarn.apply(console, args); };
  console.error = function (...args) { try { API.logToFile('[err] ' + fmt(args)); } catch(_){} return origErr.apply(console, args); };
  window.addEventListener('error', (e) => { try { API.logToFile('[uncaught] ' + e.message + ' @ ' + e.filename + ':' + e.lineno); } catch(_){} });
  window.addEventListener('unhandledrejection', (e) => { try { API.logToFile('[unhandledrejection] ' + (e.reason?.message || e.reason)); } catch(_){} });
}
_installLogForwarder();

