// 2026-06-13: reuse the existing pushJob/completeJob "Running task"
// modal (same UX as image-to-3D / rig / refine) for the animation
// retarget. Active jobs in this session are tracked here so the
// streaming anim:progress channel can keep updating the right one.
let _activeAnimJob = null;
if (window.meshyAPI?.onAnimProgress) {
  window.meshyAPI.onAnimProgress((data) => {
    if (_lotAnim && data?.source === 'motion') {
      const tranche = 100 / _lotAnim.total;
      const dedans = Math.min(0.95, Math.max(0, (data.pct || 0) / 100));
      _progresLot(_lotAnim.jobId, _lotAnim.index * tranche + dedans * tranche,
        `${_lotAnim.type} (${_lotAnim.index + 1}/${_lotAnim.total}) — ${data.msg || ''}`);
      return;
    }
    if (!_activeAnimJob || typeof updateJobProgress !== 'function') return;
    // Drive the progress bar by phase (no real % from the backend yet).
    const phaseToPct = { start: 5, search: 15, match: 25, retarget: 60, bake: 85, judge: 95, done: 100 };
    const pct = (typeof data?.pct === 'number' && data.pct > 0)
      ? data.pct : (phaseToPct[data?.phase] ?? null);
    if (pct != null) {
      try { updateJobProgress(_activeAnimJob.id, pct, data.msg); } catch (_) {}
    }
  });
}

// Generate Animation — PARITE WEB (2026-09-28) : les clips coches sont
// calcules EN LIGNE par le moteur de production (5 credits par clip), un
// travail unique qui passe de 1/N a N/N. Les anciens moteurs locaux ne sont
// plus proposes : leurs gestionnaires restent dans le main, sans bouton.
let _lotAnim = null;   // { jobId, index, total, type } pendant un lot
function _progresLot(jobId, pct, sousTitre) {
  const j = state.jobs?.find((x) => x.id === jobId);
  if (!j || j.status !== 'running') return;
  j.bridgeReporting = true;
  if (pct > (j.progress || 0)) j.progress = Math.min(99, pct);
  if (sousTitre) j.subtitle = String(sousTitre).slice(0, 130);
  try { renderJobs(); } catch (_) {}
}
document.getElementById('ws-generate-anim')?.addEventListener('click', async () => {
  const status = document.getElementById('ws-anim-status');
  const btn = document.getElementById('ws-generate-anim');
  const setStatus = (msg, isErr = false) => {
    if (status) {
      status.textContent = msg;
      status.style.color = isErr ? 'var(--danger, #f55)' : 'var(--text-2)';
    }
  };
  const proj = state.currentProject;
  if (!proj) return;
  // Le rig utilise est CELUI QUE L'UTILISATEUR VOIT dans l'apercu « squelette
  // source » (`selectedRigPath`, ecrit par « Used for Animation »).
  const rigPath = proj.selectedRigPath || proj.activeRigPath || _rigLePlusRecent(proj);
  if (!rigPath) {
    customError(_i18nT('You need a rigged mesh first. Generate a Rig in Step 3, then come back.'), _i18nT('No rig available'));
    return;
  }
  // liste du selecteur : « walk », « walk__sneak » (variante), « attack »…
  const types = _animSelection.map(_nomClipSelection);
  if (!types.length) {
    showToast(_i18nT('Nothing selected: choose an animation and a variant, then click Add.'), 'info', 4000);
    return;
  }
  // Moteur procedural (2026-09-28) : idle / walk / run / virages calcules ICI, en une
  // fraction de seconde, gratuitement, dans UN fichier « locomotion » (menu de choix au
  // lecteur). Seuls attack / death / fly passent encore par l'IA en ligne.
  const allures = types.filter((t) => ALLURES_PROCEDURALES.includes(t.split('__')[0]));
  // Lot commun a TOUT le clic (allures + clips IA) : une seule version, comme sur le web
  const lot = `d${Date.now().toString(36)}`;
  if (allures.length) {
    btn.disabled = true;
    try {
      setStatus(_i18nT('Generating…'));
      const brut = await API.readMeshFile(rigPath);
      if (!brut) throw new Error(_i18nT('Rig file not found.'));
      const t0 = performance.now();
      const { glb, infos } = animerGLB(brut, { allures, mode: _modeAnim(), espece: _especeAnim() });
      console.log('[locomotion] ' + allures.join('+') + ' en ' + Math.round(performance.now() - t0) + ' ms', infos);
      const rigStem = rigPath.split(/[\\/]/).pop().replace(/\.glb$/i, '');
      const filename = `locomotion_${lot}_${Date.now()}__${rigStem}.glb`;
      const glbPath = await API.getMeshPath('animated/' + filename);
      const w = await API.saveBuffer({ path: glbPath, buffer: glb });
      if (!w?.success) throw new Error(w?.error || 'write failed');
      const rigL = (proj.rigs || []).find((r) => r.path === rigPath);
      proj.animations = proj.animations || [];
      proj.animations.unshift({
        id: filename, batchId: lot, type: 'locomotion', filename, path: glbPath,
        url: 'file:///' + glbPath.replace(/\\/g, '/'),
        motionLabel: 'Locomotion: ' + allures.map(_libelleClip).join(', '),
        created: new Date().toISOString(), mtime: Date.now(),
        rigPath, rigFilename: rigL?.filename, sourceImage: rigL?.sourceImage,
      });
      _selectedAnim = null;
      _selectedBatch = lot;
      _selectedGait = null;
      try { renderAnimVersions(proj); } catch (_) {}
      setStatus(`${_i18nT('Done')} — ${allures.length} ${_i18nT('animations')}`);
      const carte = document.getElementById('step-card-animation');
      const edition = carte?.querySelector('.stage-edit');
      if (edition) edition.open = true;
    } catch (err) {
      setStatus(`Error: ${err?.message || err}`, true);
      customError(String(err?.message || err), _i18nT('Animation failed'));
      btn.disabled = false;
      return;
    } finally {
      btn.disabled = false;
    }
    types.splice(0, types.length, ...types.filter((t) => !ALLURES_PROCEDURALES.includes(t.split('__')[0])));
    if (!types.length) return;
  }
  // Le type d'asset du projet choisit le squelette de reference du modele.
  const assetType = proj.assetType || document.getElementById('ws-asset-type')?.value || '';
  const batchId = lot;
  const icones = { pending: '◻', running: '⏳', done: '✓', failed: '✗' };
  const etat = types.map(() => 'pending');
  const liste = () => types.map((t, i) => `${icones[etat[i]]} ${t}`).join('\n');
  const job = (typeof pushJob === 'function')
    ? pushJob(`Animate ${types.join('+')}: ${proj.name}`, null, {
        Engine: 'MyFabmesh.AI Motion',
        Animations: liste(),
        'Source rig': (rigPath || '').split(/[\\/]/).pop(),
        Batch: `0/${types.length}`,
      }, 180000 * types.length, { sourceImageUrl: rigPath, projectName: proj.name })
    : null;
  const majJob = () => {
    const j = job && state.jobs?.find((x) => x.id === job.id);
    if (!j) return;
    j.params = j.params || {};
    j.params.Animations = liste();
    j.params.Batch = `${etat.filter((e) => e === 'done').length}/${types.length}`;
  };
  const rig = (proj.rigs || []).find((r) => r.path === rigPath);
  btn.disabled = true;
  let faits = 0;
  try {
    for (const [i, type] of types.entries()) {
      etat[i] = 'running';
      majJob();
      _lotAnim = job ? { jobId: job.id, index: i, total: types.length, type } : null;
      setStatus(`${type} (${i + 1}/${types.length})…`);
      if (job) _progresLot(job.id, (i / types.length) * 100 + 2, `${type} (${i + 1}/${types.length})`);
      const r = await API.animMotion({ meshPath: rigPath, animType: type, assetType, projectName: proj.name, batchId });
      if (!r?.success) {
        etat[i] = 'failed';
        majJob();
        const msg = r?.error || 'unknown';
        setStatus(`${type} : ${msg}`, true);
        if (job) { try { completeJob(job.id, false, msg); } catch (_) {} }
        if (!job?.cancelled) reportPipelineError(msg, `Animate failed (${type})`);
        return;
      }
      faits++;
      etat[i] = 'done';
      majJob();
      const filename = r.glbPath.split(/[\\/]/).pop();
      proj.animations = proj.animations || [];
      proj.animations.unshift({
        id: filename,
        batchId,
        type,
        filename,
        path: r.glbPath,
        url: 'file:///' + r.glbPath.replace(/\\/g, '/'),
        motionLabel: type,
        created: new Date().toISOString(),
        mtime: Date.now(),
        rigPath,
        rigFilename: rig?.filename,
        sourceImage: rig?.sourceImage,
      });
      try { renderAnimVersions(proj); } catch (_) {}
      try { _selectAnim?.(proj.animations[0]); } catch (_) {}
      try { window.dispatchEvent(new CustomEvent('anim:new', { detail: proj.animations[0] })); } catch (_) {}
      if (job) _progresLot(job.id, (faits / types.length) * 100, `${faits}/${types.length} done`);
    }
    setStatus(`${_i18nT('Done')} — ${faits}/${types.length}`);
    if (job) { try { completeJob(job.id, true); } catch (_) {} }
    const carte = document.getElementById('step-card-animation');
    const edition = carte?.querySelector('.stage-edit');
    if (edition) edition.open = true;
  } catch (err) {
    const msg = String(err?.message || err);
    setStatus(`Error: ${msg}`, true);
    if (job) { try { completeJob(job.id, false, msg); } catch (_) {} }
  } finally {
    _lotAnim = null;
    btn.disabled = false;
    try { window._refreshTopbarCredits?.(); } catch (_) {}
  }
});

// ============================================================
// HELPER: reload current project from disk
// ============================================================
async function reloadCurrentProject() {
  if (!state.currentProject) return;
  const name = state.currentProject.name;
  const sanitizedName = name.replace(/[^a-zA-Z0-9_-]/g, '_');
  await refreshProjectsPage();
  // Try exact match first, then sanitized match (spaces → underscores)
  // Plusieurs entrees peuvent correspondre (marqueur de projet vide « Mobilier design » + dossier reel « Mobilier_design ») : on prend celle qui a du contenu.
  const _candidats = state.projects.filter(p => p.name === name || p.name === sanitizedName
    || p.name.replace(/[^a-zA-Z0-9_-]/g, '_') === sanitizedName);
  const _poids = (p) => (p.images?.length || 0) + (p.meshes?.length || 0) + (p.rigs?.length || 0) + (p.animations?.length || 0);
  const refreshed = _candidats.sort((a, b) => _poids(b) - _poids(a))[0];
  if (refreshed) console.log('[reload] matched project:', refreshed.name, 'for requested:', name);
  else console.log('[reload] NO MATCH for project:', name, '(sanitized:', sanitizedName, ') in:', state.projects.map(p => p.name).slice(0, 10));
  if (!refreshed) {
    // The project no longer matches anything in the projects scan — most
    // likely the user just deleted its last image. Don't leave the UI
    // frozen on the stale data: present an empty shell so they can
    // regenerate from scratch via the "Create new" stage (which
    // setStageOpenState auto-expands when images.length === 0).
    console.log('[reload] empty shell for', name);
    const emptyShell = {
      name: state.currentProject.name,
      images: [], meshes: [], rigs: [],
      animations: [],
            _reloadTs: Date.now(),
    };
    state.currentProject = emptyShell;
    populateWorkspace(emptyShell);
    return;
  }
  if (refreshed) {
    refreshed._reloadTs = Date.now();
    // Carry over multiview data + 2-view back photos (not on disk in
    // a way reload would naturally pick up — they live in _backphotos/
    // and are referenced by per-image map state)
    if (state.currentProject._multiviews) refreshed._multiviews = state.currentProject._multiviews;
    if (state.currentProject._backPhotos) refreshed._backPhotos = state.currentProject._backPhotos;
    if (state.currentProject._stages) refreshed._stages = state.currentProject._stages;
    if (state.currentProject._stagesList) refreshed._stagesList = state.currentProject._stagesList;
    state.currentProject = refreshed;
    console.log('[reload] images:', refreshed.images?.length, 'meshes:', refreshed.meshes?.length);
    populateWorkspace(refreshed);

    // Open "Edit selected" stage for steps that have content.
    // Use a short timeout (not rAF) so populateWorkspace's own rAFs finish first.
    setTimeout(() => {
      const steps = [
        { id: 'step-card-image',     has: refreshed.images?.length     > 0 },
        { id: 'step-card-mesh',      has: refreshed.meshes?.length     > 0 },
        { id: 'step-card-rig',       has: refreshed.rigs?.length       > 0 },
        { id: 'step-card-animation', has: refreshed.animations?.length > 0 },
      ];
      for (const s of steps) {
        if (!s.has) continue;
        const card = document.getElementById(s.id);
        if (!card) continue;
        card.classList.remove('collapsed', 'disabled');
        const createStage = card.querySelector('.stage-create');
        const editStage = card.querySelector('.stage-edit');
        if (createStage) createStage.open = false;
        if (editStage) editStage.open = true;
      }
      // Check multiview after the stage is opened (previewImagePath is now set)
      _checkMultiviewForCurrentImage();
    }, 150);

    _checkMultiviewForCurrentImage();
  }
  // If the user just edited a multi-view, offer to regenerate the others.
  // Deferred so the reload UI settles first.
  setTimeout(_offerMultiviewRegenerate, 250);
}

// ============================================================
// JOBS BUBBLE
// ============================================================
// Expected duration per job kind, in ms — used to fake a smooth progress bar.
// Values are calibrated against real observed runs on a 16 GB RTX 5080
// with torch 2.7.1+cu128. If you see the progress bar reach 90% and stall
// for a long time, bump the matching value here.
const JOB_EXPECTED_MS = {
  'image':   30000,   // ~30 s for a 1-image RealVisXL batch at 25 steps
  'img2img': 30000,
  'bg':      8000,
  'mesh':    90000,   // ~90 s for TripoSR 512 + bake_texture (baked UV)
  'rig':     120000,  // ~2 min: UniRig skel + swap + voxel skin + anims bake
  'inpaint': 180000,
};

function inferKind(name) {
  const n = name.toLowerCase();
  if (n.includes('inpaint') || n.includes('mask')) return 'inpaint';
  if (n.includes('3d') || n.includes('mesh')) return 'mesh';
  if (n.includes('rig')) return 'rig';
  if (n.includes('background')) return 'bg';
  if (n.includes('modify') || n.includes('img2img')) return 'img2img';
  return 'image';
}

// Subscribe ONCE to stdout progress markers from the Python bridges so
// the job progress bar reflects actual work instead of a fake time-based
// climb. Bridges emit lines like:
//   LOCAL_TRIPOSR_PROGRESS: 65 some_label
// We parse the integer and clamp the matching running job to at least
// that value.
if (!window.__fabmesh_ai3d_listener_installed && window.meshyAPI && window.meshyAPI.onAI3DProgress) {
  window.__fabmesh_ai3d_listener_installed = true;
  // Match ONLY bridge-level overall emitters (LOCAL_SF3D_PROGRESS,
  // LOCAL_TRIPOSR_PROGRESS, LOCAL_TRIPOSG_PROGRESS, LOCAL_MESHY_PROGRESS,
  // LOCAL_IMG_PROGRESS, LOCAL_JUGG_PROGRESS, LOCAL_REALVIS_PROGRESS).
  // The previous regex `/_PROGRESS:/` also matched MULTIVIEW_PROGRESS and
  // TEXTURE_*_PROGRESS that sub-scripts emit via slog.progress(). Those
  // are sub-phase percentages (0-100 *within* multiview, not overall), so
  // treating them as overall snapped the bar to ~90% as soon as multiview
  // finished — hiding the full refine phase (the "stuck at 90%" bug).
  const PROG_RE = /\bLOCAL_[A-Z0-9_]+_PROGRESS:\s*(\d{1,3})/;
  // Sub-script lines are forwarded by the bridge with a "LOCAL_SF3D: " prefix;
  // we must NOT scrape their embedded sub-phase percentages. The bridge
  // already re-emits a remapped LOCAL_SF3D_PROGRESS: line for those.
  const SUB_PREFIX = 'LOCAL_SF3D: ';
  window.meshyAPI.onAI3DProgress((msg) => {
    try {
      if (!msg || typeof msg !== 'string') return;
      // DIAGNOSTIC: log every chunk containing a progress marker, with the
      // matched value — reveals whether the bar stalls because the bridge
      // sent nothing, or because the renderer rejected a line, or because
      // main.js batched updates. Filter to progress-relevant chunks so the
      // console doesn't drown.
      if (msg.indexOf('_PROGRESS:') !== -1 || msg.indexOf('FABMESH_SUBPCT') !== -1) {
        console.log('[progress-diag]', Date.now(), JSON.stringify(msg.slice(0, 300)));
      }
      // Ignore sub-phase raw percentages — the bridge already remaps those
      // into proper LOCAL_SF3D_PROGRESS overall values. Without this guard
      // a 99% FABMESH_SUBPCT (tile 6/6 of refine) would incorrectly snap
      // the bar to 99% while the overall slice only covers 60..99.
      if (msg.indexOf('FABMESH_SUBPCT') !== -1) return;
      // msg may be a multi-line chunk — parse line by line so sub-script
      // forwarded lines (prefixed `LOCAL_SF3D: `) don't leak their inner
      // `MULTIVIEW_PROGRESS` values as fake overall percentages.
      const lines = msg.split(/\r?\n/);
      let reported = -1;
      for (const rawLine of lines) {
        if (!rawLine) continue;
        // Forwarded sub-script lines: the bridge prefixes them with
        // "LOCAL_SF3D: " before printing. Their embedded *_PROGRESS
        // markers are SUB-PHASE values — skip.
        if (rawLine.startsWith(SUB_PREFIX)) continue;
        const mm = PROG_RE.exec(rawLine);
        if (mm) {
          const v = parseInt(mm[1], 10);
          console.log('[progress-diag] matched line:', rawLine.trim(), '-> v=', v);
          if (v > reported) reported = v;
        } else if (rawLine.indexOf('_PROGRESS:') !== -1) {
          console.log('[progress-diag] NO MATCH but has _PROGRESS:', rawLine.trim());
        }
      }
      if (reported < 0) return;
      reported = Math.max(0, Math.min(99, reported));
      // Synthesize a match object so the downstream code path (which used
      // to read `m`) still compiles. We only need `reported` below.
      const m = [null, String(reported)];
      if (!m) return;
      // Apply to the most recent running job whose kind is mesh/rig —
      // bridges that emit these markers are all in the 3D/rig pipeline.
      for (let i = state.jobs.length - 1; i >= 0; i--) {
        const j = state.jobs[i];
        if (j.status === 'running' && (j.kind === 'mesh' || j.kind === 'rig')) {
          // Mark that we've seen a real bridge progress event. Once the
          // bridge starts reporting, the local smooth-climb timer should
          // stop fighting it: its cap at 90 hides the refine phase (60-99)
          // that now emits real values, so the bar would sit at 90% for
          // minutes even though the bridge is actively moving.
          j.bridgeReporting = true;
          if (reported > j.progress) {
            j.progress = reported;
            renderJobs();
          }
          break;
        }
      }
    } catch (e) { /* ignore */ }
  });
}

// Expose jobs API on window so classic-script helpers (index2-edit-tools.js)
// can push/complete jobs in the same queue the rest of the app uses.
// Because index2.js is an ES module, plain `function foo()` declarations
// don't land on `window`; we wire them up explicitly below after definition.
/* VIGNETTE DES TRAVAUX = L'ELEMENT DE L'ETAPE D'AVANT (2026-09-30, user : « l'icone de la vignette doit correspondre a l'image de
 * l'item utilise dans l'etape d'avant »). Un travail qui n'a pas fourni sa propre image prend celle de ce qu'il transforme :
 * animation -> le rig utilise (sa vignette), rig ou operation de maillage -> le maillage affiche. Les travaux d'image gardent
 * leur logique (image source passee a pushJob). Rend une adresse ou null. */
function _vignetteAmont(kind) {
  try {
    const p = state.currentProject; if (!p) return null;
    if (kind === 'anim') {
      const r = _rigAffiche(); if (!r) return null;
      if (typeof _vignetteDuRig === 'function') return _vignetteDuRig(r, p) || null;
      const t = r.thumb || r.sourceImage; return t ? _toFileUrl(t) : null;
    }
    if (kind === 'rig' || kind === 'mesh') {
      const m = p.previewMeshPath || p.selectedMeshPath;
      return m ? _meshJobThumb(m) : null;
    }
  } catch (_) { /* pas de vignette */ }
  return null;
}
function pushJob(name, onCancel, params, expectedMsOverride, opts, _cloudOpts) {
  // INSTRUMENTATION (2026-09-24). L'utilisateur voit une generation d'image
  // se lancer seule a chaque mesh. Trois hypotheses ecartees par la mesure :
  // le bouton image ne la declenche pas, la reprise ne concerne que les rigs,
  // la file d'attente rend `ok` en mode cloud. On enregistre donc la PILE
  // D'APPEL — les journaux partent vers R2 a chaque fin de travail, la
  // prochaine occurrence nommera son appelant au lieu de nous faire deviner.
  try {
    if (/^Generate images/i.test(String(name || ''))) {
      var _pile = (new Error().stack || '').split(String.fromCharCode(10));
      console.warn('[trace] Generate images pousse par :', _pile.slice(1, 6).join(' | '));
    }
  } catch (_) {}
  // Cross-signature guard. Cloud's pushJob is
  //   (name, onCancel, params, expectedMsOverride, startedAtOverride, opts)
  // — a future cloud->desktop sync paste of a 6-arg call would land opts in
  // _cloudOpts (slot 6) and a number (or undefined) in slot 5. Detect that
  // shape and shift opts back into place so the projectName/sourceImageUrl
  // snapshot still survives. Also handles the legacy case where opts was
  // accidentally passed in the expectedMsOverride slot.
  if (_cloudOpts && typeof _cloudOpts === 'object') {
    opts = _cloudOpts;
  } else if (opts === undefined && expectedMsOverride
             && typeof expectedMsOverride === 'object') {
    opts = expectedMsOverride;
    expectedMsOverride = undefined;
  }
  const id = ++state.jobIdCounter;
  const kind = inferKind(name);
  const expected = (typeof expectedMsOverride === 'number' && expectedMsOverride > 0)
    ? expectedMsOverride
    : (JOB_EXPECTED_MS[kind] || 60000);
  // SNAPSHOT the source image at launch time. Without this, the Job
  // Details modal reads state.currentProject.* at RENDER time, which
  // may have changed if the user clicked another version thumbnail
  // between launch and the modal refresh (bug: modal shows wrong
  // thumb because the user switched selected image mid-job).
  const o = opts || {};
  // Resolve a stable project label ONCE: callers may pass it through opts,
  // else snapshot whatever the current project is at launch (the user can
  // switch projects mid-job, and the popup must keep pointing at the project
  // that started the job — not whichever is open now).
  const projectName = o.projectName || (state.currentProject ? state.currentProject.name : null);
  const job = {
    id,
    name,
    kind,
    progress: 5,
    status: 'running',
    startedAt: Date.now(),
    expectedMs: expected,
    onCancel: onCancel || null,
    tickTimer: null,
    params: params || null,
    sourceImageUrl: o.sourceImageUrl || _vignetteAmont(kind),
    projectName,
    // 2026-06-02 — mirror cloud's `sourceProject` field so _jobProjectName
    // (the cross-project navigation helper used by the running-job tile click)
    // has a reliable source independent of the legacy title-regex parse,
    // which breaks on project names containing colons / em-dashes
    // (e.g. "Orc rose: chapter 2" was matched as project="chapter 2").
    sourceProject: o.sourceProject || projectName,
    assetKind: o.assetKind || null,
    // SOUS-TACHE (2026-09-25). Un travail peut n'etre qu'une ETAPE d'un autre
    // (le worker insere une ligne `jobs` par operation interne : rectify,
    // back-view, text2image). Sans ce rattachement l'utilisateur voyait deux
    // popups pour une seule action (« Generate 3D » + « Generate images ») et
    // ne pouvait pas dire laquelle appartenait a l'autre. Le parent est
    // designe par son identifiant LOCAL (job.id) ou par son nom si l'appelant
    // n'en a pas. Voir renderJobs / renderStepProgressWidgets pour le rendu.
    parentJobId: o.parentJobId || null,
    parentJobName: o.parentJobName || null,
  };
  // Smoothly climb from 5 to 90% over expected duration UNTIL the bridge
  // starts emitting real progress events. After that, the bridge is the
  // single source of truth (it reaches 99% gradually across multi-view,
  // SF3D, UV projection, and SDXL refine). The old behaviour kept the
  // timer running to 90% and hid the bridge's more accurate values —
  // producing the "jumps to 97% then stalls" feel the user complained
  // about: the bar was the timer, not the pipeline.
  // IMPORTANT: never DECREASE progress — real values always win.
  job.bridgeReporting = false;
  job.tickTimer = setInterval(() => {
    if (job.status !== 'running') { clearInterval(job.tickTimer); return; }
    if (job.bridgeReporting) return; // bridge is driving the bar now
    const elapsed = Date.now() - job.startedAt;
    const estimated = Math.min(90, 5 + (elapsed / expected) * 85);
    job.progress = Math.max(job.progress, estimated);
    renderJobs();
  }, 800);
  state.jobs.push(job);
  renderJobs();
  // Auto-open the details modal so the user sees the live progress + cancel button
  // without having to click the bubble in the corner.
  // SAUF une REPRISE apres rechargement (params.Resumed) : avec plusieurs
  // travaux repris, seule la derniere fiche restait visible (« une analyse
  // en cours, c'est faux, j'en ai plusieurs », 2026-09-27). On ouvre le
  // panneau des travaux, qui les montre tous.
  if (params && params.Resumed) {
    try {
      document.getElementById('jobs-panel-2')?.classList.remove('hidden');
      document.getElementById('jobs-bubble-2')?.classList.add('hidden');
    } catch (_) {}
  } else {
    try { openJobDetails(id); } catch (e) {}
  }
  return job;
}

// Resolve a job's owning project name. Mirrors cloud's _jobProjectName
// (cloud/public/app/index2.js). Priority:
//   1. j.params.Project  — set by some legacy MCP paths
//   2. j.sourceProject   — set by pushJob (preferred, snapshot at launch)
//   3. j.projectName     — current pushJob field, equivalent to sourceProject
//   4. title-regex tail  — last-ditch fallback for jobs that pre-date the
//                          opts param (kept for backwards-compat). Fragile
//                          on names with ':' or '—' so the above sources
//                          should hit first.
function _jobProjectName(j) {
  if (!j) return null;
  if (j.params && j.params.Project) return j.params.Project;
  if (j.sourceProject) return j.sourceProject;
  if (j.projectName) return j.projectName;
  const m = (j.name || '').match(/[:—–-]\s*([^:—–-]+)\s*$/);
  if (m) return m[1].trim();
  return null;
}
window._jobProjectName = _jobProjectName;

/** SOUS-TACHES (2026-09-25). Un travail rattache a un autre ne doit pas
 *  occuper sa propre tuile : l'utilisateur voyait « Generate 3D » ET
 *  « Generate images » pour un seul clic. On resout donc le parent une fois,
 *  puis les rendus groupent les enfants sous lui.
 *  Retourne le job parent, ou null si ce job est autonome. */
function _jobParent(j) {
  if (!j) return null;
  const pid = j.parentJobId;
  if (pid != null) {
    const p = state.jobs.find(x => x.id === pid);
    if (p && p !== j) return p;
  }
  if (j.parentJobName) {
    // Repli par nom : les jobs repris du serveur n'ont pas de parentJobId
    // (le worker ne stocke pas la filiation), seulement le nom du parent.
    const p = state.jobs.find(x => x !== j && x.name === j.parentJobName);
    if (p) return p;
  }
  return null;
}
window._jobParent = _jobParent;

/** Les enfants d'un job, dans l'ordre d'apparition. Un enfant dont le parent
 *  a disparu de state.jobs retombe comme job autonome (mieux vaut une tuile
 *  orpheline qu'une barre de progression invisible). */
function _jobChildren(parentId) {
  return (state.jobs || []).filter(x => x.parentJobId === parentId);
}

/* FIN D'UN PARENT DONT UNE SOUS-TACHE TOURNE ENCORE (2026-09-26).
 *
 * L'ancienne version de completeJob passait le parent a « done » (vert,
 * 100 %) PUIS sortait avant d'en programmer le retrait : quand la sous-tache
 * finissait, personne ne reprenait le parent et sa tuile restait affichee a
 * jamais (« Generate back views » fige a 100 %, signale par l'utilisateur).
 * Desormais le parent reste « en cours » et sa fin est MEMORISEE ; la fin de
 * son dernier enfant la rejoue (_terminerParentEnAttente). Au plus 30 s
 * d'attente : un enfant qui survit a son parent n'etait sans doute pas le
 * sien (rattachement par projet = heuristique) ; il est detache et devient
 * une tuile autonome. Rend true si la fin est differee. */
function _finDiffereeSiEnfants(j, success, errorMessage) {
  let enCours = [];
  try { enCours = _jobChildren(j.id).filter(c => c.status === 'running'); } catch (_) {}
  if (!enCours.length) return false;
  j._finEnAttente = { success, errorMessage };
  j.progress = Math.max(j.progress || 0, 95);
  if (!j._attenteTimer) {
    j._attenteTimer = setTimeout(() => {
      j._attenteTimer = null;
      const f = j._finEnAttente;
      if (!f || !state.jobs.includes(j)) return;
      j._finEnAttente = null;
      try {
        for (const c of _jobChildren(j.id)) {
          if (c.status === 'running') { c.parentJobId = null; c.parentJobName = null; }
        }
      } catch (_) {}
      completeJob(j.id, f.success, f.errorMessage);
    }, 30000);
  }
  try { renderJobs(); } catch (_) {}
  return true;
}

/** Fin d'une sous-tache : si son parent n'attendait plus qu'elle, on le
 *  termine avec l'issue qu'il avait memorisee. */
function _terminerParentEnAttente(enfant) {
  try {
    const par = enfant.parentJobId != null
      ? state.jobs.find(x => x.id === enfant.parentJobId) : null;
    if (!par || !par._finEnAttente) return;
    if (_jobChildren(par.id).some(c => c.status === 'running')) return;
    if (par._attenteTimer) { clearTimeout(par._attenteTimer); par._attenteTimer = null; }
    const f = par._finEnAttente;
    par._finEnAttente = null;
    completeJob(par.id, f.success, f.errorMessage);
  } catch (_) {}
}

/** Un enfant ne s'affiche jamais comme tuile de premier niveau : il est
 *  rendu SOUS son parent. Les listes principales filtrent avec ce predicat. */
function _estSousTache(j) {
  return _jobParent(j) !== null;
}

/* ONGLETS « EN COURS » / « TRAVAUX FINIS » (2026-09-26, demande de
 * l'utilisateur). Un travail termine REMONTE en tete de la liste, reste
 * visible ~4 s, puis passe dans l'onglet « Travaux finis ». L'historique est
 * garde dans CE navigateur (localStorage, 50 entrees) pour survivre a un
 * rechargement ; une vignette blob:/data: ne survit pas, elle n'est pas
 * gardee. Les sous-taches n'y figurent pas : elles appartiennent a leur
 * parent. */
const _CLE_JOBS_TERMINES = 'fabmesh_jobs_termines_v1';
const _DELAI_ARCHIVAGE_MS = 4000;
state.jobsTermines = (() => {
  try {
    const a = JSON.parse(localStorage.getItem(_CLE_JOBS_TERMINES) || '[]');
    return Array.isArray(a) ? a.slice(0, 50) : [];
  } catch (_) { return []; }
})();
state.jobsOnglet = 'encours';

/* Icones des etapes (meme dessin que les en-tetes d'etape du HTML). */
const _ICONES_ETAPES = {
  1: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="14" rx="2.5"/><circle cx="9" cy="10" r="1.7"/><path d="M4.5 17.5l5-5 3.5 3.5 2.5-2.5 4 4"/></svg>',
  2: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2.8l8.2 4.6v9.2L12 21.2l-8.2-4.6V7.4z"/><path d="M12 12l8.2-4.6M12 12v9.2M12 12L3.8 7.4"/><path d="M8 5.1l8.1 4.6M16 5.1L7.9 9.7" stroke-opacity="0.45"/></svg>',
  3: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="4.3" r="2.1"/><path d="M12 6.4v7.2M12 8.8l-4.3 3.1M12 8.8l4.3 3.1M12 13.6l-3.2 6.4M12 13.6l3.2 6.4"/><g fill="currentColor" stroke="none"><circle cx="7.7" cy="11.9" r="1.3"/><circle cx="16.3" cy="11.9" r="1.3"/><circle cx="12" cy="13.6" r="1.3"/><circle cx="8.8" cy="20" r="1.2"/><circle cx="15.2" cy="20" r="1.2"/></g></svg>',
  4: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="15" cy="4.3" r="2.1"/><path d="M14 7.2l-2.3 5.2 3.2 3-1.3 5.6M11.7 12.4l-3.4 1.2M14 7.9l4.1 2.4M14.9 15.4l4.3 1.4"/><path d="M2.8 8.5h4.4M2 12.2h4.3M3.4 16h3.4" stroke-opacity="0.55"/></svg>',
};
/** Anneau de categorie d'une tuile de travail : autour de la miniature, ou icone de l'etape. */
function _iconeCategorieHtml(etape, vignetteHtml) {
  const n = (etape >= 1 && etape <= 4) ? etape : 0;
  const dedans = vignetteHtml || (n ? _ICONES_ETAPES[n] : '');
  if (!dedans) return '';
  return `<span class="job-cat" data-cat="${n}">${dedans}</span>`;
}

/* VIGNETTE D'UN TRAVAIL (2026-09-27, user : « certaines generations n'ont pas
 * d'image »). Trois trous : un rig repris passait l'URL du GLB comme image
 * (image cassee), le rig et la reprise d'une generation n'en passaient
 * aucune, et une URL signee expire en 24 h. On garde l'image source si c'en
 * est une ; sinon, et en repli si elle ne charge plus, l'image du projet. */
function _vignetteProjet(nom) {
  const p = (state.projects || []).find(x => x && x.name === nom)
    || (state.currentProject && state.currentProject.name === nom ? state.currentProject : null);
  const t = p && p.thumb;
  if (!t) return '';
  return /^(https?:|data:|blob:)/i.test(String(t)) ? String(t) : (typeof _toFileUrl === 'function' ? _toFileUrl(t) : String(t));
}
function _vignetteTravailHtml(url, nomProjet) {
  const repli = _vignetteProjet(nomProjet);
  let u = url ? String(url) : '';
  if (/\.(glb|gltf|fbx|obj|ply)(\?|#|$)/i.test(u)) u = '';
  if (u && !/^(https?:|data:|blob:)/i.test(u) && typeof _toFileUrl === 'function') u = _toFileUrl(u);
  const src = u || repli;
  if (!src) return '';
  return `<img src="${escapeHtml(src)}" alt="" class="step-progress-item-thumb"`
    + (repli && repli !== src ? ` data-repli="${escapeHtml(repli)}"` : '') + `/>`;
}
// Une vignette qui ne charge plus (URL signee expiree) passe sur l'image du
// projet, puis disparait plutot que de rester cassee.
document.addEventListener('error', (e) => {
  const img = e.target;
  if (!img || !img.classList || !img.classList.contains('step-progress-item-thumb')) return;
  if (img.dataset.repli && img.getAttribute('src') !== img.dataset.repli) {
    img.src = img.dataset.repli; img.dataset.repli = '';
  } else {
    img.remove();
  }
}, true);

function _sauverJobsTermines() {
  try { localStorage.setItem(_CLE_JOBS_TERMINES, JSON.stringify((state.jobsTermines || []).slice(0, 50))); } catch (_) {}
}

/** Place un travail termine dans l'historique (jamais une sous-tache). */
function _archiverJob(j) {
  if (!j || j.parentJobId != null) return;
  const _base = (n) => String(n || '').replace(' (resumed)', '');
  const deja = (state.jobsTermines || []).some(e => e.projectName === (_jobProjectName(j) || null)
    && _base(e.name) === _base(j.name) && j.startedAt && e.startedAt
    && Math.abs(e.startedAt - j.startedAt) < 2 * 60 * 1000);
  if (deja) return;
  const vignette = j.sourceImageUrl && /^(https?:|file:)/i.test(String(j.sourceImageUrl))
    ? j.sourceImageUrl : null;
  const entree = {
    finiId: 'f' + Date.now().toString(36) + '_' + j.id,
    name: j.name,
    statut: j.cancelled ? 'annule' : (j.status === 'error' ? 'echec' : 'ok'),
    startedAt: j.startedAt || null,
    finiLe: Date.now(),
    projectName: _jobProjectName(j) || null,
    sourceImageUrl: vignette,
    errorMessage: j.errorMessage ? String(j.errorMessage).slice(0, 300) : null,
  };
  state.jobsTermines = [entree, ...(state.jobsTermines || [])].slice(0, 50);
  _sauverJobsTermines();
}

/** Retire un travail termine de « En cours » apres `delai`, et l'archive.
 *  Un ECHEC dont la fiche detaillee est ouverte attend sa fermeture :
 *  l'utilisateur lit l'erreur (ou utilise son bouton de reprise). Une
 *  reussite part a l'heure — pushJob ouvre la fiche de chaque nouveau
 *  travail, attendre sa fermeture bloquerait presque toujours l'archivage ;
 *  sa fiche est simplement refermee. */
function _programmerArchivage(j, delai) {
  setTimeout(() => {
    const encore = state.jobs.find(x => x.id === j.id);
    if (!encore || encore.status === 'running') return;
    if (state._jobDetailsOpenId === encore.id) {
      if (encore.status === 'error') { _programmerArchivage(encore, 2000); return; }
      try { closeJobDetails(); } catch (_) {}
    }
    state.jobs = state.jobs.filter(x => x.id !== encore.id);
    _archiverJob(encore);
    renderJobs();
    renderJobsTermines();
  }, delai);
}

/** Liste « Travaux finis ». Reconstruite seulement quand elle change. */
function renderJobsTermines() {
  const liste = document.getElementById('jobs-termines-liste');
  const termines = state.jobsTermines || [];
  const nb = document.getElementById('jobs-nb-termines');
  if (nb) nb.textContent = String(termines.length);
  if (!liste) return;
  const sig = termines.map(e => e.finiId).join(',');
  if (liste.dataset.sig === sig && liste.childElementCount) return;
  liste.dataset.sig = sig;
  if (!termines.length) {
    liste.innerHTML = '<div class="jobs-vide-2">No finished jobs yet</div>';
    return;
  }
  liste.innerHTML = termines.map(e => {
    const aller = _jobStepIndex(e) > 0;
    const duree = e.startedAt && e.finiLe ? fmtDuration(e.finiLe - e.startedAt) : '';
    let heure = '';
    try { heure = new Date(e.finiLe).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); } catch (_) {}
    const icone = e.statut === 'ok' ? '&#10003;' : (e.statut === 'annule' ? '&#8856;' : '&#10005;');
    const vign = _vignetteTravailHtml(e.sourceImageUrl, e.projectName);
    return `
      <div class="job-fini-2 ${escapeHtml(e.statut)}" data-fini-id="${escapeHtml(e.finiId)}">
        <div class="job-fini-2-ligne">
          <span class="job-fini-2-icone" aria-hidden="true">${icone}</span>
          ${_iconeCategorieHtml(_jobStepIndex(e), vign)}
          <span class="job-fini-2-nom">${escapeHtml(_displayJobName(e.name))}</span>
          ${aller ? `<button type="button" class="job-goto-btn" data-fini-goto="${escapeHtml(e.finiId)}">Go to</button>` : ''}
        </div>
        <div class="job-fini-2-meta">${escapeHtml([duree, heure].filter(Boolean).join(' \u00b7 '))}</div>
        ${e.errorMessage ? `<div class="job-fini-2-erreur">${escapeHtml(e.errorMessage)}</div>` : ''}
      </div>`;
  }).join('');
}

/** Bascule entre les onglets « En cours » et « Travaux finis ». */
function _choisirOngletJobs(onglet) {
  state.jobsOnglet = onglet === 'termines' ? 'termines' : 'encours';
  const enCours = state.jobsOnglet === 'encours';
  const bEnCours = document.getElementById('jobs-onglet-encours');
  const bTermines = document.getElementById('jobs-onglet-termines');
  if (bEnCours) { bEnCours.classList.toggle('actif', enCours); bEnCours.setAttribute('aria-selected', String(enCours)); }
  if (bTermines) { bTermines.classList.toggle('actif', !enCours); bTermines.setAttribute('aria-selected', String(!enCours)); }
  const lEnCours = document.getElementById('jobs-list-2');
  const lTermines = document.getElementById('jobs-termines-2');
  if (lEnCours) lEnCours.hidden = !enCours;
  if (lTermines) lTermines.hidden = enCours;
  if (!enCours) renderJobsTermines();
}

function completeJob(id, success, errorMessage) {
  const j = state.jobs.find(j => j.id === id);
  if (!j) return;
  if (j.tickTimer) { clearInterval(j.tickTimer); j.tickTimer = null; }
  // Un parent ne se termine pas avant ses sous-taches : sa fin est differee
  // (voir _finDiffereeSiEnfants). L'ancien commentaire annoncait que le parent
  // etait « requalifie d'office quand son dernier enfant se termine » : aucun
  // code ne le faisait, la tuile restait affichee a jamais.
  if (_finDiffereeSiEnfants(j, success, errorMessage)) return;
  j.progress = 100;
  j.status = success ? 'done' : 'error';
  // Un travail termine REMONTE en tete de la liste (demande de l'utilisateur),
  // puis part dans « Travaux finis » (_programmerArchivage).
  state.jobs = [j, ...state.jobs.filter(x => x !== j)];
  // Sous-tache terminee : son parent attendait peut-etre qu'elle.
  setTimeout(() => _terminerParentEnAttente(j), 0);
  if (!success && errorMessage) {
    // Mappe les OOM VRAM/RAM en message FR clair (au lieu d'une stack brute).
    j.errorMessage = (typeof humanizeErrorMessage === 'function')
      ? humanizeErrorMessage(errorMessage)
      : String(errorMessage);
  }
  // 2026-06-02 liveliness: trigger the one-shot bounce-and-flash on
  // the matching step card so the user gets a satisfying visual cue
  // that something just succeeded. CSS animation is 1.5s; we remove
  // the class after 1600ms so it can re-fire on the next completion.
  try {
    if (success) {
      const stepIdx = _jobStepIndex(j);
      if (stepIdx > 0) {
        const cardId = ['step-card-image','step-card-mesh','step-card-rig','step-card-animation'][stepIdx - 1];
        const card = document.getElementById(cardId);
        if (card) {
          card.classList.add('just-done');
          setTimeout(() => card.classList.remove('just-done'), 1600);
        }
      }
    }
  } catch (_) {}
  renderJobs();
  // ~4 s en tete de liste, puis « Travaux finis » (demande de l'utilisateur,
  // 2026-09-26). Une fiche detaillee ouverte reporte l'archivage : le bouton
  // de reprise d'une erreur (« Open Settings ») reste utilisable.
  _programmerArchivage(j, _DELAI_ARCHIVAGE_MS);
  // SOLDE DE LA BARRE DU HAUT apres CHAQUE travail en mode Cloud — debit, ou
  // remboursement si echec (2026-09-30). Seules la generation d'images et
  // l'animation le relisaient : apres un Modify, un Upscale, un maillage, un
  // rig… le solde affiche restait l'ancien.
  try { if (_isCloudMode()) _rafraichirSoldeBientot(); } catch (_) {}
}
var _soldeMinuterie = null;   // var : jamais en zone morte, meme appele tot
function _rafraichirSoldeBientot() {
  clearTimeout(_soldeMinuterie);
  _soldeMinuterie = setTimeout(() => { try { window._refreshTopbarCredits?.(); } catch (_) {} }, 800);
}

// Export jobs API for classic-script helpers (index2-edit-tools.js).
// - push: create a job right now (no gating) — use for lightweight or already-gated work
// - enqueue: go through the VRAM/GPU/RAM gate, queue if limits exceeded — use for heavy GPU work
// - complete: mark a job done/error + optional error message
// - render: force a UI redraw of the jobs panel
window.fabmeshJobs = {
  push: (name, onCancel, params, expectedMs, opts) => pushJob(name, onCancel, params, expectedMs, opts),
  enqueue: (kind, name, runFn) => enqueueJob(kind, name, runFn),
  complete: (id, success, errorMessage) => completeJob(id, success, errorMessage),
  render: () => renderJobs(),
};

async function cancelJob(id) {
  const j = state.jobs.find(j => j.id === id);
  if (!j) return;
  if (j.status !== 'running') return;
  const ok = await customConfirm(`Cancel "${j.name}"? The current operation will be stopped.`, 'Cancel job', 'Cancel job');
  if (!ok) return;
  // Mark the job as cancelled BEFORE killing the process so the awaiting
  // promise can detect the cancellation and skip the error popup
  j.cancelled = true;
  if (j.tickTimer) { clearInterval(j.tickTimer); j.tickTimer = null; }
  j.status = 'error';
  j.progress = 100;
  j.name += ' (cancelled)';
  renderJobs();
  // If the IPC supports cancellation, fire it
  try {
    if (API.cancelJob) await API.cancelJob(id);
  } catch (e) { console.warn('cancelJob IPC failed:', e); }
  if (j.onCancel) {
    try { j.onCancel(); } catch (e) {}
  }
  // Travail annule : il part aussi dans « Travaux finis » (statut annule).
  _programmerArchivage(j, 3000);
}
window._cancelJob = cancelJob;

// Classify a job into one of the 4 Create New steps so the per-step
// progress widget can show only the jobs relevant to its own panel.
// Returns 1..4 or 0 for "no step" (don't render in any step widget).
function _jobStepIndex(j) {
  const n = (j && j.name) || '';
  // Step 1 (image) — generation, edits, variants, view rectifiers.
  if (/^(generate images?|generating (back|6) views|generate back views|multi[- ]?views|modify|inpaint|face[- ]?fix|remove[- ]?bg|rectif|upscal|back[- ]?view|t[- ]?pose|re[- ]?roll|variant|img2img|sdxl|flux|image[- ]?to[- ]?image)/i.test(n)) return 1;
  // 2026-06-14: manual image-edit tools are named "Manual mask inpaint",
  // "Clone stamp: ...", "Draw mask: ...", etc. — they don't START with an
  // image keyword, so the anchored test above missed them and they never
  // showed in the Image step's GENERATING widget (only in the global
  // running-jobs panel). Match them anywhere in the name.
  if (/(mask inpaint|auto[- ]?inpaint|manual (mask|inpaint|paint|crop)|clone stamp|draw mask|brightness|symmetri[sz]e|color pick|blur brush|\bcrop\b|\bpaint\b|recolor|recolorier|habits|outfit|back photo|downscale|style transfer|export image|remove background|\bage\b|variant)/i.test(n)) return 1;
  if (/^(generate 3d|mesh op|fill[- ]?holes|smooth|material[- ]?adjust|generate mesh|texture|pbr|enhance texture)/i.test(n)) return 2;
  // Mesh texture ops can carry a prefix (e.g. "trellis2 retex: …", "Region re-texture: …")
  // so the anchored test above misses them — match the texture keywords anywhere.
  // Etapes de construction 2D (« Construction stages: <projet> ») : etape
  // image. Sans cette regle, le motif « construction stages » ci-dessous les
  // rangeait en 3D (audit 1.0.36) ; « 3D construction stages » y reste.
  if (/^(construction stages|étapes de construction)/i.test(n)) return 1;
  if (/(retex|re-?texture|reshape|texture variation|enhance texture|détail\+\+|detail\+\+|detail synth|refine mesh|explosion 3d|explode|\bresize\b|construction stages|export to unreal|^export )/i.test(n)) return 2;
  // Mesh-editor saves ("Save mesh edit: …" from Sculpt/Paint/Select) + manual
  // mesh tools — they produce a new mesh version, so the "Go to generated
  // item" button must appear and jump to the mesh step.
  if (/(mesh edit|save mesh|sculpt|watertight|decimate|set[- ]?pivot|fix[- ]?normals|segment)/i.test(n)) return 2;
  if (/(rig|skeleton|re-?skin)/i.test(n)) return 3;
  if (/(^animate|animation)/i.test(n)) return 4;
  return 0;
}

// Track per-step "last seen hasRunning" so we only auto-toggle the
// GENERATING stage when the state CHANGES. Without this, the every-
// second render tick would clobber the user's manual expand (they
// open it, next render closes it). With this, the user's toggle wins
// until the running state flips.
const _stageGenLastRunning = { 1: null, 2: null, 3: null, 4: null };

function _toggleGeneratingStage(stepIdx, hasRunning) {
  const cardId = ['step-card-image','step-card-mesh','step-card-rig','step-card-animation'][stepIdx - 1];
  const card = document.getElementById(cardId);
  if (!card) return;
  const stage = card.querySelector('.stage-generating');
  if (!stage) return;
  // Hide the whole GENERATING section when this step has no jobs/tiles
  // (the empty "No generation in progress" state). renderStepProgressWidgets
  // sets the widget's .has-jobs class BEFORE calling us, so it is reliable;
  // recently done/error tiles keep .has-jobs for a few seconds and stay
  // visible — only the truly-idle panel is hidden.
  const _pw = stage.querySelector('.step-progress-widget');
  stage.style.display = (_pw && _pw.classList.contains('has-jobs')) ? '' : 'none';
  // Only force the open state on TRANSITION (running ↔ idle). User's
  // manual click between transitions is respected.
  const last = _stageGenLastRunning[stepIdx];
  if (last !== hasRunning) {
    stage.open = !!hasRunning;
    _stageGenLastRunning[stepIdx] = hasRunning;
  }
  // Liveliness: badge pulse + icon spin animate via CSS picking up
  // .has-running on the step card.
  card.classList.toggle('has-running', !!hasRunning);
}

// Open the project (if different from current) and scroll/expand the
// step card matching this job. Exposed on window so HTML onclick can
// reach it from anywhere.
/* DEFILEMENT VERS UNE ETAPE QUI TIENT (2026-09-27, user : « Go to m'amene dans
 * le bon projet mais en bas au lieu de l'endroit exact »). Un seul
 * scrollIntoView apres deux images ne suffit pas : l'ouverture du projet
 * charge ensuite images et visualiseurs, la page grandit AU-DESSUS de la
 * carte et la pousse vers le bas. On re-vise la carte pendant ~2,5 s, et on
 * s'arrete des que l'utilisateur fait defiler ou clique lui-meme. */
function _defilerVersCarte(el) {
  if (!el) return;
  let arrete = false;
  const EVTS = ['wheel', 'touchstart', 'keydown', 'mousedown'];
  const stop = () => { arrete = true; };
  EVTS.forEach(ev => window.addEventListener(ev, stop, { passive: true, capture: true }));
  const viser = (doux) => {
    if (arrete) return;
    try {
      const r = el.getBoundingClientRect();
      if (Math.abs(r.top - 12) > 24) el.scrollIntoView({ behavior: doux ? 'smooth' : 'auto', block: 'start' });
    } catch (_) {}
  };
  viser(true);
  [450, 900, 1500, 2400].forEach(t => setTimeout(() => viser(false), t));
  setTimeout(() => EVTS.forEach(ev => window.removeEventListener(ev, stop, { capture: true })), 2600);
}

window._navigateToJobStep = async function(jobId, jobObj) {
  // `jobObj` : une entree de « Travaux finis », qui n'est plus dans state.jobs.
  const j = jobObj || state.jobs.find(x => x.id === jobId);
  if (!j) return;
  const stepIdx = _jobStepIndex(j);
  if (!stepIdx) return;
  const targetName = _jobProjectName(j);
  const cur = state.currentProject && state.currentProject.name;
  if (targetName && targetName !== cur) {
    try {
      const p = (state.projects || []).find(x => x && x.name === targetName);
      if (p && typeof openProject === 'function') {
        await openProject(p);
      } else if (typeof window.openProjectByName === 'function') {
        await window.openProjectByName(targetName);
      }
    } catch (_) {}
  }
  const cardId = ['step-card-image','step-card-mesh','step-card-rig','step-card-animation'][stepIdx - 1];
  const card = document.getElementById(cardId);
  if (!card) return;
  card.classList.remove('collapsed');
  // Replie les AUTRES etapes (user : « en depliant le bon menu et en repliant
  // les mauvais »).
  ['step-card-image', 'step-card-mesh', 'step-card-rig', 'step-card-animation']
    .filter(id => id !== cardId).forEach(id => document.getElementById(id)?.classList.add('collapsed'));
  // TRAVAIL TERMINE : on ouvre « Edit selected », ou se trouve le resultat,
  // et on referme « Create new » (user, 2026-09-27 : « ca ne deplie pas
  // Edit selected, je ne vois pas l'element genere »). En cours ou en
  // echec : « Create new », ou se suit la generation.
  const _fini = (jobObj && jobObj.statut === 'ok') || j.status === 'done';
  const stage = card.querySelector('.stage-create');
  const _edit = card.querySelector('.stage-edit');
  if (_fini && _edit) {
    _edit.open = true;
    if (stage) stage.open = false;
  } else if (stage && !stage.open) stage.open = true;
  // Wait a beat for the details to fully reflow before scrolling so the
  // browser has settled on its final layout box.
  await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
  _defilerVersCarte(card);
  // Pulse-highlight the destination card so the user gets a visual cue
  // that the navigation actually happened.
  try {
    card.classList.add('pulse-highlight');
    setTimeout(() => card.classList.remove('pulse-highlight'), 1600);
  } catch (_) {}
  // Pulse the specific job tile inside the step widget if present.
  try {
    const tile = document.querySelector(`.step-progress-item[data-job-id="${jobId}"]`);
    if (tile) {
      tile.classList.add('pulse-highlight');
      setTimeout(() => tile.classList.remove('pulse-highlight'), 1600);
    }
  } catch (_) {}
};

// Populate every per-step progress widget from state.jobs. Only jobs
// belonging to the currently-open project show up — the widget lives
// inside that project's workspace, so cross-project bleed would be
// confusing. Empty widgets get the hidden state (no .has-jobs class).
// Translate a job title for DISPLAY only — the stored job.name stays English so
// the step-matching regex (_jobStepIndex) keeps working. Handles "Prefix: value"
// templates ("Generate 3D: dropped") via tf(), else a plain t() lookup.
function _displayJobName(name) {
  const I = window.FabI18n;
  if (!I || I.lang === 'en' || !name) return name || '';
  const m = String(name).match(/^(.*?): (.+)$/);
  if (m && I.tf) {
    const out = I.tf(m[1] + ': {x}', m[2]);
    if (out && out !== m[1] + ': ' + m[2]) return out;  // had a template translation
  }
  return (I.t && I.t(name)) || name;
}

function renderStepProgressWidgets() {
  const curName = state.currentProject && state.currentProject.name;
  for (let s = 1; s <= 4; s++) {
    const widget = document.getElementById(`step-progress-${s}`);
    if (!widget) continue;
    const matching = state.jobs.filter(j => {
      if (_jobStepIndex(j) !== s) return false;
      // Une SOUS-TACHE n'est pas un item de premier niveau : elle est rendue
      // dans sa tuile parente (voir _renderSousTaches). Sinon l'etape affichait
      // « Generate 3D » et « Generate images » cote a cote pour un seul clic.
      if (_estSousTache(j)) return false;
      const pn = _jobProjectName(j);
      // No project label on the job → show in the current project's
      // widget only (best-effort). With a label, show only if matching.
      return !pn || pn === curName;
    });
    if (!matching.length) {
      widget.classList.remove('has-jobs');
      if (widget.dataset.sig !== '__empty__') {
        widget.innerHTML = '<div class="step-progress-empty">No generation in progress</div>';
        widget.dataset.sig = '__empty__';
      }
      try { _toggleGeneratingStage(s, false); } catch (_) {}
      continue;
    }
    widget.classList.add('has-jobs');
    // Step badge only pulses while at least one job is STILL running.
    // Done/error tiles keep showing for ~3-8s but the step itself
    // stops being "active" so we let the badge calm down.
    const hasRunning = matching.some(j => j.status === 'running');
    try { _toggleGeneratingStage(s, hasRunning); } catch (_) {}
    // Targeted update: patch bars/% in place while the item SET is unchanged,
    // instead of rebuilding innerHTML every tick (the violent green flicker).
    const _sigW = matching.map(j => j.id + ':' + j.status + ':' + _jobChildren(j.id).length).join(',');
    if (widget.dataset.sig === _sigW) {
      matching.forEach(j => {
        const el = widget.querySelector(`.step-progress-item[data-job-id="${j.id}"]`);
        if (!el) return;
        const pct = Math.round(j.progress || 0);
        const fill = el.querySelector('.step-progress-item-bar-fill');
        if (fill) fill.style.width = pct + '%';
        const pctEl = el.querySelector('.step-progress-item-pct');
        if (pctEl) {
          const elapsed = j.startedAt ? fmtDuration(Date.now() - j.startedAt) : '';
          pctEl.innerHTML = (elapsed ? `<span style="color:var(--text-2); margin-right:8px; font-weight:normal;">${elapsed}</span>` : '') + pct + '%';
        }
        // Sous-taches : meme tick, meme mise a jour en place (pas de rebuild,
        // sinon la barre de l'enfant repart de zero a chaque rafraichissement).
        _jobChildren(j.id).forEach(c => {
          const sc = widget.querySelector(`.job-item-2-sub[data-job-id="${c.id}"]`);
          if (!sc) return;
          const cpct = Math.round(c.progress || 0);
          const cfill = sc.querySelector('.job-item-2-bar-fill');
          if (cfill) cfill.style.width = cpct + '%';
          const cpctEl = sc.querySelector('.job-item-2-sub-pct');
          if (cpctEl) {
            const cel = c.startedAt ? fmtDuration(Date.now() - c.startedAt) : '';
            cpctEl.textContent = (cel ? cel + ' \u00b7 ' : '') + cpct + '%';
          }
        });
      });
      continue;
    }
    widget.dataset.sig = _sigW;
    widget.innerHTML = matching.map(j => {
      const pct = Math.round(j.progress || 0);
      const canCancel = j.status === 'running';
      const statusClass = j.status === 'done' ? ' done'
                        : j.status === 'error' ? ' error'
                        : '';
      const elapsed = j.startedAt ? fmtDuration(Date.now() - j.startedAt) : '';
      // Small source-asset thumbnail so the user recognises which
      // generation is theirs. Snapshot stamped at pushJob time —
      // never the currently-selected version (race-safe).
      const thumbUrl = j.sourceImageUrl ? (
        /^(https?:|data:|blob:|file:|app:)/i.test(j.sourceImageUrl)
          ? j.sourceImageUrl
          : (typeof _toFileUrl === 'function' ? _toFileUrl(j.sourceImageUrl) : j.sourceImageUrl)
      ) : '';
      const thumbHtml = thumbUrl
        ? `<img src="${escapeHtml(thumbUrl)}" alt="" class="step-progress-item-thumb"/>`
        : '';
      return `
        <div class="step-progress-item${statusClass}" data-job-id="${j.id}">
          <div class="step-progress-item-header">
            ${_iconeCategorieHtml(_jobStepIndex(j), thumbHtml)}
            <div class="step-progress-item-name">${escapeHtml(_displayJobName(j.name))}</div>
            ${canCancel ? `<button class="step-progress-cancel-btn" onclick="event.stopPropagation(); window._cancelJob(${j.id})" title="Cancel job">&#10005;</button>` : ''}
          </div>
          <div class="step-progress-item-bar">
            <div class="step-progress-item-bar-fill" style="width:${pct}%"></div>
          </div>
          <div class="step-progress-item-pct">${elapsed ? `<span style="color:var(--text-2); margin-right:8px; font-weight:normal;">${elapsed}</span>` : ''}${pct}%</div>
          ${_renderSousTaches(j.id, 'job-item-2-sub')}
        </div>`;
    }).join('');
    widget.querySelectorAll('.step-progress-item[data-job-id]').forEach(el => {
      el.addEventListener('click', () => {
        const id = parseInt(el.dataset.jobId);
        openJobDetails(id);
      });
    });
  }
}

// Rendu des SOUS-TACHES d'un travail (2026-09-25). Un travail parent peut
// enchainer des operations qui, elles aussi, creent une ligne `jobs` cote
// serveur (rectify, back-view, text2image). L'utilisateur demandait a voir
// "une sous-tache dans la generation du mesh" plutot que deux popups
// independantes dont on ne savait pas laquelle appartenait a l'autre.
//
// Le rendu est volontairement PLUS LEGER qu'une tuile de premier niveau :
// pas de bouton « Go to » (la sous-tache n'est pas un point d'entree), pas de
// vignette (elle herite du contexte visuel du parent), barre plus fine.
// Le bouton d'annulation reste : un pipeline bloque doit pouvoir etre coupe.
function _renderSousTaches(parentId, cls) {
  let enfants = [];
  try { enfants = _jobChildren(parentId); } catch (_) { return ''; }
  if (!enfants.length) return '';
  return enfants.map(c => {
    const pct = Math.round(c.progress || 0);
    const canCancel = c.status === 'running';
    const statusClass = c.status === 'done' ? ' done'
                      : c.status === 'error' ? ' error'
                      : '';
    const elapsed = c.startedAt ? fmtDuration(Date.now() - c.startedAt) : '';
    const label = `${elapsed ? elapsed + ' · ' : ''}${pct}%`;
    return `
      <div class="${cls}${statusClass}" data-job-id="${c.id}">
        <div class="${cls}-row">
          <span class="${cls}-bullet">&#8627;</span>
          <span class="${cls}-name">${escapeHtml(_displayJobName(c.name))}</span>
          ${canCancel ? `<button class="job-cancel-btn" onclick="event.stopPropagation(); window._cancelJob(${c.id})" title="Cancel job">&#10005;</button>` : ''}
        </div>
        <div class="${cls}-bar">
          <div class="job-item-2-bar-fill" style="width:${pct}%"></div>
        </div>
        <div class="${cls}-pct">${label}</div>
      </div>
    `;
  }).join('');
}

// Tuiles EN COURS triees par AVANCEMENT, la plus avancee en haut (user 28/09 : « faire evoluer leur
// position en fonction de leur pourcentage »). On DEPLACE les noeuds existants (jamais de
// reconstruction : le bouton sous le curseur serait detruit) avec un glissement anime (FLIP).
// Hysteresis de 3 points : deux travaux au coude a coude ne s'echangent pas sans cesse. Rien ne
// bouge tant que la souris est sur la liste (le clic sur « Go to » ou « x » ne doit pas rater).
function _trierJobsParAvancement(list, anime = true) {
  if (!list || list.matches(':hover')) return;
  const cartes = [...list.children].filter((el) => el.matches('.job-item-2[data-job-id]'));
  if (cartes.length < 2) return;
  const pct = (el) => { const j = state.jobs.find((x) => String(x.id) === el.dataset.jobId); return j ? (Number(j.progress) || 0) : 0; };
  const ordre = cartes.slice();
  for (let i = 1; i < ordre.length; i++) {                  // tri par insertion stable, avec hysteresis
    const c = ordre[i];
    let k = i;
    while (k > 0 && pct(c) > pct(ordre[k - 1]) + 3) k--;
    if (k !== i) { ordre.splice(i, 1); ordre.splice(k, 0, c); }
  }
  if (ordre.every((c, i) => c === cartes[i])) return;
  const avant = new Map(cartes.map((c) => [c, c.getBoundingClientRect().top]));
  const ancre = cartes[cartes.length - 1].nextSibling;      // les travaux en attente restent en bas
  for (const c of ordre) list.insertBefore(c, ancre);
  if (!anime || window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;
  for (const c of ordre) {
    const dy = avant.get(c) - c.getBoundingClientRect().top;
    if (!dy) continue;
    c.style.transition = 'none';
    c.style.transform = `translateY(${dy}px)`;
    c.getBoundingClientRect();                              // position de depart prise en compte
    c.style.transition = 'transform 0.45s cubic-bezier(.2,.8,.2,1)';
    c.style.transform = '';
  }
}

function renderJobs() {
  const bubble = document.getElementById('jobs-bubble-2');
  const panel = document.getElementById('jobs-panel-2');
  const runningCount = state.jobs.filter(j => j.status === 'running').length;
  const queuedCount = queuedJobs.length;
  const totalCount = state.jobs.length + queuedCount;
  // Un seul nombre (demande user, 2026-09-28 : « 1+1, ca fait 2 ») : les
  // travaux en cours et en attente, sans les sous-taches — le meme compte que
  // l'onglet « En cours ». Le detail reste dans l'info-bulle.
  const nbBulle = state.jobs.filter(j => j.status === 'running' && !_estSousTache(j)).length + queuedCount;
  document.getElementById('jobs-bubble-count-2').textContent = String(nbBulle);
  if (bubble) bubble.title = queuedCount > 0 ? `${nbBulle - queuedCount} running, ${queuedCount} waiting` : `${nbBulle} running`;
  // Per-step widgets piggy-back on the same refresh tick.
  try { renderStepProgressWidgets(); } catch (_) {}
  // Onglets : compteurs. Tant qu'il reste des travaux finis, la bulle reste
  // accessible (grisee s'il n'y a rien en cours) pour consulter l'historique.
  const nbTermines = (state.jobsTermines || []).length;
  try {
    const nbEnCours = document.getElementById('jobs-nb-encours');
    if (nbEnCours) nbEnCours.textContent = String(state.jobs.filter(j => !_estSousTache(j)).length + queuedCount);
    const nbT = document.getElementById('jobs-nb-termines');
    if (nbT) nbT.textContent = String(nbTermines);
  } catch (_) {}
  if (totalCount === 0 && nbTermines === 0) {
    bubble.classList.add('hidden');
    panel.classList.add('hidden');
    return;
  }
  bubble.classList.toggle('jobs-bubble-inactive', totalCount === 0);
  // Always show the bubble when there are active or queued jobs and the panel
  // is closed — this was the bug: queued jobs were invisible because they
  // weren't in state.jobs and the bubble only appeared for state.jobs.length > 0.
  if (panel.classList.contains('hidden')) {
    bubble.classList.remove('hidden');
  }
  const list = document.getElementById('jobs-list-2');
  // Targeted update: if the card SET is unchanged (same ids/statuses + same
  // queued set) and only progress moved, patch the bars/text IN PLACE instead
  // of rebuilding innerHTML every tick. The rebuild tore down + recreated every
  // card (thumbnail reload + bar reset), which made them flicker / jump.
  const _sig = state.jobs.map(j => j.id + ':' + j.status).join(',')
    + '|' + queuedJobs.map(q => q.displayName || '').join('~');
  if (list.dataset.sig === _sig) {
    state.jobs.forEach(j => {
      const el = list.querySelector(`.job-item-2[data-job-id="${j.id}"]`);
      if (!el) return;
      const pct = Math.round(j.progress);
      const fill = el.querySelector('.job-item-2-bar-fill');
      if (fill) fill.style.width = pct + '%';
      // le NOM aussi (« Generate images » -> « Generate back views » quand l'image est prete, 28/09)
      const nomEl = el.querySelector(':scope > .job-item-2-header > .job-item-2-name');
      if (nomEl && nomEl.textContent !== _displayJobName(j.name)) nomEl.textContent = _displayJobName(j.name);
      const pctEl = el.querySelector('.job-item-2-pct');
      if (pctEl) {
        const elapsed = j.startedAt ? fmtDuration(Date.now() - j.startedAt) : '';
        pctEl.innerHTML = (elapsed ? `<span style="color:var(--text-2); margin-right:8px; font-weight:normal;">${elapsed}</span>` : '') + pct + '%';
      }
    });
    if (state._jobDetailsOpenId) refreshJobDetailsModal(state._jobDetailsOpenId);
    _trierJobsParAvancement(list);
    return;
  }
  list.dataset.sig = _sig;
  // Active jobs. Les SOUS-TACHES ne sont pas rendues ici : elles le sont sous
  // leur parent (voir _jobChildren plus bas). Sans ce filtre, une generation de
  // mesh avec back-view apparaissait deux fois — « Generate 3D » ET
  // « Generate images » — pour un seul clic de l'utilisateur (2026-09-25).
  const _racines = state.jobs.filter(j => !_estSousTache(j));
  let html = _racines.map(j => {
    const pct = Math.round(j.progress);
    const canCancel = j.status === 'running';
    // Show a "Go to step" pill when the job maps to a known step so the
    // user can jump straight to its Create New widget instead of hunting
    // for it across projects.
    const hasStep = _jobStepIndex(j) > 0;
    const elapsed = j.startedAt ? fmtDuration(Date.now() - j.startedAt) : '';
    const sbThumbUrl = j.sourceImageUrl ? (
      /^(https?:|data:|blob:|file:|app:)/i.test(j.sourceImageUrl)
        ? j.sourceImageUrl
        : (typeof _toFileUrl === 'function' ? _toFileUrl(j.sourceImageUrl) : j.sourceImageUrl)
    ) : '';
    const sbThumbHtml = sbThumbUrl
      ? `<img src="${escapeHtml(sbThumbUrl)}" alt="" class="step-progress-item-thumb"/>`
      : '';
    return `
      <div class="job-item-2 ${j.status}" data-job-id="${j.id}">
        <div class="job-item-2-header">
          ${_iconeCategorieHtml(_jobStepIndex(j), sbThumbHtml)}
          <div class="job-item-2-name">${escapeHtml(_displayJobName(j.name))}</div>
          ${hasStep ? `<button class="job-goto-btn" onclick="event.stopPropagation(); window._navigateToJobStep(${j.id})" title="Jump to this step">Go to</button>` : ''}
          ${canCancel ? `<button class="job-cancel-btn" onclick="event.stopPropagation(); window._cancelJob(${j.id})" title="Cancel job">&#10005;</button>` : ''}
        </div>
        <div class="job-item-2-bar">
          <div class="job-item-2-bar-fill" style="width:${pct}%"></div>
        </div>
        <div class="job-item-2-pct">${elapsed ? `<span style="color:var(--text-2); margin-right:8px; font-weight:normal;">${elapsed}</span>` : ''}${pct}%</div>
        ${_renderSousTaches(j.id, 'job-item-2-sub')}
      </div>
    `;
  }).join('');
  // Queued jobs (waiting for VRAM/GPU headroom)
  if (queuedCount > 0) {
    html += queuedJobs.map((q, idx) => `
      <div class="job-item-2 queued" data-queue-idx="${idx}">
        <div class="job-item-2-header">
          <div class="job-item-2-name">&#9202; ${escapeHtml(q.displayName || 'Queued job')}</div>
          <button class="job-goto-btn" onclick="event.stopPropagation(); window._startQueuedNow(${idx})" title="${escapeHtml(_i18nT('Start now, above your limits'))}">${escapeHtml(_i18nT('Start now'))}</button>
          <button class="job-cancel-btn" onclick="event.stopPropagation(); window._cancelQueuedJob(${idx})" title="Remove from queue">&#10005;</button>
        </div>
        <div class="job-item-2-bar">
          <div class="job-item-2-bar-fill queued-fill" style="width:0%"></div>
        </div>
        <div class="job-item-2-pct" style="color:var(--warning, #f59e0b); font-weight:600;">queued</div>
        <div class="job-item-2-queue-reason" style="color:var(--text-2); font-size:11px; line-height:1.35; margin-top:4px; white-space:normal;">${escapeHtml(q.reason || '')}</div>
      </div>
    `).join('');
  }
  // Onglet « En cours » vide : un message plutot qu'un panneau blanc.
  if (!html) html = '<div class="jobs-vide-2">No running jobs</div>';
  // MISE A JOUR CIBLEE. `list.innerHTML = html` a chaque tick detruisait et
  // recreait chaque ligne — donc le bouton « Go to » SOUS LE CURSEUR. Le
  // survol clignotait et le clic tombait sur un noeud qui venait de
  // disparaitre (signale par l'utilisateur le 2026-09-24). Le panneau
  // d'etape avait deja recu ce correctif ; celui-ci, non.
  //
  // La signature ne retient que ce qui change la STRUCTURE : identifiant,
  // statut, presence des boutons. Tant qu'elle est stable, on ne touche
  // qu'a la barre et au pourcentage, et le DOM survit au survol.
  const _sigJobs = state.jobs.map(j =>
      j.id + ':' + j.status + ':' + (_jobStepIndex(j) > 0 ? 'g' : '-')
      + ':' + (j.status === 'running' ? 'x' : '-')
      + ':' + (_jobParent(j) ? 's' : '-')).join(',')
    + '|' + queuedJobs.map(q => q.displayName || '').join(',');
  if (list.dataset.sigJobs === _sigJobs) {
    state.jobs.forEach(j => {
      const pct = Math.round(j.progress);
      const elapsed = j.startedAt ? fmtDuration(Date.now() - j.startedAt) : '';
      const el = list.querySelector('.job-item-2[data-job-id="' + j.id + '"]');
      if (el) {
        // `:scope >` : la barre et le pourcentage PROPRES a la tuile, jamais
        // ceux d'une sous-tache imbriquee dessous.
        const fill = el.querySelector(':scope > .job-item-2-bar > .job-item-2-bar-fill');
        if (fill) fill.style.width = pct + '%';
        // le NOM aussi (« Generate images » -> « Generate back views » quand l'image est prete, 28/09)
        const nomEl = el.querySelector(':scope > .job-item-2-header > .job-item-2-name');
        if (nomEl && nomEl.textContent !== _displayJobName(j.name)) nomEl.textContent = _displayJobName(j.name);
        const pctEl = el.querySelector(':scope > .job-item-2-pct');
        if (pctEl) {
          pctEl.innerHTML = (elapsed
            ? '<span style="color:var(--text-2); margin-right:8px; font-weight:normal;">'
              + escapeHtml(elapsed) + '</span>'
            : '') + pct + '%';
        }
      }
      // SOUS-TACHE (2026-09-26) : son element porte la classe job-item-2-sub,
      // PAS job-item-2. L'ancien code sortait sur `if (!el) return` juste
      // au-dessus, AVANT d'arriver ici : aucune sous-tache n'etait jamais mise
      // a jour en place — barre et chrono figes (« Rectify source view »
      // bloque a 1m42s / 90 %, signale par l'utilisateur). Le libelle garde le
      // format du rendu complet (« duree · pct »).
      const subEl = list.querySelector('.job-item-2-sub[data-job-id="' + j.id + '"]');
      if (subEl) {
        const subFill = subEl.querySelector('.job-item-2-bar-fill');
        if (subFill) subFill.style.width = pct + '%';
        const subPct = subEl.querySelector('.job-item-2-sub-pct');
        if (subPct) subPct.textContent = (elapsed ? elapsed + ' \u00b7 ' : '') + pct + '%';
      }
    });
    if (state._jobDetailsOpenId) refreshJobDetailsModal(state._jobDetailsOpenId);
    _trierJobsParAvancement(list);
    return;
  }
  list.innerHTML = html;
  list.dataset.sigJobs = _sigJobs;
  _trierJobsParAvancement(list, false);                 // rendu neuf : directement dans l'ordre
  // Bind click on each active job item to open the details modal
  list.querySelectorAll('.job-item-2[data-job-id]').forEach(el => {
    el.addEventListener('click', () => {
      const id = parseInt(el.dataset.jobId);
      openJobDetails(id);
    });
  });
  // If the details modal is open and showing this job, refresh its values too
  if (state._jobDetailsOpenId) {
    refreshJobDetailsModal(state._jobDetailsOpenId);
  }
}
// Cancel a queued job (remove from the queue before it ever starts)
window._startQueuedNow = function(idx) {
  const q = queuedJobs[idx];
  if (!q) return;
  q.force = true;
  if (idx > 0) { queuedJobs.splice(idx, 1); queuedJobs.unshift(q); renderJobs(); }
  console.log('[queue] start now:', q.displayName);
  try { processQueue(); } catch (_) {}
};
window._cancelQueuedJob = function(idx) {
  if (idx >= 0 && idx < queuedJobs.length) {
    const removed = queuedJobs.splice(idx, 1);
    console.log('[queue] removed queued job:', removed[0]?.displayName);
    renderQueueIndicator();
    renderJobs();
  }
};

// ----- Job details modal -----
let _jobGpuTimer = null;
// Le moniteur VRAM/GPU/température n'a de sens que sur une carte NVIDIA lue par
// nvidia-smi. Sans carte (ou en mode Cloud) il restait figé sur « -- » — l'app
// avait l'air cassée — et déclenchait 2 spawns nvidia-smi par seconde d'un
// exécutable inexistant tant que la modale de tâche était ouverte.
function _jobGpuMonitorAvailable() { return _hasNvidia() && !_isCloudMode(); }
function _syncJobGpuMonitorVisibility() {
  const box = document.getElementById('job-gpu-monitor');
  if (box) box.style.display = _jobGpuMonitorAvailable() ? '' : 'none';
}
async function refreshJobGpuMonitor() {
  if (!API.checkGPU) return;
  if (!_jobGpuMonitorAvailable()) return;
  // Skip the IPC round-trip if the window is not visible — saves CPU when
  // the user has the app in the background while a long job runs.
  if (document.visibilityState === 'hidden') return;
  try {
    const gpu = await API.checkGPU();
    if (!gpu || !gpu.available) return;
    const vram = document.getElementById('jgm-vram');
    const util = document.getElementById('jgm-util');
    const temp = document.getElementById('jgm-temp');
    // Convert the 0-100 slider positions to the same units shown next to
    // each line so the limit and the current value are directly comparable.
    const vramLimitPct  = Math.round(gpuLimits?.vram ?? 90);
    const vramLimitGB   = (gpu.totalGB * vramLimitPct / 100);
    const utilLimitPct  = Math.round(gpuLimits?.util ?? 95);
    // Temperature slider uses the same 30-100°C mapping as the tooltip
    const tempLimitC    = Math.round(30 + ((gpuLimits?.temp ?? 80) / 100) * 70);
    if (vram) {
      const vramPct = (gpu.usedGB / gpu.totalGB) * 100;
      vram.textContent = `${gpu.usedGB.toFixed(1)} / ${vramLimitGB.toFixed(0)}`;
      vram.classList.remove('warn', 'error');
      if (vramPct > vramLimitPct) vram.classList.add('error');
      else if (vramPct > 70) vram.classList.add('warn');
    }
    if (util) {
      // GPU at 100% is normal during a gen (unlike RAM saturation) — show the
      // usage plainly, never colour it red.
      util.textContent = (gpu.gpuUtil || 0) + '%';
      util.classList.remove('warn', 'error');
    }
    if (temp) {
      temp.textContent = (gpu.tempC || 0) + ' / ' + tempLimitC + '°C';
      temp.classList.remove('warn', 'error');
      if ((gpu.tempC || 0) > tempLimitC) temp.classList.add('error');
      else if ((gpu.tempC || 0) > 65) temp.classList.add('warn');
    }
    // RAM mini-monitor
    const ramEl = document.getElementById('jgm-ram');
    if (ramEl && API.checkRAM) {
      try {
        const ram = await API.checkRAM();
        const ramPct = (ram.usedGB / ram.totalGB) * 100;
        const ramLimitPct = Math.round(gpuLimits?.ram ?? 85);
        const ramLimitGB  = (ram.totalGB * ramLimitPct / 100);
        ramEl.textContent = `${ram.usedGB.toFixed(1)} / ${ramLimitGB.toFixed(0)} GB`;
        ramEl.classList.remove('warn', 'error');
        if (ramPct > ramLimitPct) ramEl.classList.add('error');
        else if (ramPct > 70) ramEl.classList.add('warn');
      } catch (e2) {}
    }
  } catch (e) {}
}

function openJobDetails(id) {
  const j = state.jobs.find(x => x.id === id);
  if (!j) return;
  state._jobDetailsOpenId = id;
  document.getElementById('modal-job-details').classList.remove('hidden');
  _syncJobGpuMonitorVisibility();
  refreshJobDetailsModal(id);
  if (!_jobGpuMonitorAvailable()) return;   // pas de carte NVIDIA → pas de timer
  // Start the GPU mini monitor (2s tick — was 1s; halved to reduce nvidia-smi calls)
  refreshJobGpuMonitor();
  if (_jobGpuTimer) clearInterval(_jobGpuTimer);
  // 500ms tick so the user sees real-time VRAM/GPU/temp/RAM on the
  // overlay inside the job-details modal (same cadence as Settings).
  _jobGpuTimer = setInterval(refreshJobGpuMonitor, 500);
}
function closeJobDetails() {
  state._jobDetailsOpenId = null;
  document.getElementById('modal-job-details').classList.add('hidden');
  if (_jobGpuTimer) { clearInterval(_jobGpuTimer); _jobGpuTimer = null; }
}
function fmtDuration(ms) {
  const s = Math.floor(ms / 1000);
  if (s < 60) return s + 's';
  const m = Math.floor(s / 60);
  const rs = s % 60;
  return `${m}m ${rs}s`;
}
async function refreshJobDetailsModal(id) {
  const j = state.jobs.find(x => x.id === id);
  if (!j) { closeJobDetails(); return; }
  document.getElementById('job-details-title').textContent = j.status === 'done' ? 'Task complete' : (j.status === 'error' ? 'Task failed' : 'Running task');
  document.getElementById('job-details-subtitle').textContent = _displayJobName(j.name);
  document.getElementById('jd-status').textContent = j.status === 'running' ? 'Running' : (j.status === 'done' ? 'Done' : 'Error');
  document.getElementById('jd-started').textContent = new Date(j.startedAt).toLocaleTimeString();
  document.getElementById('jd-elapsed').textContent = fmtDuration(Date.now() - j.startedAt);
  // Estimated total: start from the static estimate, but once the job has real
  // progress (>=8%) trust a DYNAMIC estimate (elapsed / fraction) — it adapts
  // to whatever is actually happening (RAM swap, cascade slowness) that the
  // static number can't predict.
  let _estMs = j.expectedMs;
  if (j.status === 'running' && j.startedAt && typeof j.progress === 'number' && j.progress >= 8 && j.progress < 100) {
    const _elapsed = Date.now() - j.startedAt;
    const _dyn = _elapsed / (j.progress / 100);
    // Blend static + dynamic, weighted by progress. The early phases (model
    // load, rembg, rectify) are disproportionately slow, so a raw elapsed/
    // fraction extrapolation BALLOONS the estimate ("ça se rallonge sans
    // cesse"). We trust the static estimate while progress is low and only lean
    // on the dynamic one as the job nears completion (where it's accurate).
    const _w = Math.min(1, j.progress / 100);
    const _blended = _w * _dyn + (1 - _w) * (j.expectedMs || _dyn);
    _estMs = Math.max(_blended, _elapsed);  // never below already-elapsed
  }
  // Show the job's OWN project (snapshot at pushJob time) instead of whatever
  // is currently open. If the user switches projects mid-job the popup must
  // keep pointing at the project that started the job.
  document.getElementById('jd-project').textContent = _jobProjectName(j) || (state.currentProject ? state.currentProject.name : '--');
  // Parameters block
  const paramsBox = document.getElementById('jd-params');
  if (paramsBox) {
    if (j.params && Object.keys(j.params).length > 0) {
      const rows = Object.entries(j.params).map(([k, v]) => {
        const full = String(v == null ? '--' : v);
        // The value column now wraps (CSS overflow-wrap), so allow a longer
        // filename before truncating; the full name is always in the tooltip.
        const val = full.length > 120 ? full.slice(0, 117) + '...' : full;
        return `<div class="jd-row"><span class="jd-label">${escapeHtml(k)}</span><span class="jd-value" title="${escapeHtml(full)}">${escapeHtml(val)}</span></div>`;
      }).join('');
      paramsBox.innerHTML = rows;
      paramsBox.classList.remove('hidden');
    } else {
      paramsBox.innerHTML = '';
      paramsBox.classList.add('hidden');
    }
  }
  // Reference thumbnail: for rig jobs we want to show the SOURCE 3D MESH
  // (the GLB being rigged), not the image. For 3D-gen / modify / inpaint
  // / back-view we show the source image. But for a FRESH image generation
  // (`Generate images: ...`) there is no source asset yet — showing the
  // project's previously-selected image is misleading ("looks like the new
  // gen has the old image"), so we hide the thumb in that case.
  // PRIORITY: job.sourceImageUrl (the SNAPSHOT taken at pushJob time) wins
  // over state.currentProject.* — because the user can click another
  // version thumb between launch and the modal refresh, which would swap
  // the displayed source image to a completely different asset.
  const refImg = document.getElementById('jd-ref-img');
  const p = state.currentProject;
  const isRigJob = /rig/i.test(j.name || '');
  // Match all phases of an image-creation job so the popup never shows the
  // previously-selected image as a thumb. The phase-2 rename ("Generating
  // 6 views: ..." / "Generate back views: ...") used to escape the original
  // regex and reveal the stale thumb mid-generation.
  const isImageGenJob = /^(generate images?|generating (back|6) views|generate back views|multi-views)\b/i.test(j.name || '');
  let thumbUrl = null;
  // 1) Snapshot wins — set at launch time, immune to UI state mutations.
  if (j.sourceImageUrl && !isImageGenJob) {
    const u = j.sourceImageUrl;
    if (/^https?:|^file:|^data:|^blob:/i.test(u)) {
      thumbUrl = u + (u.includes('?') ? '&' : '?') + 't=' + Date.now();
    } else {
      thumbUrl = 'file:///' + String(u).replace(/\\/g, '/') + '?t=' + Date.now();
    }
  }
  // 2) Rig jobs: show the source mesh thumbnail (not an image).
  if (!thumbUrl && isRigJob && p && p.selectedMeshPath && API.getThumbnail) {
    try {
      const t = await API.getThumbnail(p.selectedMeshPath);
      if (t) thumbUrl = t + '?t=' + Date.now();
    } catch (_) {}
  }
  // 3) Fallback to the current project's image path (legacy behaviour).
  if (!thumbUrl && p && !isImageGenJob) {
    const imgPath = p.selectedImagePath || p.previewImagePath || p.thumb;
    if (imgPath) thumbUrl = 'file:///' + imgPath.replace(/\\/g, '/') + '?t=' + Date.now();
  }
  if (thumbUrl && refImg) {
    refImg.src = thumbUrl;
    refImg.style.display = '';
  } else if (refImg) {
    refImg.removeAttribute('src');
    refImg.style.display = 'none';
  }
  const pct = Math.round(j.progress);
  document.getElementById('jd-progress-fill').style.width = pct + '%';
  document.getElementById('jd-progress-pct').textContent = pct + '%';
  // First-run hint — shown while a local SDXL-server-backed job is running,
  // so the user understands why the first call takes 1-3 minutes (model
  // download + VRAM load). Hidden for cloud jobs (pollinations / meshy) and
  // for jobs that have already finished.
  // First-run hint: only show when the job JUST started (first 15s) AND
  // it's a local GPU job. After 15s the model is either loaded (hint no
  // longer relevant) or the job already has real progress. This prevents
  // the hint from appearing on every single generation.
  const hintEl = document.getElementById('jd-first-run-hint');
  if (hintEl) {
    const elapsed = Date.now() - j.startedAt;
    const isEarly = j.status === 'running' && elapsed < 15000;
    const blob = (j.params?.Engine || '') + ' ' + (j.name || '') + ' ' + (j.kind || '');
    const isLocalGpu = /realvis|sf3d|stable fast|unirig|sdxl|inpaint|img2img|style|modify/i.test(blob);
    const isImageJob = /realvis|sdxl|inpaint|img2img|style|modify|image/i.test(blob);
    // Mode Cloud : le calcul tourne sur le worker MyFabmesh, PAS sur la carte
    // de la machine. Le texte « ~7 GB chargés en VRAM / modèles déchargés au
    // bout de 5 min » serait faux (et absurde sur un PC sans GPU NVIDIA) — on
    // affiche à la place ce qui se passe vraiment.
    const txtEl = hintEl.querySelector('.jd-hint-text');
    if (txtEl && !txtEl.dataset.localTxt) txtEl.dataset.localTxt = txtEl.innerHTML;
    let show;
    if (_isCloudMode()) {
      if (txtEl) {
        txtEl.textContent = _i18nT('Generated on the MyFabmesh cloud — your GPU is not used. '
          + 'The result is downloaded to this PC as soon as it is ready.');
      }
      show = j.status === 'running';
    } else {
      if (txtEl && txtEl.dataset.localTxt) txtEl.innerHTML = txtEl.dataset.localTxt;
      show = isEarly && isLocalGpu;
      // Image ops reuse the PERSISTENT SDXL server: if it's already loaded (a gen
      // ran just before), there is no ~7 GB cold load — the op finishes in
      // seconds — so the "first run after idle" notice is misleading. Hide it when
      // the AI engine is already resident. (3D/rig spawn a fresh process each run,
      // so they genuinely cold-load every time → keep the hint for them.)
      if (show && isImageJob && API.listProcesses) {
        try {
          const pl = await API.listProcesses();
          if (((pl && pl.procs) || []).some(p => p.isAiEngine)) show = false;
        } catch (_) {}
      }
    }
    hintEl.classList.toggle('hidden', !show);
  }
  // Cancel button: only enabled while running
  const cancelBtn = document.getElementById('job-details-cancel');
  cancelBtn.disabled = j.status !== 'running';
  cancelBtn.style.display = j.status === 'running' ? '' : 'none';
  // Error box + contextual "Open Settings" shortcut.
  // Shown when the job failed with a message. If the error message matches
  // the Meshy "API key not configured" pattern, we surface a dedicated
  // primary button that opens Settings and focuses the Meshy key field.
  const errBox = document.getElementById('jd-error-box');
  const openSettingsBtn = document.getElementById('job-details-open-settings');
  const unlockBtn = document.getElementById('job-details-unlock');
  if (errBox && openSettingsBtn) {
    if (j.status === 'error' && j.errorMessage) {
      errBox.textContent = j.errorMessage;
      errBox.classList.remove('hidden');
      const needsApiKey = /api key not configured/i.test(j.errorMessage);
      openSettingsBtn.style.display = needsApiKey ? '' : 'none';
      // Content-filter block → offer a direct Unlock shortcut to the parental-
      // control disable flow (legal warning + PIN), like reportPipelineError does.
      const isContentFilter = /content filter|parental control|unrestricted mode/i.test(j.errorMessage);
      if (unlockBtn) unlockBtn.style.display = isContentFilter ? '' : 'none';
    } else {
      errBox.textContent = '';
      errBox.classList.add('hidden');
      openSettingsBtn.style.display = 'none';
      if (unlockBtn) unlockBtn.style.display = 'none';
    }
  }
  // Go-to-step button: visible whenever this job maps to a Create New
  // step (image / mesh / rig / anim). Clicking it opens the matching
  // project and scroll-expands its step card.
  const gotoBtn = document.getElementById('job-details-goto-step');
  if (gotoBtn) {
    const stepIdx = _jobStepIndex(j);
    gotoBtn.style.display = stepIdx > 0 ? '' : 'none';
    if (stepIdx > 0) {
      // On success, point at the RESULT ("generated item"); while running or
      // on error, point at the generation step (to watch / retry). Unified
      // label (was "Go to Image / 3D Mesh / Rig / Animation").
      gotoBtn.textContent = j.status === 'done' ? '→ Go to generated item' : '→ Go to generation';
    }
  }
}
