  catch (e) {
    console.warn('[re-skin] squelette illisible', e);
    customError(_i18nT('Could not read the skeleton of this rig.'), _i18nT('Re-skin only'));
    return;
  }
  lancerRigIA({ meshPath: source, squelette });
