// ============================================================
// MENU ⋮ DES VIGNETTES (test UX 2026-07-25)
// Remplace les boutons d'action qui apparaissaient PAR-DESSUS la
// vignette au survol par un menu déroulant ouvert au survol du ⋮.
// Proxy pattern : les boutons originaux restent dans le DOM (masqués
// par CSS) ; chaque item du menu relaie son .click() vers l'original,
// donc les handlers existants marchent sans aucune modification.
// ============================================================
(() => {
  const ACTION_SEL = ['.version-delete-btn', '.version-source-btn',
    '.version-mesh-btn', '.version-rig-btn', '.version-history-btn'].join(',');

  let menu = null;          // singleton #v-kebab-menu
  let anchorThumb = null;   // vignette dont le menu est ouvert
  let anchorKebab = null;
  let closeTimer = 0;

  function ensureMenu() {
    if (menu) return menu;
    menu = document.createElement('div');
    menu.id = 'v-kebab-menu';
    menu.addEventListener('mouseenter', () => clearTimeout(closeTimer));
    menu.addEventListener('mouseleave', scheduleClose);
    document.body.appendChild(menu);
    // Fermer si on scrolle/redimensionne (le menu est en position fixed).
    window.addEventListener('scroll', closeMenu, true);
    window.addEventListener('resize', closeMenu);
    return menu;
  }

  function scheduleClose() {
    clearTimeout(closeTimer);
    closeTimer = setTimeout(closeMenu, 280);
  }

  function closeMenu() {
    clearTimeout(closeTimer);
    if (menu) { menu.classList.remove('open'); menu.innerHTML = ''; }
    if (anchorKebab) anchorKebab.classList.remove('menu-open');
    anchorThumb = null; anchorKebab = null;
  }

  function openMenu(thumb, kebab) {
    const m = ensureMenu();
    closeMenu();
    const actions = Array.from(thumb.querySelectorAll(ACTION_SEL));
    if (!actions.length) return;
    anchorThumb = thumb; anchorKebab = kebab;
    kebab.classList.add('menu-open');
    for (const orig of actions) {
      const item = document.createElement('button');
      item.type = 'button';
      item.className = 'vkm-item'
        + (orig.classList.contains('version-delete-btn') ? ' vkm-delete' : '');
      const ico = document.createElement('span');
      ico.className = 'vkm-ico';
      ico.innerHTML = orig.innerHTML;
      const label = document.createElement('span');
      label.className = 'vkm-label';
      label.textContent = orig.getAttribute('title') || '';
      item.append(ico, label);
      item.addEventListener('click', (e) => {
        e.stopPropagation();
        closeMenu();
        orig.click();   // relaie vers le handler d'origine
      });
      m.appendChild(item);
    }
    // Position : sous le ⋮, aligné à droite ; remonte si déborde en bas.
    m.classList.add('open');
    const kr = kebab.getBoundingClientRect();
    const mw = m.offsetWidth, mh = m.offsetHeight;
    let left = Math.min(Math.max(8, kr.right - mw), window.innerWidth - mw - 8);
    let top = kr.bottom + 4;
    if (top + mh > window.innerHeight - 8) top = Math.max(8, kr.top - mh - 4);
    m.style.left = left + 'px';
    m.style.top = top + 'px';
  }

  function enhanceThumb(thumb) {
    if (thumb.dataset.vkm) return;
    if (!thumb.querySelector(ACTION_SEL)) return;   // rien à proposer
    thumb.dataset.vkm = '1';
    const kebab = document.createElement('button');
    kebab.type = 'button';
    kebab.className = 'v-kebab';
    kebab.title = 'Actions';   // traduit par la passe i18n des attributs title
    kebab.textContent = '\u22EE';   // ⋮
    kebab.addEventListener('mouseenter', () => openMenu(thumb, kebab));
    kebab.addEventListener('mouseleave', scheduleClose);
    kebab.addEventListener('click', (e) => {
      e.stopPropagation();
      if (anchorThumb === thumb) closeMenu();
      else openMenu(thumb, kebab);
    });
    thumb.appendChild(kebab);
  }

  function enhanceAll() {
    document.querySelectorAll('.version-thumb:not([data-vkm])').forEach(enhanceThumb);
    // Le strip a pu être re-rendu pendant que le menu était ouvert.
    if (anchorThumb && !anchorThumb.isConnected) closeMenu();
  }

  // Les strips se re-rendent par innerHTML → observer léger (childList).
  const mo = new MutationObserver((muts) => {
    for (const mu of muts) {
      for (const n of mu.addedNodes) {
        if (n.nodeType === 1 && (n.matches?.('.version-thumb')
            || n.querySelector?.('.version-thumb'))) {
          enhanceAll();
          return;
        }
      }
      for (const n of mu.removedNodes) {
        if (anchorThumb && n.nodeType === 1 && n.contains?.(anchorThumb)) {
          closeMenu();
        }
      }
    }
  });
  mo.observe(document.body, { childList: true, subtree: true });
  enhanceAll();
})();

// ============================================================
// MODALE CONNEXION CLOUD MyFabmesh (cert Store 10.1.2.10)
// Sur machine sans GPU NVIDIA, la génération d'images passe par
// le cloud → il faut une session (email + mot de passe du compte
// MyFabmesh, 50 crédits offerts à l'inscription). Retourne une
// Promise<boolean> : true = connecté.
// ============================================================
async function _openCloudSite(pathOrUrl) {
  const base = 'https://myfabmesh-cloud.fabien65400.workers.dev';
  const url = /^https?:/i.test(pathOrUrl) ? pathOrUrl : (base + pathOrUrl);
  // openExternal est exposé sous wizardAPI (pas meshyAPI) — bug initial.
  const _open = window.wizardAPI?.openExternal || window.meshyAPI?.openExternal;
  let r = null;
  try { r = _open ? await _open(url) : null; } catch (_) {}
  if (!r || r.ok === false) {
    try { await navigator.clipboard.writeText(url); } catch (_) {}
    showToast(_i18nT('Link copied to clipboard:') + ' ' + url, 'info', 6000);
  }
}

async function showCloudLoginModal() {
  return new Promise((resolve) => {
    const old = document.getElementById('cloud-login-overlay');
    if (old) old.remove();
    const ov = document.createElement('div');
    ov.id = 'cloud-login-overlay';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.65);z-index:100000;display:flex;align-items:center;justify-content:center;';
    ov.innerHTML = `
      <div style="background:#15151f;border:1px solid #3a3a4a;border-radius:12px;padding:22px;width:360px;box-shadow:0 12px 40px rgba(0,0,0,.6);">
        <h3 style="margin:0 0 6px;font-size:16px;color:#eee;" data-i18n>Sign in to MyFabmesh Cloud</h3>
        <p style="margin:0 0 14px;font-size:12px;color:#9aa;line-height:1.5;" data-i18n>No NVIDIA GPU was detected on this device, so images are generated on the MyFabmesh cloud. Sign in with your MyFabmesh account (new accounts get free credits).</p>
        <input id="cl-email" type="email" placeholder="Email" autocomplete="username"
               style="width:100%;box-sizing:border-box;margin-bottom:8px;padding:9px 10px;border-radius:8px;border:1px solid #3a3a4a;background:#0f0f16;color:#eee;font-size:13px;">
        <div style="position:relative;margin-bottom:6px;">
          <input id="cl-pass" type="password" placeholder="Password" autocomplete="current-password"
                 style="width:100%;box-sizing:border-box;padding:9px 34px 9px 10px;border-radius:8px;border:1px solid #3a3a4a;background:#0f0f16;color:#eee;font-size:13px;">
          <button type="button" id="cl-eye" title="Show password" tabindex="-1"
                  style="position:absolute;right:6px;top:50%;transform:translateY(-50%);background:transparent;border:none;color:#889;cursor:pointer;font-size:14px;padding:4px;line-height:1;">&#128065;</button>
        </div>
        <input id="cl-code" type="text" inputmode="numeric" maxlength="8" placeholder="6-digit code from your email" autocomplete="one-time-code"
               style="display:none;width:100%;box-sizing:border-box;margin-bottom:6px;padding:9px 10px;border-radius:8px;border:1px solid #3a3a4a;background:#0f0f16;color:#eee;font-size:13px;letter-spacing:2px;">
        <div id="cl-err" style="min-height:16px;font-size:11px;color:#f66;margin-bottom:8px;"></div>
        <div style="display:flex;gap:8px;justify-content:space-between;align-items:center;">
          <span style="display:flex;flex-direction:column;gap:3px;">
            <a href="#" id="cl-signup" style="font-size:11px;color:#8ab4ff;" data-i18n>Create an account</a>
            <a href="#" id="cl-forgot" style="font-size:11px;color:#8ab4ff;" data-i18n>Forgot password?</a>
          </span>
          <div style="display:flex;gap:8px;">
            <button id="cl-cancel" style="background:#2a2a3a;color:#ddd;border:1px solid #3a3a4a;border-radius:8px;padding:8px 14px;cursor:pointer;font-size:13px;" data-i18n>Cancel</button>
            <button id="cl-ok" style="background:linear-gradient(90deg,#e0447c,#8a5cf6);color:#fff;border:none;border-radius:8px;padding:8px 16px;cursor:pointer;font-size:13px;font-weight:600;" data-i18n>Sign in</button>
          </div>
        </div>
      </div>`;
    document.body.appendChild(ov);
    try { window.FabI18n?.apply?.(ov); } catch (_) {}
    const done = (v) => { ov.remove(); resolve(v); };
    ov.querySelector('#cl-cancel').onclick = () => {
      // Annuler PENDANT la confirmation laisse un compte cree mais non
      // confirme : sans un mot d'explication, l'utilisateur ne comprend pas
      // pourquoi sa prochaine inscription echouera (« adresse deja utilisee »)
      // ni ou est passe son code.
      if (mode === 'verify') {
        try {
          showToast(
            (typeof _i18nT === 'function'
              ? _i18nT('Your account was created but not confirmed. Sign in with the 6-digit code we emailed you.')
              : 'Your account was created but not confirmed. Sign in with the 6-digit code we emailed you.'),
            'info', 9000);
        } catch (_) {}
      }
      done(false);
    };
    /* PAS DE FERMETURE AU CLIC A COTE.
     *
     * Signale par le user le 2026-08-19, en creant un compte dans la VM : un
     * clic hors de la fenetre la faisait disparaitre, e-mail et mot de passe
     * saisis perdus — et, en etape de confirmation, le code a 6 chiffres avec.
     * Sur le parcours d'un testeur de certification, c'est une impasse
     * silencieuse : rien n'explique ce qui vient de se passer.
     *
     * La fenetre ne se ferme donc plus que par un geste EXPLICITE : le bouton
     * « Cancel ». Il reste toujours visible, donc aucun blocage — le piege du
     * refus n5 (une garde bien intentionnee qui enferme l'utilisateur) est
     * evite. On absorbe simplement le clic sur le fond. */
    ov.addEventListener('click', (e) => {
      if (e.target === ov) {
        e.stopPropagation();
        // Retour visuel : sans lui, l'utilisateur croit l'interface figee.
        const carte = ov.firstElementChild;
        if (carte) {
          carte.style.transition = 'transform .12s';
          carte.style.transform = 'scale(1.015)';
          setTimeout(() => { carte.style.transform = ''; }, 120);
        }
      }
    });
    const eye = ov.querySelector('#cl-eye');
    eye.onclick = () => {
      const inp = ov.querySelector('#cl-pass');
      const show = inp.type === 'password';
      inp.type = show ? 'text' : 'password';
      eye.style.color = show ? '#8ab4ff' : '#889';
      inp.focus();
    };
    /* ═══════════════════════════════════════════════════════════════
       INSCRIPTION SUR PLACE — la même fenêtre, trois états.

       « Create an account » ouvrait le NAVIGATEUR sur la page de connexion
       du site. C'était le seul chemin d'inscription de tout le produit, et
       le refus de certification n°2 portait exactement là-dessus :
       « the account creation feature is not functional ». Un testeur qui
       clique dessus quittait l'application — donc cessait de l'évaluer.

       États : 'signin' → 'signup' → 'verify'. Le code à six chiffres vient
       de l'e-mail Supabase (gabarits `{{ .Token }}` du dépôt : un code, pas
       un lien, parce qu'Outlook SafeLinks cassait les liens).
       ═══════════════════════════════════════════════════════════════ */
    let mode = 'signin';
    const els = {
      titre: ov.querySelector('h3'),
      texte: ov.querySelector('p'),
      email: ov.querySelector('#cl-email'),
      pass: ov.querySelector('#cl-pass'),
      code: ov.querySelector('#cl-code'),
      err: ov.querySelector('#cl-err'),
      ok: ov.querySelector('#cl-ok'),
      lienSignup: ov.querySelector('#cl-signup'),
      lienForgot: ov.querySelector('#cl-forgot'),
    };
    const setMode = (m) => {
      mode = m;
      els.err.textContent = '';
      els.err.style.color = '#f66';
      const T = (s) => (typeof _i18nT === 'function' ? _i18nT(s) : s);
      if (m === 'signin') {
        els.titre.textContent = T('Sign in to MyFabmesh Cloud');
        els.texte.textContent = T('No NVIDIA GPU was detected on this device, so images are generated on the MyFabmesh cloud. Sign in with your MyFabmesh account (new accounts get free credits).');
        els.pass.parentElement.style.display = '';
        els.pass.setAttribute('autocomplete', 'current-password');
        els.code.style.display = 'none';
        els.ok.textContent = T('Sign in');
        els.lienSignup.textContent = T('Create an account');
        els.lienForgot.style.display = '';
      } else if (m === 'signup') {
        els.titre.textContent = T('Create your MyFabmesh account');
        els.texte.textContent = T('New accounts get 15 free credits. Pick a password of at least 6 characters — we will email you a 6-digit confirmation code.');
        els.pass.parentElement.style.display = '';
        els.pass.setAttribute('autocomplete', 'new-password');
        els.code.style.display = 'none';
        els.ok.textContent = T('Create account');
        els.lienSignup.textContent = T('I already have an account');
        els.lienForgot.style.display = 'none';
      } else {
        els.titre.textContent = T('Confirm your email');
        els.texte.textContent = T('We sent a 6-digit code to your email address. Enter it below to finish creating your account.');
        els.pass.parentElement.style.display = 'none';
        els.code.style.display = '';
        els.ok.textContent = T('Confirm');
        els.lienSignup.textContent = T('Back to sign in');
        els.lienForgot.style.display = 'none';
        setTimeout(() => els.code.focus(), 50);
      }
    };
    els.lienSignup.onclick = (e) => {
      e.preventDefault();
      setMode(mode === 'signin' ? 'signup' : 'signin');
    };
    ov.querySelector('#cl-forgot').onclick = async (e) => {
      e.preventDefault();
      const email = ov.querySelector('#cl-email').value.trim();
      const err = ov.querySelector('#cl-err');
      if (!email) { err.textContent = _i18nT('Enter your email first.'); return; }
      err.style.color = '#f66';
      const r = await API.cloudRecover?.({ email });
      if (r?.success) {
        err.style.color = '#7ee787';
        err.textContent = _i18nT('Reset email sent — follow the link, then sign in here.');
      } else {
        err.textContent = r?.error || _i18nT('Could not send the email.');
      }
    };
    const submit = async () => {
      const T = (s) => (typeof _i18nT === 'function' ? _i18nT(s) : s);
      const email = els.email.value.trim();
      const pass = els.pass.value;
      const err = els.err;
      err.style.color = '#f66';

      if (mode === 'verify') {
        const code = els.code.value.trim();
        if (!code) { err.textContent = T('Enter the code from your email.'); return; }
        err.textContent = '';
        els.ok.disabled = true;
        const r = await API.cloudVerifySignup?.({ email, code });
        els.ok.disabled = false;
        if (r?.success) done(true);
        else err.textContent = r?.error || T('That code was not accepted.');
        return;
      }

      if (!email || !pass) { err.textContent = T('Email and password are required.'); return; }

      /* VALIDATION DE L'ADRESSE, AVANT TOUT APPEL RESEAU.
       *
       * Constate par le user le 2026-08-19 dans la VM : il avait saisi
       * « fabien65400hotmail.fr » — le @ manquait, probablement avale par le
       * clavier AZERTY de la machine virtuelle (AltGr passe mal). L'adresse
       * partait quand meme au serveur, qui repondait « Invalid login
       * credentials » : un message qui accuse le MOT DE PASSE alors que le
       * probleme est dans l'adresse. Un testeur en conclut que la connexion
       * ne fonctionne pas.
       *
       * Test volontairement permissif : on ne cherche pas a valider la norme
       * RFC, seulement a attraper la faute grossiere (@ absent, espace,
       * domaine sans point) avant de blamer l'utilisateur pour autre chose. */
      const adresseVraisemblable = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
      if (!adresseVraisemblable) {
        err.textContent = email.includes('@')
          ? T('This email address looks incomplete — check the part after the @.')
          : T('This email address is missing the @ sign.');
        try { els.email.focus(); els.email.select(); } catch (_) {}
        return;
      }

      if (mode === 'signup') {
        if (pass.length < 6) { err.textContent = T('Password must be at least 6 characters.'); return; }
        err.textContent = '';
        els.ok.disabled = true;
        const r = await API.cloudSignup?.({ email, password: pass });
        els.ok.disabled = false;
        if (!r?.success) {
          // ADRESSE DEJA INSCRITE — le cas se produit surtout apres une
          // inscription interrompue avant la confirmation. Sans ce
          // rattrapage, l'utilisateur boucle : il ne peut ni s'inscrire
          // (deja pris) ni se connecter (non confirme), et rien ne le lui dit.
          if (/already\s*registered|already\s*exists|User already/i.test(String(r?.error || ''))) {
            setMode('verify');
            err.style.color = '#7ee787';
            err.textContent = T('This email is already registered. Enter the 6-digit code we emailed you, or go back and sign in.');
            return;
          }
          err.textContent = r?.error || T('Could not create the account.');
          return;
        }
        // Confirmations desactivees cote Supabase : la session est deja la.
        if (r.codeRequis === false) { done(true); return; }
        setMode('verify');
        err.style.color = '#7ee787';
        err.textContent = T('Account created — check your email for the code.');
        return;
      }

      err.textContent = '';
      els.ok.disabled = true;
      const r = await API.cloudLogin({ email, password: pass });
      els.ok.disabled = false;
      if (r?.success) { done(true); return; }

      /* Les messages bruts de Supabase sont exacts mais trompeurs pour un
       * utilisateur : « Invalid login credentials » accuse le mot de passe
       * alors que la cause la plus frequente est de ne pas avoir encore de
       * compte, et « Email not confirmed » ne dit pas quoi faire. */
      const brut = String(r?.error || '');
      if (/invalid login credentials/i.test(brut)) {
        err.textContent = T('Wrong email or password. No account yet? Use "Create an account" below.');
      } else if (/email not confirmed|not confirmed/i.test(brut)) {
        err.textContent = T('This account is not confirmed yet. Enter the 6-digit code we emailed you.');
        setMode('verify');
      } else {
        err.textContent = brut || T('Sign-in failed.');
      }
    };
    els.ok.onclick = submit;
    els.pass.addEventListener('keydown', (e) => { if (e.key === 'Enter') submit(); });
    els.code.addEventListener('keydown', (e) => { if (e.key === 'Enter') submit(); });
    setTimeout(() => ov.querySelector('#cl-email')?.focus(), 50);
  });
}

// ============================================================
// SÉLECTEUR DE CALCUL LOCAL / CLOUD (passerelle desktop-cloud)
// Local = GPU NVIDIA de la machine (gratuit, illimité).
// Cloud = worker MyFabmesh (crédits du compte, marche partout).
// Sans GPU NVIDIA : Local désactivé, Cloud forcé (cert 10.1.2.10).
// ============================================================
window._computeMode = () => localStorage.getItem('fab-compute-mode') || 'local';
(async () => {
  const btnL = document.getElementById('ws-compute-local');
  const btnC = document.getElementById('ws-compute-cloud');
  const note = document.getElementById('ws-compute-note');
  if (!btnL || !btnC) return;

  const setNote = async (mode, gpu) => {
    if (!note) return;
    if (mode === 'cloud') {
      let email = '';
      try { const s = await API.cloudStatus?.(); if (s?.loggedIn) email = s.email || ''; } catch (_) {}
      // Prix d'une image AU REGLAGE COURANT (qualite, Turbo), lu dans la grille
      // et tenu a jour par _majMentionsPrixImage. « 3 credits per image »
      // etait ecrit en dur : faux des qu'on touchait la qualite ou le moteur.
      note.textContent = '';
      const prix = document.createElement('span');
      prix.id = 'ws-compute-prix';
      prix.setAttribute('data-i18n-skip', '');     // texte deja traduit par _i18nTf
      const qui = document.createElement('span');
      qui.id = 'ws-compute-qui';
      qui.setAttribute('data-i18n-skip', '');
      qui.dataset.email = email;
      note.append(prix, qui);
      try { window._majMentionsPrixImage?.(); } catch (_) {}
    } else {
      note.textContent = gpu?.name ? `GPU: ${gpu.name}` : '';
    }
  };

  const apply = async (mode, gpu) => {
    localStorage.setItem('fab-compute-mode', mode);
    btnL.classList.toggle('active', mode === 'local');
    btnC.classList.toggle('active', mode === 'cloud');
    await setNote(mode, gpu);
  };

  let gpu = { hasNvidia: true, name: '' };
  try { gpu = await API.gpuStatus?.() || gpu; } catch (_) {}

  // Règle produit (2026-07-26) : à CHAQUE lancement, le mode est déterminé
  // par le matériel — GPU NVIDIA → Local, sinon → Cloud. Le choix reste
  // modifiable pendant la session mais n'est pas persistant entre lancements.
  localStorage.setItem('fab-compute-mode', gpu.hasNvidia ? 'local' : 'cloud');
  try { API.setComputeMode?.(gpu.hasNvidia ? 'local' : 'cloud'); } catch (_) {}

  if (gpu.hasNvidia) {
    // Machine équipée : local par défaut, cloud OPT-IN via les Réglages
    // (switch « Cloud generation »). La ligne Compute du panneau image ne
    // s'affiche que quand le mode Cloud est actif — indicateur + retour
    // rapide au Local, sans polluer l'UI des utilisateurs 100 % locaux.
    const row = btnL.closest('.form-row');
    const syncRow = async () => {
      const m = _computeMode();
      try { API.setComputeMode?.(m); } catch (_) {}
      if (row) row.style.display = (m === 'cloud') ? '' : 'none';
      await apply(m, gpu);
      try { window._applyCloudCostPill?.(); } catch (_) {}
      try { window._refreshTopbarCredits?.(); } catch (_) {}
      try { window._applyToolPills?.(); } catch (_) {}
      try { window._applyMeshCostPill?.(); } catch (_) {}
      try { window._applyCloudFeatureMask?.(); } catch (_) {}
      try { window._applyRigAnimPills?.(); } catch (_) {}
      try { window._applyHardwareCardMask?.(); } catch (_) {}
      // Options ignorees par le serveur en Cloud, prix des fenetres de
      // validation, mention du prix par image ; grille chargee si inconnue.
      try { window._masquerOptionsSansEffetCloud?.(); } catch (_) {}
      try { window._majTousLesPrix?.(); } catch (_) {}
      try { if (m === 'cloud' && !window._prix) window._chargerPrix?.(); } catch (_) {}
    };
    btnL.addEventListener('click', () => { localStorage.setItem('fab-compute-mode', 'local'); syncRow(); });
    btnC.addEventListener('click', () => { localStorage.setItem('fab-compute-mode', 'cloud'); syncRow(); });
    window._syncComputeRow = syncRow;   // appelé par le switch des Réglages
    await syncRow();
    return;
  }

  // Machine SANS GPU NVIDIA (testeurs Store, laptops) : Cloud forcé,
  // Local grisé, solde + lien de recharge vers le SITE (pas d'achat in-app
  // → couvert par la déclaration 10.8.2 de Partner Center).
  btnL.disabled = true;
  btnL.title = (typeof _i18nT === 'function')
    ? _i18nT('No NVIDIA GPU detected — local generation unavailable on this device')
    : 'No NVIDIA GPU detected — local generation unavailable on this device';
  await apply('cloud', gpu);
  // Le mode Cloud est connu maintenant : options ignorees par le serveur et
  // prix reposes (ils ont pu etre calcules avec le mode de la session d'avant).
  try { window._masquerOptionsSansEffetCloud?.(); } catch (_) {}
  try { window._majTousLesPrix?.(); } catch (_) {}
  if (note) {
    const buy = document.createElement('a');
    buy.href = '#';
    buy.textContent = (typeof _i18nT === 'function') ? _i18nT('Buy credits') : 'Buy credits';
    buy.style.cssText = 'margin-left:8px;color:#8ab4ff;';
    buy.onclick = (e) => { e.preventDefault(); _openCloudSite('/buy'); };
    note.appendChild(buy);
  }
  // Pas d'autre listener : sans GPU le mode est Cloud et ne peut pas changer.
})();

// ============================================================
// RÉGLAGES > CLOUD GENERATION — switch Local/Cloud + compte
// Écrit la même clé localStorage 'fab-compute-mode' que le
// toggle du panneau image (window._syncComputeRow les relie).
// Sans GPU NVIDIA : Local grisé, Cloud forcé.
// ============================================================
(async () => {
  const bl = document.getElementById('set-compute-local');
  const bc = document.getElementById('set-compute-cloud');
  const note = document.getElementById('set-compute-note');
  const acct = document.getElementById('set-cloud-account');
  const bLogin = document.getElementById('set-cloud-login');
  const bLogout = document.getElementById('set-cloud-logout');
  if (!bl || !bc) return;

  let gpu = { hasNvidia: true, name: '' };
  try { gpu = await API.gpuStatus?.() || gpu; } catch (_) {}
  if (!gpu.hasNvidia) {
    localStorage.setItem('fab-compute-mode', 'cloud');
    bl.disabled = true;
    bl.title = (typeof _i18nT === 'function')
      ? _i18nT('No NVIDIA GPU detected — local generation unavailable on this device')
      : 'No NVIDIA GPU detected — local generation unavailable on this device';
  }

  const refresh = async () => {
    const mode = _computeMode();
    try { API.setComputeMode?.(mode); } catch (_) {}
    bl.classList.toggle('active', mode === 'local');
    bc.classList.toggle('active', mode === 'cloud');
    // Pas de rappel du prix ici : déjà indiqué dans la description au-dessus.
    if (note) note.textContent = (mode === 'cloud') ? '' : (gpu.name || '');
    try {
      const s = await API.cloudStatus?.();
      const actions = document.getElementById('set-account-actions');
      if (s?.loggedIn) {
        if (acct) acct.textContent = s.email + (s.credits != null ? ' · ' + _i18nTf('{x} credits', s.credits) : '');
        if (bLogin) bLogin.style.display = 'none';
        if (bLogout) bLogout.style.display = '';
        if (actions) actions.style.display = 'flex';
      } else {
        if (acct) acct.textContent = (typeof _i18nT === 'function') ? _i18nT('Not signed in') : 'Not signed in';
        if (bLogin) bLogin.style.display = '';
        if (bLogout) bLogout.style.display = 'none';
        if (actions) actions.style.display = 'none';
      }
    } catch (_) {}
    try { await window._syncComputeRow?.(); } catch (_) {}
    try { window._applyCloudCostPill?.(); } catch (_) {}
    try { window._refreshTopbarCredits?.(); } catch (_) {}
    try { window._applyToolPills?.(); } catch (_) {}
    try { window._applyMeshCostPill?.(); } catch (_) {}
    try { window._applyCloudFeatureMask?.(); } catch (_) {}
    try { window._applyRigAnimPills?.(); } catch (_) {}
    try { window._applyHardwareCardMask?.(); } catch (_) {}
    try { window._masquerOptionsSansEffetCloud?.(); } catch (_) {}
    try { window._majTousLesPrix?.(); } catch (_) {}
    try { if (mode === 'cloud' && !window._prix) window._chargerPrix?.(); } catch (_) {}
  };

  bl.addEventListener('click', () => {
    if (bl.disabled) return;
    localStorage.setItem('fab-compute-mode', 'local');
    refresh();
  });
  // Section Compte (2026-09-28, alignee sur le web)
  document.getElementById('set-account-topup')?.addEventListener('click', () => _openCloudSite('/buy'));
  document.getElementById('set-account-manage')?.addEventListener('click', () => _openCloudSite('/app/?reglages=compte'));
  document.getElementById('set-account-history')?.addEventListener('click', () => {
    document.getElementById('modal-settings')?.classList.add('hidden');
    document.getElementById('btn-history')?.click();
  });
  // L'historique est dans les parametres : l'icone de la barre faisait doublon.
  const histoBarre = document.getElementById('btn-history');
  if (histoBarre) histoBarre.style.display = 'none';
  bc.addEventListener('click', () => {
    localStorage.setItem('fab-compute-mode', 'cloud');
    refresh();
  });
  bLogin?.addEventListener('click', async () => {
    const ok = await showCloudLoginModal();
    if (ok) refresh();
  });
  bLogout?.addEventListener('click', async () => {
    try { await API.cloudLogout?.(); } catch (_) {}
    refresh();
  });

  refresh();
})();

// ============================================================
// PASSERELLE CLOUD (2026-07-26) — partage vers la bibliothèque
// web + navigateur Bibliothèque cloud / Marketplace.
// ============================================================
async function _cloudShare(filePath, kindLabel) {
  const p = state.currentProject;
  showToast(`Sending ${kindLabel} to your cloud library…`, 'info', 8000);
  let r = await API.cloudShareAsset({ filePath, projectName: p?.name || 'desktop' });
  if (r?.needsCloudLogin) {
    const ok = await showCloudLoginModal();
    if (ok) r = await API.cloudShareAsset({ filePath, projectName: p?.name || 'desktop' });
    else return;
  }
  if (r?.success) showToast(`${kindLabel} sent — visible in your web library.`, 'success');
  else showToast(`Cloud share failed: ${r?.error || 'unknown'}`, 'error');
}

document.getElementById('ws-cloud-share-img-btn')?.addEventListener('click', async () => {
  const p = state.currentProject;
  const target = editTarget(p);
  if (!target) { showToast('Pick an image first.', 'error'); return; }
  await _cloudShare(target, 'Image');
});

document.getElementById('ws-cloud-share-mesh-btn')?.addEventListener('click', async () => {
  const m = getCurrentMeshObj();
  if (!m?.path) { showToast('Pick a mesh first.', 'error'); return; }
  await _cloudShare(m.path, 'Mesh');
});

// ---- Navigateur Bibliothèque cloud / Marketplace ----
async function showCloudLibraryModal() {
  const old = document.getElementById('cloud-lib-overlay');
  if (old) old.remove();
  const ov = document.createElement('div');
  ov.id = 'cloud-lib-overlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.65);z-index:100000;display:flex;align-items:center;justify-content:center;';
  ov.innerHTML = `
    <div style="background:#15151f;border:1px solid #3a3a4a;border-radius:12px;padding:18px;width:min(860px,92vw);max-height:86vh;display:flex;flex-direction:column;box-shadow:0 12px 40px rgba(0,0,0,.6);">
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">
        <h3 style="margin:0;font-size:16px;color:#eee;flex:1;" data-i18n>Cloud library</h3>
        <div class="compute-toggle">
          <button type="button" class="ct-btn active" id="clb-tab-mine" data-i18n>My assets</button>
          <button type="button" class="ct-btn" id="clb-tab-market" data-i18n>Marketplace</button>
        </div>
        <button id="clb-site" style="background:#2a2a3a;color:#8ab4ff;border:1px solid #3a3a4a;border-radius:8px;padding:6px 12px;cursor:pointer;font-size:12px;" title="Open your MyFabmesh account in the browser">&#127760; <span data-i18n>Open the website</span></button>
        <button id="clb-close" style="background:#2a2a3a;color:#ddd;border:1px solid #3a3a4a;border-radius:8px;padding:6px 12px;cursor:pointer;">&#10005;</button>
      </div>
      <div id="clb-body" style="overflow:auto;flex:1;min-height:220px;color:#9aa;font-size:12px;">Loading…</div>
    </div>`;
  document.body.appendChild(ov);
  try { window.FabI18n?.apply?.(ov); } catch (_) {}
  ov.querySelector('#clb-close').onclick = () => ov.remove();
  ov.querySelector('#clb-site').onclick = () => {
    _openCloudSite(_clbTab === 'market' ? '/market' : '/');
  };
  ov.addEventListener('click', (e) => { if (e.target === ov) ov.remove(); });

  const body = ov.querySelector('#clb-body');
  const grid = (inner) => `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;">${inner}</div>`;
  const card = ({ img, title, sub, btnLabel, btnData }) => `
    <div style="background:#1a1a24;border:1px solid #2a2a36;border-radius:8px;padding:8px;display:flex;flex-direction:column;gap:6px;">
      <div style="height:100px;display:flex;align-items:center;justify-content:center;background:#0f0f16;border-radius:6px;overflow:hidden;">
        ${img ? `<img src="${img}" loading="lazy" style="max-width:100%;max-height:100%;object-fit:contain;" onerror="this.outerHTML='<span style=&quot;font-size:34px;opacity:.5;&quot;>&#128444;&#65039;</span>'">` : '<span style="font-size:34px;opacity:.5;">&#129482;</span>'}
      </div>
      <div style="font-size:11px;color:#ccd;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${title}">${title}</div>
      ${sub ? `<div style="font-size:10px;color:#778;">${sub}</div>` : ''}
      <button class="clb-dl primary-btn" style="padding:5px 8px;font-size:11px;" ${btnData}>${btnLabel}</button>
    </div>`;

  const destProject = () => (state.currentProject?.name || 'cloud_import').replace(/[^a-zA-Z0-9_-]/g, '_');
  // Les URLs du worker peuvent etre relatives (/r2/<cle>?exp&sig) : dans
  // Electron elles se resoudraient contre l'app -> prefixer par le site.
  const CLB_ORIGIN = 'https://myfabmesh-cloud.fabien65400.workers.dev';
  const abs = (u) => {
    if (!u || typeof u !== 'string') return null;
    if (/^https?:/i.test(u)) return u;
    if (u.startsWith('/')) return CLB_ORIGIN + u;
    return CLB_ORIGIN + '/r2/' + u;   // cle R2 nue (non signee: peut echouer)
  };

  function wireDownloads() {
    body.querySelectorAll('.clb-dl').forEach((b) => {
      b.addEventListener('click', async () => {
        b.disabled = true;
        const url = b.dataset.url || null;
        const marketId = b.dataset.market || null;
        const buy = b.dataset.buy;
        if (buy) { _openCloudSite(buy); b.disabled = false; return; }
        const fname = b.dataset.fname || `cloud_${Date.now()}.png`;
        const isMesh = /\.(glb|fbx)$/i.test(fname);
        // Le main construit le chemin absolu (MESHES_DIR / IMAGES_DIR).
        const r = await API.cloudDownloadItem({
          url, marketId, fname,
          kind: isMesh ? 'mesh' : 'image',
          project: destProject(),
        });
        if (r?.needsCloudLogin) {
          const ok = await showCloudLoginModal();
          if (ok) { b.disabled = false; b.click(); return; }
        }
        if (r?.success) {
          showToast(`Downloaded: ${fname}`, 'success');
          try { await reloadCurrentProject(); } catch (_) {}
          try { refreshProjectsPage(); } catch (_) {}
        } else if (/404/.test(r?.error || '')) {
          showToast(_i18nT('This asset is no longer available (the cloud file has expired).'), 'error', 6000);
        } else {
          showToast(`Download failed: ${r?.error || 'unknown'}`, 'error');
        }
        b.disabled = false;
      });
    });
  }

  async function loadMine() {
    body.textContent = 'Loading…';
    const r = await API.cloudListLibrary();
    if (r?.needsCloudLogin) {
      body.innerHTML = '<div style="padding:30px;text-align:center;">Sign in to see your cloud library.<br><br><button id="clb-login" class="primary-btn" style="padding:6px 14px;">Sign in</button></div>';
      body.querySelector('#clb-login').onclick = async () => { if (await showCloudLoginModal()) loadMine(); };
      return;
    }
    if (!r?.success) { body.textContent = `Error: ${r?.error || 'unknown'}`; return; }
    const cards = [];
    for (const proj of (r.projects || [])) {
      for (const imgUrl of (proj.images || []).slice(0, 60)) {
        let fname = `${proj.name}_${(imgUrl.split('/').pop() || 'img').split('?')[0]}`.replace(/[^a-zA-Z0-9_.-]/g, '_');
        if (!fname.toLowerCase().endsWith('.png')) fname += '.png';
        cards.push(card({ img: abs(imgUrl), title: proj.name, sub: 'image',
          btnLabel: '&#11015; Import', btnData: `data-url="${(abs(imgUrl) || '').replace(/"/g, '&quot;')}" data-fname="${fname}"` }));
      }
    }
    for (const m of (r.meshes || []).slice(0, 120)) {
      const fname = (m.filename || `mesh_${Date.now()}.glb`).replace(/[^a-zA-Z0-9_.-]/g, '_');
      cards.push(card({ img: abs(m.thumb), title: m.filename || 'mesh', sub: m.projectName || 'mesh',
        btnLabel: '&#11015; Import', btnData: `data-url="${(abs(m.url) || '').replace(/"/g, '&quot;')}" data-fname="${fname}"` }));
    }
    body.innerHTML = cards.length ? grid(cards.join('')) : '<div style="padding:30px;text-align:center;">Your cloud library is empty.</div>';
    wireDownloads();
  }

  async function loadMarket() {
    body.textContent = 'Loading…';
    const r = await API.cloudListMarket();
    // Même UX inline que loadMine() : panneau + bouton « Sign in », plutôt
    // qu'un « Error: Cloud session expired » sans issue (cert 10.1.2.10).
    if (r?.needsCloudLogin) {
      body.innerHTML = '<div style="padding:30px;text-align:center;">Sign in to browse the marketplace.<br><br><button id="clb-login" class="primary-btn" style="padding:6px 14px;">Sign in</button></div>';
      body.querySelector('#clb-login').onclick = async () => { if (await showCloudLoginModal()) loadMarket(); };
      return;
    }
    if (!r?.success) { body.textContent = `Error: ${r?.error || 'unknown'}`; return; }
    const ownedIds = new Set((r.owned || []).map(o => o.id || o.listing_id || o));
    const cards = (r.listings || []).map((l) => {
      const free = !l.price_cents;
      const owned = ownedIds.has(l.id);
      let fname = `market_${(l.title || l.id).replace(/[^a-zA-Z0-9_-]/g, '_')}`;
      fname += (l.asset_kind === 'mesh') ? '.glb' : '.png';
      const canGet = free || owned;
      const ownedLbl = owned ? 'Download (owned)' : 'Download (free)';
      const priceLbl = `&#128722; ${(l.price_cents / 100).toFixed(2)} ${l.currency || 'EUR'}`;
      const btnLabel = canGet ? ('&#11015; ' + ownedLbl) : priceLbl;
      const btnData = canGet
        ? `data-market="${l.id}" data-fname="${fname}"`
        : 'data-buy="https://myfabmesh-cloud.fabien65400.workers.dev/market"';
      return card({ img: abs(l.asset_url || l.mesh_url), title: l.title || l.id,
        sub: `${l.asset_kind || ''} · ${l.author_display || ''} · ${l.downloads || 0}&#11015;`,
        btnLabel, btnData });
    });
    body.innerHTML = cards.length ? grid(cards.join('')) : '<div style="padding:30px;text-align:center;">No marketplace listings yet.</div>';
    wireDownloads();
  }

  const tMine = ov.querySelector('#clb-tab-mine');
  const tMarket = ov.querySelector('#clb-tab-market');
  let _clbTab = 'mine';
  const _siteLbl = ov.querySelector('#clb-site span');
  const _updSite = () => {
    if (_siteLbl) {
      const key = (_clbTab === 'market') ? 'Open the marketplace' : 'Open the website';
      _siteLbl.textContent = (typeof _i18nT === 'function') ? _i18nT(key) : key;
    }
  };
  tMine.onclick = () => { _clbTab = 'mine'; tMine.classList.add('active'); tMarket.classList.remove('active'); _updSite(); loadMine(); };
  tMarket.onclick = () => { _clbTab = 'market'; tMarket.classList.add('active'); tMine.classList.remove('active'); _updSite(); loadMarket(); };
  _updSite();
  loadMine();
}

document.getElementById('btn-cloud-library')?.addEventListener('click', showCloudLibraryModal);


// ============================================================
// PASTILLE COÛT CLOUD ⚡ (mode Cloud uniquement) — même pastille
// jaune que le site web sur le bouton Générer (2 crédits × N).
// Idempotent : rappelé après chaque réécriture du label du bouton.
// ============================================================
/* ═══════════════════════════════════════════════════════════════════
   GRILLE TARIFAIRE — LUE, JAMAIS ECRITE EN DUR

   Audit du 2026-08-18 : tous les prix affiches par le desktop etaient des
   constantes, et TOUS avaient derive sous le prix reellement facture :

       maillage « fast »   annonce 1   facture 8    (x8)
       maillage balanced   annonce 2   facture 10
       maillage quality    annonce 4   facture 13
       image               annonce 2   facture 3    (par image)

   Toujours dans le meme sens — annoncer moins que ce qu'on preleve est une
   pratique commerciale trompeuse. Le site web se synchronisait deja sur
   `/api/pricing` ; le desktop ne l'appelait NULLE PART.

   `_prix` est donc la seule source. Tant qu'elle n'est pas chargee, on
   n'affiche AUCUN chiffre plutot qu'un chiffre invente : c'est exactement
   cette habitude du chiffre « par defaut » qui a produit l'ecart.
   ═══════════════════════════════════════════════════════════════════ */
window._prix = null;
window._prixFeatures = null;

/** Repose TOUTES les pastilles et mentions de prix (grille chargee, bascule
 *  Local/Cloud). Chaque fonction est idempotente et retire son chiffre quand
 *  la grille est inconnue ou que le mode est Local. */
window._majTousLesPrix = function () {
  try { window._applyCloudCostPill?.(); } catch (_) {}
  try { window._applyMeshCostPill?.(); } catch (_) {}
  try { window._applyToolPills?.(); } catch (_) {}
  try { window._applyRigAnimPills?.(); } catch (_) {}
  try { window._applyValidationPills?.(); } catch (_) {}
  try { window._majMentionsPrixImage?.(); } catch (_) {}
};

window._chargerPrix = async function (opts) {
  try {
    const r = await API.cloudPricing?.(opts || {});
    if (r && r.success && r.prices) {
      window._prix = r.prices;
      window._prixFeatures = r.features || null;
      // Reposer toutes les pastilles avec les vrais prix.
      window._majTousLesPrix();
      return true;
    }
  } catch (_) {}
  return false;
};

/** Prix d'une operation, ou null si la grille n'est pas encore connue. */
window._prixDe = function (cle) {
  const p = window._prix;
  if (!p || typeof p[cle] !== 'number') return null;
  return p[cle];
};

/** Prix d'UNE image au reglage courant — MEME formule que le worker
 *  (handleGenerateImage + _prixImageSelonPas, worker.ts) : le tarif
 *  `text2image` vaut pour 30 pas ; au prorata des pas du curseur Quality
 *  (bornes 10..60, comme le worker), arrondi, jamais moins d'1 credit. Le
 *  moteur « Fast (Turbo) » est facture au prix de 4 pas, quel que soit le
 *  curseur. Audit du 2026-09-30 : la pastille multipliait le tarif de 30 pas
 *  par le nombre d'images sans regarder ni la qualite ni le Turbo (60 pas :
 *  3 annonces, 6 factures ; Turbo : 3 annonces, 1 facture).
 *  Rend { prix, pas, turbo }, ou null si la grille n'est pas connue. */
window._prixImage = function () {
  const tarif30 = window._prixDe('text2image');
  if (tarif30 == null) return null;
  const turbo = document.getElementById('ws-engine')?.value === 'local-lightning';
  const pas = turbo ? 4
    : Math.max(10, Math.min(60, Math.round(Number(document.getElementById('ws-quality')?.value) || 30)));
  return { prix: Math.max(1, Math.round(tarif30 * pas / 30)), pas, turbo };
};

/** Pose, met a jour ou retire la pastille ⚡ d'un bouton. `prix` absent, nul ou
 *  non numerique : AUCUNE pastille (grille inconnue, mode Local, outil gratuit).
 *  `grande` : format des boutons Generate ; sinon format compact des outils. */
window._posePastille = function (btn, prix, grande = false) {
  if (!btn) return;
  let pill = btn.querySelector('.generate-cost-pill');
  if (!(typeof prix === 'number' && prix > 0)) { if (pill) pill.remove(); return; }
  if (!pill) {
    pill = document.createElement('span');
    pill.className = 'generate-cost-pill';
    if (!grande) pill.style.cssText = 'font-size:10px;padding:1px 7px;margin-left:6px;';
    pill.innerHTML = '<span class="generate-cost-bolt">&#9889;</span><span class="gcp-val"></span>';
    btn.appendChild(pill);
  }
  const v = pill.querySelector('.gcp-val');
  if (v) v.textContent = String(prix);
};

window._applyCloudCostPill = function (btn) {
  try {
    if (!btn) btn = document.getElementById('ws-generate-image');
    if (!btn) return;
    const cloud = (typeof window._computeMode === 'function') && window._computeMode() === 'cloud';
    // Grille pas encore chargee : pas de pastille du tout. Un chiffre faux
    // vaut moins que pas de chiffre.
    const img = cloud ? window._prixImage() : null;
    // En mode Cloud TOUTES les images demandees partent (lots de 4 au plus,
    // cloud_fallback.generateImages) ; vues de dos et etapes de construction ne
    // partent pas (bouton Generate) : rien d'autre n'est facture.
    const n = Math.max(1, parseInt(document.getElementById('ws-count')?.value, 10) || 4);
    window._posePastille(btn, img ? n * img.prix : null, true);
    const pill = btn.querySelector('.generate-cost-pill');
    if (pill && img) pill.title = `${n} × ${img.prix}`;
  } catch (_) {}
};
// Nombre d'images, qualite et moteur changent le prix : pastille ET mention
// « credits par image » de la ligne Compute suivent.
['ws-count', 'ws-quality', 'ws-engine'].forEach((id) => {
  const el = document.getElementById(id);
  const maj = () => { window._applyCloudCostPill(); window._majMentionsPrixImage?.(); };
  el?.addEventListener('change', maj);
  el?.addEventListener('input', maj);
});
window._applyCloudCostPill();

/** Mentions ECRITES du prix d'une image (plus « 3 credits per image » en dur) :
 *  - Reglages > Cloud generation : prix a la qualite par defaut (30 pas) ;
 *  - ligne Compute du panneau image (mode Cloud) : prix au reglage COURANT.
 *  Grille inconnue : la mention disparait. */
window._majMentionsPrixImage = function () {
  try {
    const tarif30 = window._prixDe('text2image');
    const wrap = document.getElementById('set-cloud-prix-image');
    const val = document.getElementById('set-cloud-prix-image-val');
    if (wrap && val) {
      const p = tarif30 == null ? null : Math.max(1, Math.round(tarif30));
      wrap.hidden = p == null;
      if (p != null) {
        val.textContent = _i18nTf(p === 1 ? '{x} credit per image (default quality)'
          : '{x} credits per image (default quality)', p);
      }
    }
    const prixEl = document.getElementById('ws-compute-prix');
    if (prixEl) {
      const img = window._prixImage();
      prixEl.textContent = !img ? ''
        : _i18nTf(img.prix === 1 ? '{x} credit per image' : '{x} credits per image', img.prix);
      const qui = document.getElementById('ws-compute-qui');
      if (qui) qui.textContent = qui.dataset.email ? (prixEl.textContent ? ' — ' : '') + qui.dataset.email : '';
    }
  } catch (_) {}
};

// ============================================================
// PASTILLE COÛT CLOUD ⚡ SUR « GÉNÉRER 3D » (mode Cloud) — prix
// réels du worker (PRICING_DEFAULTS) : preset + add-ons cochés.
// Idempotent : rappelé après chaque réécriture du label du bouton.
// ============================================================
window._applyMeshCostPill = function (btn) {
  try {
    if (!btn) btn = document.getElementById('ws-generate-mesh');
    if (!btn) return;
    const cloud = (typeof window._computeMode === 'function') && window._computeMode() === 'cloud';
    let pill = btn.querySelector('.generate-cost-pill');
    if (!cloud) { if (pill) pill.remove(); return; }
    // Prix LUS dans la grille (voir window._prix). Les anciennes constantes
    // { fast: 1, balanced: 2, quality: 4, ultra_8k: 8 } annonçaient jusqu'à
    // HUIT FOIS moins que la facturation réelle (8, 10, 13, 16).
    const preset = document.getElementById('ws-trellis2-preset')?.value || 'fast';
    const CLE_PRESET = {
      fast: 'mesh_fast', balanced: 'mesh_balanced',
      quality: 'mesh_quality', ultra_8k: 'mesh_ultra_8k',
    };
    const base = window._prixDe(CLE_PRESET[preset] || 'mesh_fast');
    if (base == null) { if (pill) pill.remove(); return; }   // grille inconnue : pas de chiffre

    const on = (id) => !!document.getElementById(id)?.checked;
    const plus = (id, cle) => { if (on(id)) { const p = window._prixDe(cle); if (p != null) cost += p; } };
    let cost = base;
    plus('ws-trellis2-multiref', 'mesh_multiref');
    plus('ws-trellis2-rectify', 'mesh_rectify');
    // Ultra Q l'emporte sur Quality+ : le worker ne facture pas les deux.
    if (!on('ws-trellis2-ultra-q')) plus('ws-trellis2-quality-plus', 'mesh_quality_plus');
    plus('ws-trellis2-ultra-q', 'mesh_ultra_q');
    // ultra_hd est ignoré par le worker quand le preset est déjà ultra_8k.
    if (preset !== 'ultra_8k') plus('ws-trellis2-ultra-hd', 'mesh_ultra_hd');
    // TEXTURE SMOOTH : appliquee ET facturee par le worker (creditCost,
    // mesh_smooth) depuis le 2026-09-24. La pastille l'ignorait alors que le
    // profil d'asset la COCHE pour les objets durs (vehicule, batiment,
    // arme…) : 1 credit preleve sans etre annonce (audit du 2026-09-30).
    plus('ws-trellis2-smooth', 'mesh_smooth');
    // Etapes de construction 3D lancees juste apres le maillage (tarif a part).
    const chantier = document.getElementById('ws-3d-buildstages');
    if (chantier?.checked && chantier.closest('.form-row')?.style.display !== 'none') {
      const pc = window._prixDe('construction3d'); if (pc != null) cost += pc;
    }
    // SUPPLEMENT « MAX TRIANGLES » (audit release 1.0.36, BLOQUANT) : le worker
    // l'ajoute toujours (creditCost -> _supplementTriangles), la pastille
    // l'oubliait : a 10 M elle annoncait ~18 credits pour ~68 debites.
    // Meme formule que le worker et que le site.
    const trisSel = document.getElementById('ws-trellis2-tris');
    const brut = !trisSel ? 500000 : trisSel.value === 'custom'
      ? parseInt(document.getElementById('ws-trellis2-tris-custom')?.value || '500000', 10)
      : parseInt(trisSel.value, 10);
    const tris = Math.max(500, Math.min(10000000, brut || 500000));
    const courbe = Math.max(1, (window._prixDe('mesh_tris_courbe_pct') ?? 130) / 100);
    cost += Math.max(window._prixDe('mesh_tris_base') ?? 1,
                     Math.ceil((window._prixDe('mesh_tris_500k') ?? 1) * Math.pow(tris / 500000, courbe) - 1e-9));
    // NE SONT PAS COMPTÉS, et c'est volontaire : refine et face_fix figurent
    // dans OPTIONS_SANS_EFFET_CLOUD (worker.ts) et sont neutralisés AVANT le
    // calcul du prix. Les facturer à l'écran faisait croire à l'utilisateur
    // qu'il achetait un raffinement qui n'aurait jamais lieu — le site web,
    // lui, masque déjà ces cases en mode Cloud (_OPTIONS_MORTES_CLOUD ici).
    if (!pill) {
      pill = document.createElement('span');
      pill.className = 'generate-cost-pill';
      pill.innerHTML = '<span class="generate-cost-bolt">&#9889;</span><span class="gcp-val"></span>';
      btn.appendChild(pill);
    }
    const v = pill.querySelector('.gcp-val');
    if (v) v.textContent = String(cost);
  } catch (_) {}
};
// Nos listeners s'enregistrent APRÈS ceux de l'ETA (_updateGenButtonsEstimate),
// donc ils re-posent la pastille après la réécriture du textContent (qui
// détruit les enfants du bouton).
[
  'ws-trellis2-preset', 'ws-trellis2-multiref', 'ws-trellis2-refine',
  'ws-trellis2-rectify', 'ws-trellis2-quality-plus', 'ws-trellis2-ultra-q',
  'ws-trellis2-ultra-hd', 'ws-trellis2-face-fix', 'ws-trellis2-smooth',
  'ws-trellis2-tris', 'ws-trellis2-tris-custom', 'ws-3d-buildstages',
].forEach(id => {
  const el = document.getElementById(id);
  el?.addEventListener('change', () => window._applyMeshCostPill());
  if (id === 'ws-trellis2-tris-custom') el?.addEventListener('input', () => window._applyMeshCostPill());
});
window._applyMeshCostPill();

/* ═══════════════════════════════════════════════════════════════════
   CHARGEMENT DE LA GRILLE + MASQUAGE DES OPTIONS SANS EFFET

   La grille est chargée au démarrage puis rafraîchie toutes les 5 minutes,
   comme le fait déjà le site web. Un prix ajusté par l'administrateur suit
   donc l'application sans re-livraison.

   Et on masque en mode Cloud les options que le serveur neutralise
   (`OPTIONS_SANS_EFFET_CLOUD`, worker.ts). Les laisser cochables revenait à
   vendre un raffinement qui n'a jamais lieu — le site web les masque depuis
   longtemps (`removeUnimplementedPaidOptions`), le desktop les affichait
   encore. « Texture smooth » RETIREE de la liste le 2026-09-30 : le worker
   l'applique et la facture depuis le 2026-09-24 ; masquee mais cochee par le
   profil d'asset, elle etait facturee sans etre visible (_OPTIONS_MORTES_CLOUD).
   ═══════════════════════════════════════════════════════════════════ */
window._masquerOptionsSansEffetCloud = function () {
  try {
    const cloud = (typeof window._computeMode === 'function') && window._computeMode() === 'cloud';
    for (const id of _OPTIONS_MORTES_CLOUD) {
      const el = document.getElementById(id);
      if (!el) continue;
      // On remonte au label pour masquer la ligne entière, pas seulement la
      // case à cocher orpheline.
      //
      // setProperty(..., 'important') est OBLIGATOIRE : la feuille de style
      // impose `.inline-check { display: inline-flex !important }`
      // (index2.css:3885), qui écrasait un simple `style.display = 'none'`.
      // Constaté au banc : le style en ligne valait bien 'none' alors que le
      // style calculé restait 'flex'.
      //
      // On vise le LABEL et non le conteneur `.form-row`, qui peut regrouper
      // plusieurs options — masquer le parent en emporterait d'autres.
      const ligne = el.closest('label') || el.parentElement || el;
      if (cloud) {
        if (el.checked) { el.checked = false; }   // ne pas laisser un état coché invisible
        ligne.style.setProperty('display', 'none', 'important');
      } else {
        ligne.style.removeProperty('display');
      }
    }
    try { window._applyMeshCostPill?.(); } catch (_) {}
  } catch (_) {}
};
window._masquerOptionsSansEffetCloud();

(async () => {
  let ok = await window._chargerPrix();
  window._masquerOptionsSansEffetCloud();
  // Même cadence que le web : 5 minutes.
  setInterval(() => { window._chargerPrix(); }, 5 * 60 * 1000);
  // Grille injoignable au demarrage (reseau pas encore pret) : aucune
  // pastille — pas de chiffre invente — mais on reessaie toutes les 30 s
  // plutot que de laisser l'application sans prix pendant 5 minutes.
  for (let essai = 0; !ok && !window._prix && essai < 8; essai++) {
    await new Promise((fin) => setTimeout(fin, 30 * 1000));
    ok = await window._chargerPrix();
  }
})();


// ============================================================
// SOLDE DE CRÉDITS DANS LA TOPBAR (mode Cloud uniquement)
// ============================================================
/* QUI est connecte. Retenu entre deux appels : quand le solde est deja connu
 * (`creditsKnown`), la fonction rendait sans interroger le serveur et la
 * mention du compte aurait disparu a chaque generation. */
window._compteCloud = window._compteCloud || null;

function _majMentionCompte(email) {
  const chip = document.getElementById('topbar-account');
  if (!chip) return;
  if (!email) { chip.style.display = 'none'; chip.textContent = ''; return; }
  // La partie locale suffit a se reconnaitre et tient dans la barre ; le
  // libelle complet reste dans l'infobulle.
  const local = String(email).split('@')[0];
  chip.textContent = local.length > 16 ? local.slice(0, 15) + '…' : local;
  chip.title = email;
  chip.style.display = '';
}

window._refreshTopbarCredits = async function (creditsKnown) {
  try {
    const el = document.getElementById('topbar-credits');
    const val = document.getElementById('topbar-credits-val');
    if (!el || !val) return;
    const cloud = (typeof window._computeMode === 'function') && window._computeMode() === 'cloud';
    if (!cloud) { el.style.display = 'none'; return; }
    el.style.display = 'inline-flex';
    const T = (s) => (typeof _i18nT === 'function' ? _i18nT(s) : s);
    const titreConnecte = (mail) => (mail
      ? T('Signed in as') + ' ' + mail + ' — ' + T('click to top up')
      : T('MyFabmesh credits — click to top up'));
    if (creditsKnown != null) {
      val.textContent = String(creditsKnown);
      el.dataset.needLogin = '';
      _majMentionCompte(window._compteCloud);
      el.title = titreConnecte(window._compteCloud);
      return;
    }
    const s = await API.cloudStatus?.();
    if (s?.loggedIn) window._compteCloud = s.email || window._compteCloud;
    else window._compteCloud = null;
    _majMentionCompte(window._compteCloud);
    if (s?.loggedIn && s.credits != null) {
      val.textContent = String(s.credits);
      el.dataset.needLogin = '';
      el.title = titreConnecte(window._compteCloud);
    } else if (s?.loggedIn) {
      val.textContent = '…';
      el.dataset.needLogin = '';
      el.title = titreConnecte(window._compteCloud);
    } else {
      // PAS CONNECTÉ. Le badge affichait « — » sans rien expliquer, et le clic
      // ouvrait le NAVIGATEUR sur /buy : on envoyait acheter des crédits
      // quelqu'un qui n'a même pas de compte. Constaté en salle blanche le
      // 2026-08-18, sur le parcours EXACT du testeur de certification — il sort
      // de l'assistant en mode Cloud, voit « — », et n'a aucun point d'entrée
      // visible vers la connexion. C'est le scénario du refus n°5.
      val.textContent = T('Sign in');
      el.dataset.needLogin = '1';
      el.title = T('Sign in to your MyFabmesh account — new accounts get 15 free credits');
    }
  } catch (_) {}
};
document.getElementById('topbar-credits')?.addEventListener('click', async () => {
  const el = document.getElementById('topbar-credits');
  // Non connecté : le badge est le point d'entrée vers la connexion DANS
  // l'application (inscription incluse), pas vers une page d'achat au navigateur.
  if (el && el.dataset.needLogin === '1') {
    try {
      const ok = await showCloudLoginModal();
      if (ok) window._refreshTopbarCredits();
    } catch (_) {}
    return;
  }
  _openCloudSite('/buy');
});
window._refreshTopbarCredits();

/* ═══════════════════════════════════════════════════════════════════
   PREMIÈRE ENTRÉE EN MODE CLOUD — proposer la connexion UNE fois.

   L'assistant annonce « Sign in with a MyFabmesh account — new accounts get
   15 free credits », puis l'application s'ouvrait sans jamais le proposer.
   L'utilisateur ne découvrait le problème qu'en cliquant « Generate ».

   On propose donc la connexion une seule fois, et JAMAIS de façon bloquante :
   annuler laisse l'application parfaitement utilisable (projets, imports,
   outils locaux). Le drapeau empêche de harceler à chaque lancement.

   Souvenir du refus n°5 : une garde posée pour aider avait fini par bloquer
   le testeur. Ici rien n'est bloqué — c'est une invitation, pas un mur.
   ═══════════════════════════════════════════════════════════════════ */
(async () => {
  try {
    if (typeof window._computeMode !== 'function' || window._computeMode() !== 'cloud') return;
    if (localStorage.getItem('fab-login-proposed') === '1') return;
    const s = await API.cloudStatus?.();
    if (s?.loggedIn) return;
    localStorage.setItem('fab-login-proposed', '1');
    const ok = await showCloudLoginModal();
    if (ok) window._refreshTopbarCredits();
  } catch (_) { /* ne doit jamais empêcher l'application de s'ouvrir */ }
})();

// ============================================================
// PASTILLES ⚡ SUR LES OUTILS IA (mode Cloud) — prix LUS dans la
// grille (window._prix), jamais ecrits en dur. En mode Local, ou
// tant que la grille est inconnue : aucune pastille.
// Couvre le panneau ÉDITER (ws-*-btn), la visionneuse (data-lb-tool),
// la visionneuse 3D (data-lb3d-tool) et les fenetres de validation.
// ============================================================
/* AUDIT DU 2026-09-30 (user : « les credits affiches dans l'appli ne sont pas
 * bons du tout ») : ces pastilles etaient des CONSTANTES restees sur une
 * ancienne grille — Modify 2 pour 3 factures, Auto Inpaint 3 pour 6, Draw
 * Mask 3 pour 6, Upscale 2 pour 3, Face Fix 2 pour 3, Recolor, Age, Variant et
 * Style 2 pour 3. Chaque bouton porte desormais la CLE de grille de la route
 * qu'il appelle REELLEMENT en mode Cloud (main.js / cloud_fallback.js), avec
 * la regle de prix du worker (getPrice dans worker.ts). Une fonction quand le
 * prix depend d'un reglage. */
const _CLOUD_TOOL_TARIFS = {
  // panneau ÉDITER — image
  'ws-modify-btn': 'modify',                  // /api/modify-image
  'ws-autoinpaint-btn': 'auto_inpaint',       // /api/auto-inpaint
  'ws-removebg-btn': 'remove_background',     // /api/remove-background
  'ws-resolution-btn': 'upscale',             // /api/upscale-image x2 (seul facteur propose ; x4 = upscale + 1)
  'ws-facefix-btn': 'face_fix_image',         // /api/face-fix-image
  // /api/outfit : outfit_complete avec « Fill hidden areas » (coche par defaut), outfit sans
  'ws-outfit-btn': () => window._prixDe(document.getElementById('of-completer')?.checked === false
    ? 'outfit' : 'outfit_complete'),
  'ws-recolor-btn': 'recolor',                // /api/recolor (cloud depuis le 2026-09-30)
  'ws-age-btn': 'tex_variant',                // /api/tex-variant (cloud depuis le 2026-09-30)
  // UNE variante : tex_variant (« Colours & materials », forme gardee) ou
  // modify (« Everything ») ; la fenetre annonce le total (x nombre).
  'ws-variant-btn': () => window._prixDe(document.getElementById('var-tex-mode')?.checked
    ? 'tex_variant' : 'modify'),
  // ws-buildstages-btn : PAS de pastille — generate-construction-stages est un
  // script SDXL/PIL 100 % local, sans endpoint worker → masque en mode Cloud
  // (_CLOUD_HIDDEN_TOOLS).
  'ws-mask-btn': 'mask_inpaint',              // /api/mask-inpaint
  'ws-style-btn': 'modify',                   // Style = Modify (/api/modify-image)
  // panneau ÉDITER step 2 : outils de maillage → /api/mesh-op (mesh_op_simple).
  // Watertight passe au tarif watertight_hd au-dela d'une resolution de 256 :
  // le prix exact est dans sa fenetre (_prixOutilMaillage).
  'ws-mesh-smooth-btn': 'mesh_op_simple',
  'ws-mesh-decimate-btn': 'mesh_op_simple',   // Triangle count (decimate / subdivide)
  'ws-mesh-subdivide-btn': 'mesh_op_simple',  // visible depuis le 2026-09-29
  'ws-mesh-fixnormals-btn': 'mesh_op_simple',
  'ws-mesh-fillholes-btn': 'mesh_op_simple',
  'ws-mesh-watertight-btn': 'mesh_op_simple', // resolution par defaut 192 ≤ 256
  // ws-mesh-center-btn (Set Pivot) : PAS de pastille — set_pivot n'est pas
  // dans la whitelist /api/mesh-op et reste LOCALE (CPU pur, gratuite).
  'ws-mesh-retexture-btn': 'mesh_op_simple',  // retex_swap
  'ws-mesh-explode-btn': 'mesh_op_simple',
  'ws-mesh-resize-btn': 'mesh_op_simple',
  'ws-mesh-material-btn': 'mesh_op_simple',   // material_adjust
  'ws-mesh-stages3d-btn': 'construction3d',   // /api/construction-stages-3d
  'ws-mesh-segment-btn': 'mesh_segment',      // /api/mesh-segment
};
/** Prix d'un outil (id de son bouton) lu dans la grille ; null si la grille
 *  est inconnue, l'outil gratuit ou local. Ne regarde PAS le mode de calcul. */
window._prixBouton = function (id) {
  const t = id && _CLOUD_TOOL_TARIFS[id];
  if (!t) return null;
  const p = typeof t === 'function' ? t() : window._prixDe(t);
  return (typeof p === 'number' && p > 0) ? p : null;
};
// Outils SANS équivalent cloud (gaps de parité) : masqués en mode Cloud.
const _CLOUD_HIDDEN_TOOLS = [
  // 'ws-recolor-btn' retire le 2026-09-24 : /api/recolor existe desormais.
  // 'ws-age-btn' retire le 2026-09-24 : /api/tex-variant existe desormais.
  'ws-buildstages-btn',  // étapes de construction 2D : SDXL local, pas d'endpoint
  'ws-multiview-btn',    // MV-Adapter / vue arrière : local uniquement
];
// Visionneuse : chaque entree clique le bouton du panneau (_wireLightboxToolbox),
// elle affiche donc le MEME prix que lui.
const _CLOUD_LB_BOUTONS = {
  modify: 'ws-modify-btn', autoinpaint: 'ws-autoinpaint-btn', removebg: 'ws-removebg-btn',
  resolution: 'ws-resolution-btn', facefix: 'ws-facefix-btn', variant: 'ws-variant-btn',
  mask: 'ws-mask-btn', outfit: 'ws-outfit-btn', recolor: 'ws-recolor-btn',
  age: 'ws-age-btn', style: 'ws-style-btn',
};
// Visionneuse 3D : route par clic simulé vers les boutons workspace
// (LB3D_TOOL_MAP). sculpt/paintvert/selectface/export/blender/folder restent
// sans pastille (gratuits/locaux) ; texvar/regionretex/enhancetex/detailsynth
// sont masquées en Cloud. « center » (→ Set Pivot) volontairement ABSENT : op
// locale gratuite.
const _CLOUD_LB3D_BOUTONS = {
  smooth: 'ws-mesh-smooth-btn', decimate: 'ws-mesh-decimate-btn', subdivide: 'ws-mesh-subdivide-btn',
  fixnormals: 'ws-mesh-fixnormals-btn', fillholes: 'ws-mesh-fillholes-btn',
  watertight: 'ws-mesh-watertight-btn', retexture: 'ws-mesh-retexture-btn', material: 'ws-mesh-material-btn',
};

window._applyToolPills = function () {
  try {
    const cloud = (typeof window._computeMode === 'function') && window._computeMode() === 'cloud';
    const prix = (id) => (cloud ? window._prixBouton(id) : null);
    for (const id of Object.keys(_CLOUD_TOOL_TARIFS)) {
      window._posePastille(document.getElementById(id), prix(id));
    }
    for (const [tool, id] of Object.entries(_CLOUD_LB_BOUTONS)) {
      window._posePastille(document.querySelector(`.lb-tool-btn[data-lb-tool="${tool}"]`), prix(id));
    }
    for (const [tool, id] of Object.entries(_CLOUD_LB3D_BOUTONS)) {
      window._posePastille(document.querySelector(`[data-lb3d-tool="${tool}"]`), prix(id));
    }
    for (const id of _CLOUD_HIDDEN_TOOLS) {
      const b = document.getElementById(id);
      if (b) b.style.display = cloud ? 'none' : '';
    }
    // Pendants lightbox des boutons masqués : la lightbox route par clic
    // simulé vers le bouton workspace, masquer ce dernier ne suffit donc pas.
    for (const tool of ['multiview']) {
      const b = document.querySelector(`.lb-tool-btn[data-lb-tool="${tool}"]`);
      if (b) b.style.display = cloud ? 'none' : '';
    }
  } catch (_) {}
};
window._applyToolPills();

/* FENETRES DE VALIDATION (2026-09-30). Chaque outil ouvre une fenetre avant
 * de lancer le calcul ; son bouton de lancement annonce le prix de CE
 * lancement (nombre de variantes, completion des habits, agrandir ou
 * reduire…), lu dans la grille comme les pastilles des boutons. Avant, aucune
 * de ces fenetres n'affichait de prix sur le bureau : le code commun avec le
 * site recopiait une pastille `.cloud-cost-badge` que le bureau ne pose pas.
 * Mesh tool (mt-apply), Segment (seg-go) et la fenetre de lancement
 * (lct-lancer) posent la leur a l'ouverture : leur prix depend de l'outil. */
const _TARIFS_VALIDATION = {
  'mod-apply': () => window._prixBouton('ws-modify-btn'),
  'var-apply': () => {
    // une variante = un appel facture ; meme borne 1..8 que le lancement
    const u = window._prixBouton('ws-variant-btn');
    const n = Math.max(1, Math.min(8, parseInt(document.getElementById('var-count')?.value, 10) || 1));
    return u == null ? null : n * u;
  },
  'ai-go': () => window._prixBouton('ws-autoinpaint-btn'),
  'mask-apply': () => window._prixBouton('ws-mask-btn'),
  'of-go': () => window._prixBouton('ws-outfit-btn'),
  'rc-go': () => window._prixBouton('ws-recolor-btn'),
  'age-go': () => window._prixBouton('ws-age-btn'),
  'sty-apply': () => window._prixBouton('ws-style-btn'),
  // Agrandir = /api/upscale-image ; Reduire = retouche locale, gratuite
  'res-apply': () => (document.getElementById('res-mode')?.value === 'down'
    ? null : window._prixBouton('ws-resolution-btn')),
  'bs3d-start': () => window._prixBouton('ws-mesh-stages3d-btn'),
  'ex3d-start': () => window._prixBouton('ws-mesh-explode-btn'),
  'rz-apply': () => window._prixBouton('ws-mesh-resize-btn'),
  'mat-apply-btn': () => window._prixBouton('ws-mesh-material-btn'),
};
window._applyValidationPills = function () {
  try {
    const cloud = (typeof window._computeMode === 'function') && window._computeMode() === 'cloud';
    for (const [id, prix] of Object.entries(_TARIFS_VALIDATION)) {
      window._posePastille(document.getElementById(id), cloud ? prix() : null);
    }
  } catch (_) {}
};
// Repose a chaque OUVERTURE de ces fenetres (la grille a pu changer depuis) et
// a chaque reglage qui change le prix.
(function _suivrePrixValidation() {
  const fenetres = new Set();
  for (const id of Object.keys(_TARIFS_VALIDATION)) {
    const f = document.getElementById(id)?.closest('.modal-overlay, .modal');
    if (f) fenetres.add(f);
  }
  try {
    const obs = new MutationObserver(() => window._applyValidationPills());
    fenetres.forEach((f) => obs.observe(f, { attributes: true, attributeFilter: ['class'] }));
  } catch (_) { /* sans observateur : prix pose au chargement de la grille */ }
  const REGLAGES = new Set(['var-count', 'var-tex-mode', 'var-free-mode', 'of-completer', 'res-mode']);
  const maj = (e) => {
    if (!e.target || !REGLAGES.has(e.target.id)) return;
    window._applyValidationPills();
    window._applyToolPills();   // Variant et Outfit : la pastille du bouton suit le reglage
  };
  document.addEventListener('change', maj);
  document.addEventListener('input', maj);
})();
window._applyValidationPills();

// ============================================================
// MASQUAGE DES OUTILS DESKTOP-ONLY EN MODE CLOUD — ces outils
// IA 3D/rig n'ont AUCUN équivalent côté worker (pas d'endpoint) :
// les laisser visibles en mode Cloud = échec garanti au clic.
// En mode Local, tout est ré-affiché.
// ============================================================
const _CLOUD_HIDDEN_MESH_TOOLS = [
  'ws-mesh-enhance-tex-btn',   // Real-ESRGAN local, pas d'endpoint worker
  'ws-mesh-detail-synth-btn',  // detail_synth.py SDXL local
  'ws-mesh-region-retex-btn',  // SDXL inpaint atlas local
  'ws-mesh-reshape-btn',       // auto inpaint 3D : SDXL + moteur 3D locaux
  'ws-mesh-reshape-draw-btn',  // idem, zone peinte en 3D
  'ws-mesh-texvar-btn',        // texture_var absent de la whitelist /api/mesh-op
  'ws-mesh-trellis2-btn',      // trellis2_retex absent de la whitelist /api/mesh-op
  'ws-mesh-name-btn',          // part namer local (Modal _partnamer non déployé)
                               // (paid no-op côté worker, pas de vraie reprojection)
  'ws-mesh-center-btn',        // set_pivot absent de la whitelist /api/mesh-op
                               // (op trimesh locale, pas de venv IA en Cloud)
];
// Entrées lightbox 3D correspondantes : la lightbox route vers les boutons
// workspace par clic simulé, masquer le bouton workspace ne suffit donc pas.
const _CLOUD_HIDDEN_LB3D_TOOLS = ['texvar', 'regionretex', 'enhancetex', 'detailsynth', 'center',
  'blender'];  // Open in Blender : binaire local, jamais disponible en Cloud
// Outils qui exigent Blender installé (aucun rapport avec le cloud) : sur une
// machine de test Store, Blender est absent → clic = « Blender path not
// configured ». On les grise avec une explication au lieu d'une erreur.
// En mode Cloud ils sont en plus MASQUÉS (voir _applyCloudFeatureMask) : le
// pipeline Blender/Unreal/FBX est 100 % local, sans équivalent worker.
const _BLENDER_TOOLS = ['ws-mesh-blender-btn', 'ws-rig-blender-btn', 'ws-rig-unreal-btn',
  'ws-anim-export-btn'];   // Export FBX = anim:export → Blender

window._applyCloudFeatureMask = function () {
  try {
    const cloud = (typeof window._computeMode === 'function') && window._computeMode() === 'cloud';
    for (const id of _CLOUD_HIDDEN_MESH_TOOLS) {
      const el = document.getElementById(id);
      if (el) el.style.display = cloud ? 'none' : '';
    }
    for (const t of _CLOUD_HIDDEN_LB3D_TOOLS) {
      const el = document.querySelector(`[data-lb3d-tool="${t}"]`);
      if (el) el.style.display = cloud ? 'none' : '';
    }
    // Blender / Unreal / Export FBX : chaîne 100 % locale (binaire externe).
    // _applyBlenderToolState ne touche QUE disabled/title → pas de conflit ici.
    for (const id of _BLENDER_TOOLS) {
      const el = document.getElementById(id);
      if (el) el.style.display = cloud ? 'none' : '';
    }
    // Mode « Colours & materials » (forme gardee) de la fenetre Variant : il
    // etait masque en Cloud parce que tex-variant ne tournait qu'en local. Il
    // passe par /api/tex-variant depuis le 2026-09-30 (main.js) : les deux
    // modes restent proposes, comme sur le site et en mode Local.
    // Formats d'export : la conversion GLTF/OBJ/STL/PLY passe par trimesh
    // (Python) et le FBX par Blender — indisponibles en mode Cloud. Le GLB est
    // une copie directe du fichier : il marche partout.
    const fmtSel = document.getElementById('exp-format');
    if (fmtSel) {
      for (const opt of Array.from(fmtSel.options)) {
        const glb = opt.value === 'glb';
        opt.disabled = cloud && !glb;
        if (!opt.dataset.baseLabel) opt.dataset.baseLabel = opt.textContent;
        opt.textContent = (cloud && !glb)
          ? `${opt.dataset.baseLabel} — ${_i18nT('local engine required')}`
          : opt.dataset.baseLabel;
      }
      if (cloud && fmtSel.value !== 'glb') fmtSel.value = 'glb';
    }
  } catch (_) {}
};

// Blender/Unreal : dépendent d'une installation Blender, pas du mode de calcul.
// On les désactive avec un titre explicatif quand aucun chemin n'est configuré.
window._applyBlenderToolState = async function () {
  try {
    let blender = '';
    try { const cfg = await API.getConfig?.(); blender = (cfg && cfg.blenderPath) || ''; } catch (_) {}
    const msg = _i18nT('Blender is not installed (or its path is not set in Settings). '
      + 'Export as GLB instead — it opens in Blender, Unreal, Unity and the Windows 3D Viewer.');
    for (const id of _BLENDER_TOOLS) {
      const el = document.getElementById(id);
      if (!el) continue;
      el.disabled = !blender;
      el.classList.toggle('disabled', !blender);
      if (!blender) el.title = msg; else el.removeAttribute('title');
    }
  } catch (_) {}
};
window._applyBlenderToolState();
window._applyCloudFeatureMask();

// ============================================================
// PASTILLES ⚡ RIG + ANIMATION.
// Les deux boutons Generate voient leur textContent réécrit par
// _updateGenButtonsEstimate ET refreshButtonLabelsAndHiding (ce qui
// détruit la pastille enfant) → cette fonction est ré-appelée après
// chaque réécriture, en plus des 2 sites de bascule Local/Cloud.
// Prix LUS dans la grille (2026-09-30) : rig, reskin et anim etaient
// des constantes (10, 6, 5) qu'un reglage de l'onglet Pricing ne
// suivait pas.
// ============================================================
/* Le rig part sur le cloud en mode Cloud, ET en mode Local quand aucun moteur
 * de rig n'est installe (main.js, auto-rig-ai : `basculeCloud`) — il est alors
 * facture sans qu'aucune pastille ne l'annonce. Renseigne au demarrage. */
window._rigViaCloud = false;
(async () => {
  try {
    const dispo = await window.meshyAPI?.rigLocalDisponible?.();
    if (dispo === false) { window._rigViaCloud = true; window._applyRigAnimPills?.(); }
  } catch (_) {}
})();
window._applyRigAnimPills = function () {
  try {
    const cloud = (typeof window._computeMode === 'function') && window._computeMode() === 'cloud';
    const rigCloud = cloud || window._rigViaCloud === true;
    const prix = (cle) => (rigCloud ? window._prixDe(cle) : null);
    // Rig : /api/auto-rig SANS squelette impose → tarif `rig`.
    window._posePastille(document.getElementById('ws-generate-rig-ai'), prix('rig'));
    // Peau seule : squelette impose → tarif `reskin` (getPrice du worker).
    window._posePastille(document.getElementById('ws-rig-reskin-btn'), prix('reskin'));
    // Editeur des points : articulations deplacees = squelette impose (reskin),
    // sinon nouveau tirage de l'IA (rig) — voir ptsRegenerer.
    let osModifies = false;
    try { osModifies = !!_pts.osModifies; } catch (_) {}
    window._posePastille(document.getElementById('pts-regenerer'), prix(osModifies ? 'reskin' : 'rig'));
    // Animation : TOUJOURS en ligne (parite web, 2026-09-28), quel que soit le
    // mode de calcul. Les allures du moteur procedural sont GRATUITES
    // (calculees ici) ; chaque clip IA restant = un appel /api/animate au
    // tarif `anim`.
    const nbClips = (typeof _animSelection !== 'undefined' ? _animSelection : [])
      .filter((e) => !ALLURES_PROCEDURALES.includes(e.type)).length;
    const pAnim = window._prixDe('anim');
    window._posePastille(document.getElementById('ws-generate-anim'),
      (nbClips && pAnim != null) ? nbClips * pAnim : null);
  } catch (_) {}
};
window._applyRigAnimPills();

/* ═══════════════════════════════════════════════════════════════════
   PRÉCHAUFFAGE GPU — parité avec le web (cloud-overrides.installPrewarm)

   Le refus de certification Microsoft du 28/07/2026 (« Image generation
   failed - The cloud GPU took too long to start ») venait de là : le
   desktop exposait bien `cloudPrewarm` dans le preload, mais AUCUN code
   du renderer ne l'appelait. Le seul préchauffage était celui du main,
   8 s après le lancement — donc avant toute connexion, et il sortait
   immédiatement faute de session.

   Ici on chauffe quand l'utilisateur montre son intention de générer :
   il clique dans le champ de description, le GPU démarre pendant qu'il
   tape. Le débounce de 4 min vit côté main (cloud_fallback.prewarm),
   donc marteler le champ ne facture rien de plus.
   ═══════════════════════════════════════════════════════════════════ */
(() => {
  const api = window.meshyAPI;
  if (!api?.cloudPrewarm) return;   // build desktop pur : rien à chauffer

  let last = 0;
  const warm = () => {
    // Garde-fou local en plus de celui du main : évite un aller-retour
    // IPC à chaque frappe dans le champ.
    if (Date.now() - last < 60_000) return;
    last = Date.now();
    try { api.cloudPrewarm({}).catch?.(() => {}); } catch (_) {}
  };

  const attach = () => {
    for (const id of ['ws-prompt', 'np-prompt', 'ws-trellis2-preset', 'ws-asset-type']) {
      const el = document.getElementById(id);
      if (!el || el.dataset.prewarmBound) continue;
      el.dataset.prewarmBound = '1';
      el.addEventListener('focus', warm);
    }
  };

  attach();
  // Les panneaux sont rendus à la demande : on re-tente à l'ouverture
  // d'un projet plutôt que d'observer tout le DOM en permanence.
  document.addEventListener('click', attach, { passive: true });
  window.addEventListener('focus', warm);
})();

// ===================== Signalement de contenu genere par l'IA =====================
// EXIGE PAR LA CERTIFICATION MICROSOFT STORE, politique 11.16 « Live Generative
// AI Content » : tout produit presentant du contenu cree par un modele generatif
// doit offrir un moyen de signaler un contenu inapproprie. Son absence a motive
// le refus du 2026-08-04 (rapport 83ac9ac1, produit 9PH6GT8XKQDW).
//
// Le signalement remonte dans l'onglet « Messages » de l'admin, deja consulte,
// avec son badge de non-lus et son bouton de reponse.
(function wireReportContent() {
  const overlay = document.getElementById('modal-report');
  if (!overlay) return;
  const selReason = document.getElementById('rp-reason');
  const txtDetails = document.getElementById('rp-details');
  const elStatus = document.getElementById('rp-status');
  const btnSend = document.getElementById('rp-send');
  let contexte = {};

  const fermer = () => overlay.classList.add('hidden');

  function ouvrir(ctx) {
    contexte = ctx || {};
    if (txtDetails) txtDetails.value = '';
    if (elStatus) { elStatus.textContent = ''; elStatus.style.color = ''; }
    if (btnSend) { btnSend.disabled = false; btnSend.textContent = 'Send report'; }
    overlay.classList.remove('hidden');
  }

  document.getElementById('rp-close')?.addEventListener('click', fermer);
  document.getElementById('rp-cancel')?.addEventListener('click', fermer);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) fermer(); });

  function promptCourant() {
    try { return document.getElementById('ws-prompt')?.value || ''; } catch (_) { return ''; }
  }

  document.getElementById('ws-report-img-btn')?.addEventListener('click', () => {
    let cible = '';
    try { cible = editTarget(state.currentProject) || ''; } catch (_) {}
    ouvrir({ kind: 'image', asset_url: cible, prompt: promptCourant() });
  });

  // Le meme signalement, mais dans la barre sous l'image, a cote de
  // « Copy prompt » : c'est la que le regard se porte apres une generation.
  document.getElementById('ws-report-img-inline-btn')?.addEventListener('click', (e) => {
    e.stopPropagation();
    let cible = '';
    try { cible = editTarget(state.currentProject) || ''; } catch (_) {}
    ouvrir({ kind: 'image', asset_url: cible, prompt: promptCourant() });
  });

  document.getElementById('ws-report-mesh-btn')?.addEventListener('click', () => {
    let cible = '';
    try { cible = getCurrentMeshObj()?.path || ''; } catch (_) {}
    ouvrir({ kind: 'mesh', asset_url: cible, prompt: promptCourant() });
  });

  /* ENTREE PERMANENTE — barre du haut.
   *
   * La politique 11.16 a valu DEUX refus (2026-08-04, puis 2026-08-19) alors
   * que le dispositif de signalement existait deja les deux fois. Le probleme
   * n'a jamais ete son absence, mais sa DECOUVRABILITE :
   *   - « Report content » des panneaux d'outils n'apparait qu'une fois une
   *     image ou un maillage selectionne. Un testeur qui n'a rien genere —
   *     et sur un Surface sans GPU, generer exige un compte — ne le voit
   *     jamais ;
   *   - l'entree « A propos » demande d'ouvrir une fenetre secondaire, ce
   *     qu'un examinateur cherchant « Report an Issue » ne fait pas.
   *
   * Ce bouton-ci est dans la barre du haut, visible des le premier lancement,
   * sans compte, sans projet et sans contenu. */
  document.getElementById('btn-report-ai')?.addEventListener('click', () => {
    let cible = '';
    try { cible = editTarget(state.currentProject) || ''; } catch (_) {}
    if (!cible) { try { cible = getCurrentMeshObj()?.path || ''; } catch (_) {} }
    ouvrir({ kind: 'unspecified', asset_url: cible, prompt: promptCourant() });
  });

  // Entree depuis la fenetre « A propos ». Les boutons places pres du
  // contenu n'existent qu'une fois une image ou un maillage selectionne ;
  // celui-ci est disponible A TOUT MOMENT, y compris au tout premier
  // lancement. C'est le chemin qu'un examinateur de certification suit.
  document.getElementById('about-report-btn')?.addEventListener('click', () => {
    let cible = '';
    try { cible = editTarget(state.currentProject) || ''; } catch (_) {}
    if (!cible) { try { cible = getCurrentMeshObj()?.path || ''; } catch (_) {} }
    try { document.getElementById('about-modal')?.classList.add('hidden'); } catch (_) {}
    ouvrir({ kind: 'unspecified', asset_url: cible, prompt: promptCourant() });
  });

  const btnSuppr = document.getElementById('rp-delete');

  // Apercu du contenu, pour que l'admin puisse JUGER sans rien installer.
  // Une image se joint telle quelle ; un maillage .glb ne s'affiche pas dans
  // un tableau de bord, on capture donc le viewport 3D tel qu'il est a
  // l'ecran au moment du signalement.
  function apercuPng() {
    try {
      if (contexte.kind !== 'mesh') return '';
      const cv = document.getElementById('ws-mesh-canvas');
      if (!cv || !cv.width) return '';
      return cv.toDataURL('image/png');
    } catch (_) { return ''; }
  }

  // Suppression du contenu signale, proposee APRES l'envoi. Elle n'efface
  // que la copie LOCALE : la piece jointe au signalement reste cote serveur,
  // sans quoi l'admin ne pourrait plus instruire le dossier.
  btnSuppr?.addEventListener('click', async () => {
    const chemin = contexte.asset_url || '';
    if (!chemin) { fermer(); return; }
    const ok = await customConfirm(
      'Delete this content from your project? The copy attached to your report is kept so an admin can review it.',
      'Delete reported content');
    if (!ok) return;
    btnSuppr.disabled = true;
    try {
      if (contexte.kind === 'mesh') {
        const nom = String(chemin).split(/[\/]/).pop();
        await API.deleteMesh(nom);
      } else {
        await API.deleteFile(chemin);
      }
      if (elStatus) { elStatus.style.color = '#7ee08a'; elStatus.textContent = 'Content deleted. Your report was kept.'; }
      showToast('Reported content deleted.', 'success');
      setTimeout(() => { fermer(); try { location.reload(); } catch (_) {} }, 1200);
    } catch (e) {
      btnSuppr.disabled = false;
      if (elStatus) { elStatus.style.color = '#ffcf6b'; elStatus.textContent = 'Could not delete: ' + (e?.message || e); }
    }
  });

  btnSend?.addEventListener('click', async () => {
    const charge = {
      reason: selReason?.value || 'other',
      details: txtDetails?.value || '',
      asset_url: contexte.asset_url || '',
      // Le chemin sert au processus principal a LIRE le fichier et le joindre.
      asset_path: contexte.asset_url || '',
      preview_b64: apercuPng(),
      prompt: contexte.prompt || '',
      kind: contexte.kind || '',
      surface: 'desktop',
    };
    btnSend.disabled = true;
    btnSend.textContent = 'Sending…';
    if (elStatus) { elStatus.style.color = ''; elStatus.textContent = 'Sending your report…'; }
    try {
      // VOIE NORMALE : le processus principal. Un fetch direct depuis le
      // renderer echoue toujours — le worker n'envoie aucun en-tete CORS et
      // l'origine du renderer n'est pas la sienne. C'est ce qui faisait
      // basculer chaque signalement vers le repli courriel au lieu de la
      // messagerie de l'admin.
      const rep = await window.meshyAPI?.cloudReportContent?.(charge);
      if (!rep) throw new Error('canal indisponible');
      if (!rep.success) throw new Error(rep.error || 'echec');
      if (elStatus) { elStatus.style.color = '#7ee08a'; elStatus.textContent = 'Report sent. Thank you — an admin will review it.'; }
      btnSend.textContent = 'Sent';
      // Le signalement est parti ET la piece est televersee : on peut
      // maintenant proposer d'effacer la copie locale. Pas avant — sinon on
      // inciterait a detruire la preuve plutot qu'a la transmettre.
      if (btnSuppr) btnSuppr.style.display = '';
      // Pas de fermeture automatique : elle escamoterait l'offre de
      // suppression avant que l'utilisateur ait eu le temps de la lire.
    } catch (e) {
      // REPLI HORS LIGNE, INDISPENSABLE. L'application fonctionne sans compte
      // et sans reseau (generation locale) : un dispositif de signalement qui
      // echoue des que le serveur est injoignable ne remplirait pas l'exigence.
      // On bascule sur le courriel, qui aboutit toujours.
      const corps = encodeURIComponent(
        'Reason: ' + charge.reason + '\n' +
        'Type: ' + charge.kind + '\n' +
        'Prompt: ' + charge.prompt + '\n' +
        'File: ' + charge.asset_url + '\n\n' +
        'Details:\n' + charge.details + '\n');
      // ADRESSE REELLE, verifiee. `report@myfabmesh.ai` etait utilisee
      // ici : le domaine myfabmesh.ai n'a NI enregistrement A NI MX
      // (verifie le 2026-08-20). Le repli hors ligne — le seul chemin
      // de signalement quand le serveur est injoignable, et donc celui
      // qu'un examinateur peut tester — envoyait dans le vide.
      // Cette boite-ci est celle declaree dans les mentions legales
      // (cloud/src/config/legal-identity.ts, supportEmail).
      const ADRESSE_SIGNALEMENT = 'myfabmesh.contact@gmail.com';
      const lien = 'mailto:' + ADRESSE_SIGNALEMENT
                 + '?subject=' + encodeURIComponent('AI content report — ' + charge.reason)
                 + '&body=' + corps;
      /* Il ne suffit PAS d'appeler et d'esperer.
       *
       * Ce que faisait l'ancien code : `window.meshyAPI?.openExternal?.(lien)
       * || window.open(lien)`. `meshyAPI` n'expose PAS openExternal, donc
       * l'expression tombait sur `window.open`, que `setWindowOpenHandler`
       * autorise pour mailto: — le brouillon s'ouvrait donc bel et bien.
       * Le defaut reel etait ailleurs : l'adresse pointait sur un domaine
       * inexistant.
       *
       * Reste que le code n'avait AUCUN filet : si l'ouverture echoue — pas
       * de client de messagerie configure, gestionnaire modifie, navigateur
       * qui bloque la fenetre cote web — l'interface affirmait quand meme
       * qu'un brouillon etait ouvert. On attend desormais le verdict et, a
       * defaut, on AFFICHE l'adresse avec un bouton de copie. Un dispositif
       * exige par la certification doit aboutir dans tous les cas. */
      let ouvert = false;
      try {
        const r = await (window.meshyAPI?.openMailto?.(lien));
        ouvert = !!(r && r.ok);
      } catch (_) { ouvert = false; }
      if (!ouvert) {
        try { ouvert = !!window.open(lien); } catch (_) { ouvert = false; }
      }
      if (elStatus) {
        elStatus.style.color = '#ffcf6b';
        elStatus.innerHTML = '';
        const t = document.createElement('span');
        t.textContent = ouvert
          ? 'Could not reach the server — your e-mail app has been opened instead.'
          : 'Could not reach the server. Please e-mail your report to ';
        elStatus.appendChild(t);
        if (!ouvert) {
          const adr = document.createElement('strong');
          adr.textContent = ADRESSE_SIGNALEMENT;
          adr.style.userSelect = 'text';
          elStatus.appendChild(adr);
          const copier = document.createElement('button');
          copier.className = 'ghost-btn';
          copier.style.cssText = 'margin-left:8px; font-size:11px; padding:2px 8px;';
          copier.textContent = 'Copy address';
          copier.onclick = () => {
            navigator.clipboard.writeText(ADRESSE_SIGNALEMENT).then(() => {
              copier.textContent = '✓ Copied';
              setTimeout(() => { copier.textContent = 'Copy address'; }, 1500);
            }).catch(() => {});
          };
          elStatus.appendChild(copier);
        }
      }
      btnSend.disabled = false;
      btnSend.textContent = 'Send report';
    }
  });
})();

/* ============================================================
   ACCESSIBILITE — nom accessible, annonces, fenetres modales.

   Constat de l'audit du 2026-08-20 : 470 boutons pour 6 `aria-label`, aucun
   `role`, aucune region live. Un lecteur d'ecran annonce « bouton » sur les
   boutons a glyphe — dont le drapeau de signalement, celui-la meme qu'exige
   la certification — et ne dit jamais qu'une generation est terminee.

   On ne peut pas annoter 470 balises a la main sans en oublier, et une
   annotation figee se desynchroniserait des cinq traductions. On DERIVE donc
   le nom accessible de l'infobulle, a l'execution, et on rejoue le balayage
   apres chaque changement de langue et a chaque mutation du document.
   ============================================================ */
(() => {
  const estGlyphe = (t) => {
    const s = (t || '').trim();
    if (!s) return true;
    // Un libelle « reel » contient au moins deux caracteres latins ou
    // ideographiques a la suite ; « ⚑ », « ↻ », « ? » n'en contiennent pas.
    return !/[A-Za-zÀ-ɏЀ-ӿ؀-ۿऀ-ॿ一-鿿]{2,}/.test(s);
  };

  // Croix de fermeture : le glyphe « ✕ » n'a pas d'infobulle et se lit
  // « bouton » tout court. Elles sont nombreuses et toutes identiques.
  const CROIX = /^[×✕✖❌ＸxX]$/;

  function nommer(racine) {
    let poses = 0;
    for (const b of (racine || document).querySelectorAll('button, [role="button"]')) {
      if (b.getAttribute('aria-label')) continue;
      if (!estGlyphe(b.textContent)) continue;      // le texte suffit deja
      let t = b.getAttribute('title') || b.dataset.tooltip || '';
      if (!t) {
        const brut = (b.textContent || '').trim();
        const classes = String(b.className || '');
        if (CROIX.test(brut) || /close-x|about-close/.test(classes)) {
          t = (typeof _i18nT === 'function' ? _i18nT('Close') : 'Close');
        }
      }
      if (!t) continue;
      b.setAttribute('aria-label', t);
      poses++;
    }
    return poses;
  }

  function annoncer(racine) {
    /* Regions dont le contenu change SEUL : sans `aria-live`, un lecteur
     * d'ecran ne dit jamais qu'une generation est terminee.
     *
     * On vise par MOTIF plutot que par liste : le produit compte une
     * vingtaine d'elements « ...-status » (step1-status, ws-anim-status,
     * pe-status, set-calib-status...) et une liste figee en aurait oublie a
     * chaque nouvelle fonction. */
    const cibles = (racine || document).querySelectorAll(
      '[id$="-status"], [id$="-progress-label"], #toast-container, #cl-err');
    for (const el of cibles) {
      if (el.getAttribute('aria-live')) continue;
      el.setAttribute('aria-live', 'polite');
      el.setAttribute('aria-atomic', 'true');
    }
  }

  function modales(racine) {
    for (const m of (racine || document).querySelectorAll('.modal-overlay')) {
      if (!m.getAttribute('role')) {
        m.setAttribute('role', 'dialog');
        m.setAttribute('aria-modal', 'true');
        const titre = m.querySelector('h2, h3');
        if (titre) {
          if (!titre.id) titre.id = 'titre-' + Math.random().toString(36).slice(2, 9);
          m.setAttribute('aria-labelledby', titre.id);
        }
      }
    }
  }

  function balayer(racine) { try { nommer(racine); annoncer(racine); modales(racine); } catch (_) {} }

  const lancer = () => {
    balayer(document);
    // Le contenu est construit dynamiquement : on rejoue, en le laissant
    // respirer (regroupement des mutations).
    let attente = null;
    try {
      new MutationObserver(() => {
        if (attente) return;
        attente = setTimeout(() => { attente = null; balayer(document); }, 400);
      }).observe(document.body, { childList: true, subtree: true });
    } catch (_) {}
    // Apres un changement de langue, les infobulles changent : on repart de
    // zero pour que le nom accessible suive.
    try {
      const appliquer = window.FabI18n && window.FabI18n.applyLang;
      if (appliquer) {
        window.FabI18n.applyLang = function (lang) {
          const r = appliquer.apply(this, arguments);
          try {
            document.querySelectorAll('button[aria-label]').forEach((b) => b.removeAttribute('aria-label'));
            balayer(document);
          } catch (_) {}
          return r;
        };
      }
    } catch (_) {}
  };

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', lancer);
  else lancer();
})();

// ============================================================
// HISTORIQUE D'UTILISATION — PARITE WEB (2026-09-27). Meme fenetre que le
// site (« My usage history »). Deux sources :
//   - les travaux CLOUD du compte (/api/history.json, relaye par le main
//     car le renderer n'a ni le cookie de session ni l'acces CORS) ;
//   - les travaux LOCAUX termines (state.jobsTermines), sans credits.
// Un travail cloud lance depuis le bureau figure dans les deux : la ligne
// locale est ecartee quand une ligne cloud du meme projet tombe a moins de
// 2 minutes.
// ============================================================
(function historiqueBureau() {
  const btn   = document.getElementById('btn-history');
  const modal = document.getElementById('history-modal');
  const close = document.getElementById('history-close-btn');
  const tbody = document.getElementById('history-tbody');
  const errEl = document.getElementById('history-error');
  const exportBtn = document.getElementById('history-export-btn');
  if (!btn || !modal || !tbody) return;
  const esc = (v) => String(v == null ? '' : v).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  let lignesLocales = new Map();

  const shut = () => { modal.style.display = 'none'; };
  btn.addEventListener('click', () => { modal.style.display = 'flex'; charger(); });
  close?.addEventListener('click', shut);
  modal.addEventListener('click', (e) => { if (e.target === modal) shut(); });

  exportBtn?.addEventListener('click', async () => {
    if (!window.meshyAPI?.cloudHistoryExport) return;
    const r = await window.meshyAPI.cloudHistoryExport();
    if (r?.needsCloudLogin) showToast(_i18nT('Sign in to your MyFabmesh account to export the cloud history.'), 'info', 5000);
    else if (r?.success) showToast(_i18nT('History exported') + ' ✓', 'success', 3000);
    else if (!r?.canceled) showToast(_i18nT('Export failed') + ': ' + (r?.error || '?'), 'error', 5000);
  });

  function locales() {
    const STATUT = { ok: 'succeeded', echec: 'failed', annule: 'cancelled' };
    return (state.jobsTermines || []).map((j) => ({
      id: 'local:' + j.finiId,
      date: new Date(j.finiLe || j.startedAt || Date.now()).toISOString(),
      type: (typeof _displayJobName === 'function' ? _displayJobName(j.name) : j.name) || '—',
      status: STATUT[j.statut] || 'succeeded',
      duration_s: Math.max(0, ((j.finiLe || 0) - (j.startedAt || 0)) / 1000) || 0,
      credits: '—',
      project: j.projectName || '',
      _local: j,
    }));
  }

  async function charger() {
    errEl.style.display = 'none';
    tbody.innerHTML = '<tr><td colspan="6" style="padding:16px; color:var(--text-2);">' + esc(_i18nT('Loading…')) + '</td></tr>';
    let cloud = [], note = '';
    try {
      const r = window.meshyAPI?.cloudHistoryList ? await window.meshyAPI.cloudHistoryList() : null;
      if (r?.success) cloud = r.rows || [];
      else if (r?.needsCloudLogin) note = _i18nT('Sign in to your MyFabmesh account to see your cloud usage too.');
      else if (r) note = _i18nT('Cloud history unavailable') + (r.error ? ' (' + r.error + ')' : '');
    } catch (e) { note = _i18nT('Cloud history unavailable'); }
    const tCloud = cloud.map((c) => ({ t: new Date(c.date).getTime(), p: c.project || '' }));
    const loc = locales().filter((l) => {
      const t = new Date(l.date).getTime();
      return !tCloud.some((c) => c.p === l.project && Math.abs(c.t - t) < 120000);
    });
    lignesLocales = new Map(loc.map((l) => [l.id, l._local]));
    const lignes = [...cloud, ...loc].sort((a, b) => new Date(b.date) - new Date(a.date));
    if (note) { errEl.textContent = note; errEl.style.display = 'block'; }
    rendu(lignes);
  }

  function rendu(rows) {
    if (!rows.length) {
      tbody.innerHTML = '<tr><td colspan="6" style="padding:24px; color:var(--text-2); text-align:center;">' + esc(_i18nT('No generations yet.')) + '</td></tr>';
      return;
    }
    const couleur = (s) => s === 'succeeded' ? '#4cd964' : (s === 'failed' ? '#ff5252' : '#ffaa33');
    const cel = 'padding:6px 10px; border-bottom:1px solid var(--border);';
    tbody.innerHTML = rows.map((r) => `
      <tr data-job-id="${esc(r.id)}" style="cursor:pointer;" title="${esc(String(r.id).startsWith('local:') ? _i18nT('Local job — click to open it') : _i18nT('Click for full details'))}">
        <td style="${cel} white-space:nowrap;">${esc(new Date(r.date).toLocaleString('fr', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }))}</td>
        <td style="${cel}">${esc(r.type)}${String(r.id).startsWith('local:') ? ' <span style="font-size:10px; color:var(--text-2); border:1px solid var(--border); border-radius:8px; padding:0 6px; margin-left:4px;">' + esc(_i18nT('local')) + '</span>' : ''}</td>
        <td style="${cel}"><span style="background:${couleur(r.status)}22; color:${couleur(r.status)}; padding:2px 8px; border-radius:10px; font-size:11px;">${esc(r.status)}</span></td>
        <td style="${cel} text-align:right; font-variant-numeric:tabular-nums;">${Number(r.duration_s || 0).toFixed(1)}s</td>
        <td style="${cel} text-align:right; font-variant-numeric:tabular-nums;">${esc(r.credits)}</td>
        <td style="${cel} color:var(--text-2);">${esc(r.project || '—')}</td>
      </tr>`).join('');
    tbody.querySelectorAll('tr[data-job-id]').forEach((tr) => {
      tr.addEventListener('mouseenter', () => { tr.style.background = 'rgba(168,85,247,0.06)'; });
      tr.addEventListener('mouseleave', () => { tr.style.background = ''; });
      tr.addEventListener('click', () => {
        const id = tr.dataset.jobId;
        if (id.startsWith('local:')) {
          const entree = lignesLocales.get(id);
          shut();
          if (entree && typeof window._navigateToJobStep === 'function') window._navigateToJobStep(null, entree);
        } else detail(id);
      });
    });
  }

  // Detail d'un travail cloud (fenetre au-dessus de l'historique).
  const wrap = document.getElementById('history-detail');
  const titre = document.getElementById('history-detail-title');
  const corps = document.getElementById('history-detail-body');
  document.getElementById('history-detail-close')?.addEventListener('click', () => { wrap.style.display = 'none'; });
  wrap?.addEventListener('click', (e) => { if (e.target === wrap) wrap.style.display = 'none'; });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && wrap?.style.display === 'flex') wrap.style.display = 'none'; });
  const ligne = (label, val) => (val == null || val === '') ? '' :
    `<div style="display:grid; grid-template-columns:140px 1fr; gap:12px; padding:3px 0; border-bottom:1px solid rgba(255,255,255,0.04);"><span style="color:var(--text-2); font-size:11px; text-transform:uppercase;">${esc(label)}</span><span>${val}</span></div>`;
  const nomFichier = (u) => String(u || '').split('?')[0].split('/').pop();
  corps?.addEventListener('click', (e) => {
    const a = e.target.closest('[data-projet]');
    if (!a) return;
    e.preventDefault();
    wrap.style.display = 'none'; shut();
    window.openProjectByName && window.openProjectByName(a.dataset.projet);
  });
  const lienProjet = (n) => n ? `<a href="#" data-projet="${esc(n)}" style="color:var(--accent); text-decoration:underline;">${esc(n)}</a>` : '—';
  async function detail(id) {
    wrap.style.display = 'flex';
    titre.textContent = _i18nT('Event') + ' ' + id;
    corps.textContent = _i18nT('Loading…');
    try {
      const r = await window.meshyAPI.cloudHistoryDetail(id);
      if (!r?.success || !r.job) { corps.textContent = (r && r.error) || 'Error'; return; }
      const job = r.job, opt = job.options || {};
      const durMs = opt.duration_ms != null ? Number(opt.duration_ms)
                  : (job.finished_at ? new Date(job.finished_at) - new Date(job.created_at) : 0);
      const coul = job.status === 'succeeded' ? '#4cd964' : (job.status === 'failed' ? '#ff5252' : '#ffaa33');
      let html = '';
      html += ligne('Job ID', `<code>${esc(job.id)}</code>`);
      html += ligne('Type', esc(job.asset_type));
      html += ligne('Status', `<span style="color:${coul}; font-weight:600;">${esc(job.status)}</span>`);
      html += ligne('Created', esc(new Date(job.created_at).toLocaleString('fr')));
      if (job.finished_at) html += ligne('Finished', esc(new Date(job.finished_at).toLocaleString('fr')));
      html += ligne('Duration', (durMs / 1000).toFixed(1) + ' s');
      html += ligne('Credits', esc(job.credit_cost));
      html += ligne('Project', lienProjet(job.project_name));
      if (job.error) html += `<div style="margin-top:10px; padding:8px 10px; background:rgba(255,82,82,0.1); border:1px solid #ff5252; border-radius:6px; color:#ff5252; word-break:break-word;"><strong>Error:</strong> ${esc(job.error)}</div>`;
      if (job.mesh_url) html += ligne('Output', esc(nomFichier(job.mesh_url)));
      for (const a of (r.assets || [])) html += ligne(a.kind, esc(nomFichier(a.url)));
      if (opt.prompt) html += ligne('Prompt', esc(opt.prompt));
      if (opt.preset) html += ligne('Preset', esc(opt.preset));
      corps.innerHTML = html;
    } catch (e) { corps.textContent = 'Fetch failed: ' + (e?.message || e); }
  }
})();

// CHOIX EN BOUTONS (2026-09-29, fenetres simplifiees ; styles .choix dans index2.css). Chaque
// <div class="choix" data-pour="<id>"> pilote une <select> CACHEE du meme formulaire : le code des
// outils lit toujours sa valeur et ecoute son « change ». Les boutons se resynchronisent a chaque
// ouverture de fenetre (une valeur posee par le code, sans evenement, reste affichee juste) et une
// option desactivee desactive son bouton. Identique bureau / web.
function _synchroChoix(racine) {
  (racine || document).querySelectorAll('.choix[data-pour]').forEach(g => {
    const sel = document.getElementById(g.dataset.pour);
    if (!sel) return;
    g.querySelectorAll('.choix-btn').forEach(b => {
      const opt = Array.from(sel.options).find(o => o.value === b.dataset.valeur);
      const actif = sel.value === b.dataset.valeur;
      b.disabled = !opt || opt.disabled;
      b.classList.toggle('actif', actif);
      b.setAttribute('aria-pressed', actif ? 'true' : 'false');
    });
  });
}
document.addEventListener('click', (e) => {
  const b = e.target && e.target.closest ? e.target.closest('.choix[data-pour] .choix-btn') : null;
  if (!b || b.disabled) return;
  const sel = document.getElementById(b.closest('.choix').dataset.pour);
  if (!sel) return;
  if (sel.value !== b.dataset.valeur) {
    sel.value = b.dataset.valeur;
    sel.dispatchEvent(new Event('change', { bubbles: true }));
  }
  _synchroChoix();
});
document.addEventListener('change', (e) => { if (e.target && e.target.tagName === 'SELECT') _synchroChoix(); });
try {
  new MutationObserver((mutations) => {
    for (const m of mutations) {
      const el = m.target;
      if (el.classList && el.classList.contains('modal-overlay') && !el.classList.contains('hidden')) _synchroChoix(el);
    }
  }).observe(document.body, { subtree: true, attributes: true, attributeFilter: ['class'] });
} catch (_) { /* pas d'observateur : les boutons se synchronisent au premier clic */ }
_synchroChoix();

// KIT DES FENETRES (2026-09-29) — habille un reglage de « Mesh tool » comme les autres fenetres :
// case a cocher = option d'une ligne (.opt-ligne) ; liste de 2 a 4 choix = boutons (.choix) qui
// pilotent la liste, cachee (le code lit toujours sa valeur). Identique bureau / web.
function _mtHabiller(wrap, lab, input, spec) {
  if (spec.type === 'checkbox') {
    const ligne = document.createElement('label');
    ligne.className = 'opt-ligne';
    const texte = document.createElement('span');
    const titre = document.createElement('b');
    titre.textContent = spec.label;
    texte.appendChild(titre);
    if (spec.hint) { const s = document.createElement('small'); s.textContent = spec.hint; texte.appendChild(s); }
    lab.style.display = 'none';
    ligne.appendChild(input);
    ligne.appendChild(texte);
    wrap.appendChild(ligne);
    input.__dejaPlace = true;
  } else if (spec.type === 'select' && spec.options && spec.options.length >= 2 && spec.options.length <= 4) {
    if (!input.id) input.id = 'mt-p-' + spec.id;
    input.style.display = 'none';
    const groupe = document.createElement('div');
    groupe.className = 'choix';
    groupe.dataset.pour = input.id;
    spec.options.forEach(([val, lbl]) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'choix-btn';
      b.dataset.valeur = String(val);
      const t = document.createElement('b');
      t.textContent = lbl;
      b.appendChild(t);
      groupe.appendChild(b);
    });
    wrap.appendChild(groupe);
  }
}

// ══ FENETRE DE LANCEMENT (2026-09-29, user : « pas fan des outils qui se lancent juste en un clic : le
// bouton ouvre une fenetre et la on valide le lancement ») ══ Un ecouteur en CAPTURE intercepte le clic
// de ces outils (et d'un choix du menu Style), ouvre #modal-lancement, puis rejoue le clic valide : les
// gestionnaires d'origine ne changent pas, et les clics simules par la visionneuse plein ecran passent
// aussi par la fenetre. Le prix affiche est celui de la pastille du bouton (absente = gratuit).
// Identique bureau / web.
const _OUTILS_A_VALIDER = {
  'ws-removebg-btn': { titre: 'Remove background', texte: 'Cuts the subject out, on a transparent background.', action: 'Remove background', apercu: 'image' },
  'ws-facefix-btn': { titre: 'Face Fix', texte: "Sharpens the face, or an animal's head.", action: 'Fix the face', apercu: 'image' },
  'ws-symmetrize-auto-btn': { titre: 'Auto symmetry', texte: 'Mirrors the left half of the image onto the right half.', action: 'Symmetrize', apercu: 'image' },
  'ws-extend-btn': { titre: 'Extend', texte: 'Adds a margin around the image (15 % on each side).', action: 'Extend', apercu: 'image' },
  'ws-mesh-enhance-tex-btn': { titre: 'Sharpen texture (x2)', texte: 'Doubles the texture resolution, without inventing detail.', action: 'Sharpen', apercu: null },
  'ws-mesh-detail-synth-btn': { titre: 'Detail++', texte: 'Adds fine AI detail to the texture.', action: 'Add detail', apercu: null },
  // outils manuels PAYANTS sur le web (1 credit a l'ouverture) : validation seulement s'il y a un prix
  'ws-picker-btn': { titre: 'Color Pick', texte: 'Opens the colour picker on the image.', action: 'Open', apercu: 'image', siPayant: true },
  // 'ws-lm-manual' (Skeleton points) RETIRE de la liste (2026-09-29, user : « il faut direct ouvrir la page ») : le bouton ouvre
  // lui-meme un editeur, une fenetre de validation avant serait un doublon.
};
function _lctImageCourante() {
  const p = state.currentProject;
  let chemin = null;
  try { chemin = (typeof editTarget === 'function') ? editTarget(p) : null; } catch (_) {}
  chemin = chemin || p?.previewImagePath || p?.selectedImagePath;
  return chemin ? _toFileUrl(chemin) : '';
}
/** Prix affiche dans la fenetre de lancement : celui du bouton de l'outil,
 *  en mode Cloud seulement (en Local ces outils sont gratuits). */
function _prixLancement(boutonPrix) {
  const cloud = (typeof window._computeMode === 'function') && window._computeMode() === 'cloud';
  return (cloud && boutonPrix && window._prixBouton) ? window._prixBouton(boutonPrix.id) : null;
}
function _ouvrirLancement(def, boutonPrix) {
  return new Promise((resoudre) => {
    const m = document.getElementById('modal-lancement');
    if (!m) { resoudre(true); return; }
    const t = (s) => ((typeof _i18nT === 'function') ? _i18nT(s) : s);
    document.getElementById('lct-titre').textContent = def.titreBrut || t(def.titre);
    document.getElementById('lct-texte').textContent = t(def.texte);
    const src = def.apercu === 'image' ? _lctImageCourante() : '';
    document.getElementById('lct-corps').classList.toggle('sans-apercu', !src);
    document.getElementById('lct-apercu').hidden = !src;
    if (src) document.getElementById('lct-image').src = src;
    const lancer = document.getElementById('lct-lancer');
    const annuler = document.getElementById('lct-annuler');
    const fermer = document.getElementById('lct-fermer');
    lancer.textContent = t(def.action);
    // Prix de l'outil LU dans la grille (_prixBouton), en mode Cloud. Le code
    // commun avec le site recopiait une pastille `.cloud-cost-badge` que le
    // bureau ne pose pas : la fenetre n'affichait jamais de prix ici.
    window._posePastille?.(lancer, _prixLancement(boutonPrix));
    const fin = (ok) => {
      m.classList.add('hidden');
      lancer.onclick = annuler.onclick = fermer.onclick = null;
      resoudre(ok);
    };
    lancer.onclick = () => fin(true);
    annuler.onclick = () => fin(false);
    fermer.onclick = () => fin(false);
    m.classList.remove('hidden');
  });
}
document.addEventListener('click', (e) => {
  const cible = e.target && e.target.closest
    ? e.target.closest(Object.keys(_OUTILS_A_VALIDER).map(i => '#' + i).join(',') + ', .style-option')
    : null;
  if (!cible || cible.__lctValide || cible.disabled) return;
  let def = _OUTILS_A_VALIDER[cible.id];
  let boutonPrix = cible;
  if (cible.classList.contains('style-option')) {
    const nom = (cible.textContent || '').trim();
    const t = (s) => ((typeof _i18nT === 'function') ? _i18nT(s) : s);
    def = { titreBrut: t('Style') + ' : ' + nom, texte: 'Repaints the image in this style.', action: 'Apply the style', apercu: 'image' };
    boutonPrix = document.getElementById('ws-style-btn');
  }
  if (!def) return;
  if (def.siPayant && _prixLancement(boutonPrix) == null) return;
  e.stopImmediatePropagation();
  e.preventDefault();
  _ouvrirLancement(def, boutonPrix).then((ok) => {
    if (!ok) return;
    cible.__lctValide = true;
    try { cible.click(); } finally { cible.__lctValide = false; }
  });
}, true);

// ══ KIT DES FENETRES, lot 2b (2026-09-29) ══
// ✕ generique (.fen-fermer) : declenche l'Annuler de la fenetre (meme nettoyage), sinon la masque.
document.addEventListener('click', (e) => {
  const x = e.target && e.target.closest ? e.target.closest('.fen-fermer') : null;
  if (!x) return;
  const m = x.closest('.modal-overlay, .modal');
  // un vrai Annuler / Fermer d'abord (meme nettoyage que ce bouton), sinon le premier bouton discret du pied
  const annuler = m && (m.querySelector('[id$="-cancel"]') || m.querySelector('[id$="-close"]')
    || m.querySelector('.modal-actions .ghost-btn'));
  if (annuler) annuler.click(); else if (m) m.classList.add('hidden');
});
// RESOLUTION : un choix puis « Apply », qui relaie le clic au bouton d'origine (cache). Avant, les deux
// boutons lancaient l'operation des le clic. La taille visee et le prix suivent le choix.
(function () {
  const fen = document.getElementById('modal-resolution');
  const sel = document.getElementById('res-mode');
  const appliquer = document.getElementById('res-apply');
  if (!fen || !sel || !appliquer) return;
  const cible = () => document.getElementById(sel.value === 'down' ? 'res-downscale' : 'res-upscale');
  const maj = () => {
    const c = cible();
    if (!c) return;
    c.dispatchEvent(new Event('mouseenter'));          // affiche « actuelle -> visee » (gestionnaire existant)
    // Prix : grille (_TARIFS_VALIDATION, 'res-apply') — le bureau ne pose pas
    // de pastille sur les boutons caches qu'on recopiait ici.
    window._applyValidationPills?.();
  };
  sel.addEventListener('change', maj);
  appliquer.addEventListener('click', () => cible()?.click());
  try {
    new MutationObserver(() => { if (!fen.classList.contains('hidden')) setTimeout(maj, 0); })
      .observe(fen, { attributes: true, attributeFilter: ['class'] });
  } catch (_) {}
})();

// ══ FENETRE STYLE (2026-09-29, user : « cree un viewer pour Style aussi ») ══ Le bouton Style ouvrait un menu
// deroulant ; il ouvre maintenant une fenetre au gabarit commun. Les styles viennent des .style-option du menu
// (cache, inchange) et « Apply » clique l'option choisie, en sautant la fenetre de lancement (deja validee ici).
// Identique bureau / web.
document.addEventListener('click', (e) => {
  const b = e.target && e.target.closest ? e.target.closest('#ws-style-btn') : null;
  if (!b || b.disabled) return;
  e.stopImmediatePropagation();
  e.preventDefault();
  const m = document.getElementById('modal-style');
  const liste = document.getElementById('sty-liste');
  if (!m || !liste) return;
  const options = Array.from(document.querySelectorAll('.style-option'));
  let choisie = null;
  liste.innerHTML = '';
  options.forEach((opt) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'choix-btn';
    const t = document.createElement('b');
    t.textContent = (opt.textContent || '').trim();
    btn.appendChild(t);
    btn.onclick = () => {
      choisie = opt;
      liste.querySelectorAll('.choix-btn').forEach(x => x.classList.toggle('actif', x === btn));
      document.getElementById('sty-apply').disabled = false;
    };
    liste.appendChild(btn);
  });
  const src = (typeof _lctImageCourante === 'function') ? _lctImageCourante() : '';
  const img = document.getElementById('sty-image');
  if (img && src) img.src = src;
  const appliquer = document.getElementById('sty-apply');
  appliquer.disabled = true;                       // un style a choisir d'abord
  // Prix : grille (_TARIFS_VALIDATION, 'sty-apply' = tarif Modify) — le bureau
  // ne pose pas la pastille `.cloud-cost-badge` qu'on recopiait ici.
  window._applyValidationPills?.();
  const fermer = () => { m.classList.add('hidden'); appliquer.onclick = null; };
  document.getElementById('sty-cancel').onclick = fermer;
  appliquer.onclick = () => {
    if (!choisie) return;
    fermer();
    choisie.__lctValide = true;
    try { choisie.click(); } finally { choisie.__lctValide = false; }
  };
  m.classList.remove('hidden');
}, true);

// FACE FIX selon le type d'objet (2026-09-29, user : « ne doit pas etre visible pour les projets de type
// batiment ») : seulement pour ce qui a un visage ou une tete. Bouton du panneau ET entree de la visionneuse.
// Type inconnu : visible. Verifie chaque seconde (le type change a l'ouverture d'un projet ou au menu).
const _TYPES_AVEC_TETE = new Set(['character', 'creature', 'animal', 'insect', 'other_living']);
function _majFaceFixVisible() {
  const t = String(state.currentProject?.assetType || document.getElementById('ws-asset-type')?.value || '').toLowerCase();
  const visible = !t || _TYPES_AVEC_TETE.has(t);
  document.querySelectorAll('#ws-facefix-btn, [data-lb-tool="facefix"]').forEach((b) => {
    if (b.hidden === !visible) return;
    b.hidden = !visible;
  });
}
setInterval(_majFaceFixVisible, 1000);
document.addEventListener('change', (e) => { if (e.target && e.target.id === 'ws-asset-type') _majFaceFixVisible(); });

/* PROMPT DE GENERATION : la description du user en ROUGE (2026-09-29, user : « il faut mettre en rouge ma
 * description dans le prompt »). Un calque miroir (<pre>, jamais auto-traduit) derriere le champ repete son
 * texte, la partie du user en rouge ; le champ reste editable (texte transparent, curseur visible) et les
 * couleurs suivent la saisie. La partie du user = ce que la GENERATION garde apres stripKnownPromptSuffixes :
 * tout ce qui n'est pas du gabarit. Remplace l'apercu « cliquer pour editer » du bureau apres Enhance.
 * Identique bureau / web. */
(function _promptMiroir() {
  const ta = document.getElementById('ws-prompt');
  if (!ta || ta.__miroir) return;
  ta.__miroir = true;
  let wrap = ta.parentElement;
  if (!wrap.classList.contains('prompt-wrap')) {
    wrap = document.createElement('div');
    ta.parentElement.insertBefore(wrap, ta);
    wrap.appendChild(ta);
  }
  wrap.classList.add('prompt-miroir-wrap');
  const miroir = document.createElement('pre');
  miroir.className = 'prompt-miroir';
  miroir.setAttribute('aria-hidden', 'true');
  miroir.setAttribute('translate', 'no');
  miroir.setAttribute('data-i18n-skip', '');
  wrap.insertBefore(miroir, ta);
  const PROPS = ['fontFamily', 'fontSize', 'fontWeight', 'fontStyle', 'lineHeight', 'letterSpacing', 'wordSpacing',
    'textTransform', 'textIndent', 'tabSize', 'paddingTop', 'paddingBottom', 'paddingLeft',
    'borderTopWidth', 'borderRightWidth', 'borderBottomWidth', 'borderLeftWidth',
    'borderTopLeftRadius', 'borderTopRightRadius', 'borderBottomLeftRadius', 'borderBottomRightRadius'];
  // couleurs lues AVANT que le champ devienne transparent
  const cs0 = getComputedStyle(ta);
  miroir.style.color = cs0.color;
  miroir.style.backgroundColor = cs0.backgroundColor;
  ta.style.caretColor = cs0.color;
  ta.classList.add('prompt-avec-miroir');
  function caler() {
    const cs = getComputedStyle(ta);
    for (const k of PROPS) miroir.style[k] = cs[k];
    // la barre de defilement du champ reduit sa largeur de texte : meme retrait a droite dans le miroir
    const barre = Math.max(0, ta.offsetWidth - ta.clientWidth
      - (parseFloat(cs.borderLeftWidth) || 0) - (parseFloat(cs.borderRightWidth) || 0));
    miroir.style.paddingRight = ((parseFloat(cs.paddingRight) || 0) + barre) + 'px';
    miroir.style.left = ta.offsetLeft + 'px';
    miroir.style.top = ta.offsetTop + 'px';
    miroir.style.width = ta.offsetWidth + 'px';
    miroir.style.height = ta.offsetHeight + 'px';
    miroir.scrollTop = ta.scrollTop;
  }
  const echap = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const estMot = (c) => !!c && /[\p{L}\p{N}_]/u.test(c);
  // premiere occurrence de m a partir de pos, bornee par des non-lettres (« car » ne colore pas « carved »)
  function trouver(bas, m, pos) {
    for (let i = bas.indexOf(m, pos); i >= 0; i = bas.indexOf(m, i + 1)) {
      if (!estMot(bas[i - 1]) && !estMot(bas[i + m.length])) return i;
    }
    return -1;
  }
  function rendre() {
    const v = ta.value || '';
    let user = '';
    try { user = (typeof stripKnownPromptSuffixes === 'function' ? stripKnownPromptSuffixes(v) : v) || ''; } catch (_) {}
    const bas = v.toLowerCase();
    let html = '';
    let pos = 0;
    for (const m of user.split(',').map((x) => x.trim()).filter((x) => x.length > 1)) {
      const i = trouver(bas, m.toLowerCase(), pos);
      if (i < 0) continue;
      html += echap(v.slice(pos, i)) + '<code class="prompt-user">' + echap(v.slice(i, i + m.length)) + '</code>';
      pos = i + m.length;
    }
    html += echap(v.slice(pos));
    miroir.innerHTML = html + (v.endsWith('\n') ? ' ' : '');
    miroir.scrollTop = ta.scrollTop;
  }
  // toute ecriture du champ par le code (pre-rempli, Enhance, projet ouvert) recolore aussi
  const d = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value');
  Object.defineProperty(ta, 'value', {
    configurable: true,
    get() { return d.get.call(this); },
    set(x) { d.set.call(this, x); rendre(); },
  });
  ta.addEventListener('input', rendre);
  ta.addEventListener('scroll', () => { miroir.scrollTop = ta.scrollTop; });
  try { new ResizeObserver(() => { caler(); rendre(); }).observe(ta); } catch (_) {}
  window.addEventListener('resize', caler);
  caler();
  rendre();
})();

// ══ POIDS DE PEAU (2026-09-29, user : « un outil qui colore les parties bougees par chaque os, qu'on puisse
// peindre, et peindre des parties statiques ») : editeur commun lib/editeur-poids.js. Enregistre une NOUVELLE
// version du rig (…_rigged_skinpaint_<ts>.glb a cote du rig d'origine), gratuit sur le bureau.
document.getElementById('ws-rig-poids-btn')?.addEventListener('click', async () => {
  const p = state.currentProject;
  const _r = _rigAffiche();
  const rig = (_r && _r.path) || p?.selectedRigPath || p?.rigs?.[0]?.path;
  if (!rig) { customError(_i18nT('Generate a rig first.'), _i18nT('Skin weights')); return; }
  const buffer = await API.readMeshFile(rig, { complet: true });   // enregistre une version : maillage complet
  if (!buffer) { showToast(_i18nT('Could not read the rig file.'), 'error'); return; }
  const { ouvrirEditeurPoids } = await import('./lib/editeur-poids.js');
  await ouvrirEditeurPoids({
    buffer,
    enregistrer: async (glb) => {
      const src = String(rig).replace(/^file:\/\/\/?/i, '').replace(/[?#].*$/, '');
      const base = src.replace(/\.glb$/i, '').replace(/_rigged_[a-z0-9]+_\d+$/i, '');
      const sortie = `${base}_rigged_skinpaint_${Date.now()}.glb`;
      const r = await API.saveBuffer({ path: sortie, buffer: glb });
      if (!r || !r.success) throw new Error((r && r.error) || 'save failed');
      showToast(_i18nT('Skin weights saved as a new rig version.'), 'success');
      await reloadCurrentProject();
    },
  });
});

// ══ NUMERO DE VERSION (2026-09-29) : petit repere en bas a droite ; le build monte a chaque modification
// (build/ecrire-version.mjs ecrit build-info.js). Survol = date et commit. Identique bureau / web.
(function afficherVersion() {
  const b = window.__BUILD__;
  if (!b || document.getElementById('version-logiciel')) return;
  const el = document.createElement('div');
  el.id = 'version-logiciel';
  el.setAttribute('data-i18n-skip', ''); el.setAttribute('translate', 'no');
  el.textContent = `v${b.version} · build ${b.build}${b.sale ? '*' : ''}`;
  el.title = `${b.date} · ${b.hash}${b.sale ? ' · unsaved changes' : ''}`;
  document.body.appendChild(el);
})();

// ══ JOURNAL DES MODIFICATIONS (2026-09-29, user : « si je clique sur la version, une popup avec les derniers changements ») :
// clic sur le numero de version = liste des derniers commits (build-info.js, ecrit par build/ecrire-version.mjs).
function ouvrirJournalVersion() {
  const b = window.__BUILD__; if (!b) return;
  const t = (s) => ((typeof _i18nT === 'function') ? _i18nT(s) : s);
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  document.getElementById('modal-journal')?.remove();
  const m = document.createElement('div');
  m.id = 'modal-journal'; m.className = 'modal-overlay'; m.setAttribute('data-i18n-skip', '');
  // groupe par version (titre), puis par jour ; les versions anciennes sont repliees
  const groupes = []; (b.journal || []).forEach((j) => { const v = j.v || b.version; let g = groupes[groupes.length - 1]; if (!g || g.v !== v) { g = { v, jours: [] }; groupes.push(g); } let jr = g.jours[g.jours.length - 1]; if (!jr || jr.d !== j.d) { jr = { d: j.d, l: [] }; g.jours.push(jr); } jr.l.push({ t: j.t, n: j.n }); });
  const lignes = groupes.map((g, gi) => `<details class="mj-version"${gi === 0 ? ' open' : ''}><summary>v${esc(g.v)} <span class="mj-n">${g.jours.reduce((n, x) => n + x.l.length, 0)}</span></summary>${g.jours.map((jr) => `<div class="mj-jour">${esc(jr.d)}</div><ul class="mj-liste">${jr.l.map((x) => `<li><span class="mj-build">${x.n ? '#' + esc(x.n) : ''}</span><span class="mj-txt">${esc(x.t)}</span></li>`).join('')}</ul>`).join('')}</details>`).join('');
  m.innerHTML = `<div class="modal-card" style="max-width:680px;width:92vw;">
    <div class="fen-tete"><h2>${esc(t('Latest changes'))}</h2><button type="button" class="settings-close-x" id="mj-close" title="Close">&#10005;</button></div>
    <p class="modal-subtitle">v${esc(b.version)} · build ${esc(b.build)}${b.sale ? ' *' : ''} · ${esc(b.date)} · ${esc(b.hash)}${b.sale ? ' — ' + esc(t('changes in progress, not yet saved')) : ''}</p>
    <div class="mj-corps">${lignes || '—'}</div>
    <div class="modal-actions"><button class="primary-btn" id="mj-ok">${esc(t('Close'))}</button></div></div>`;
  document.body.appendChild(m);
  const fermer = () => { m.remove(); document.removeEventListener('keydown', echap); };
  const echap = (e) => { if (e.key === 'Escape') fermer(); };
  document.addEventListener('keydown', echap);
  m.addEventListener('click', (e) => { if (e.target === m) fermer(); });
  m.querySelector('#mj-close').onclick = fermer; m.querySelector('#mj-ok').onclick = fermer;
}
(function activerJournalVersion() {
  const el = document.getElementById('version-logiciel');
  if (el) { el.style.cursor = 'pointer'; el.style.pointerEvents = 'auto'; el.onclick = ouvrirJournalVersion; }
})();
